/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20111012-4","meetingId":"h23-c-settlement","date":"2011年10月12日","dateIso":"2011-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","topics":[{"id":"topic-01","title":"◯石田（秀）委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２２年度品川区一般会計歳入歳出決算","agenda":"◯石田（秀）委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"１６６ページの建築確認事務、それから１５７ページの駅周辺等放置自転車対策費、１６５ページの避難道路機能強化事業についてお伺いします。民間の建築確認の事業者と区の審査との違いはどうなっているのか。例えば、日数は今、大して変わらないと以前もお話がありましたけれども、日数が実際どれぐらい違って、費用の差はどれぐらいあるのかということをお伺いさせていただきたいと思います。","respondent":"中村建築課長","answer":"約２.７日の差があります。それと料金ですけれども、こちらは区の確認申請料が一番今安いという認識でおります。民間の確認検査機関は、その倍あるいは３倍近く設定されているところもあります。こういったことにつきまして、どう考えているかということ……。","id":"exchange-001"},{"speaker":"沢田委員","kind":"確認","question":"日数はほとんど民間と二、三日程度の違いということで、また費用は逆に２倍、３倍という大変差がある中で、区への確認申請は減っていて、一方で相談件数だけは増えているというのは、そういういろんな事情があると思うんですが、ちょっと疑問なところがあるんですけども、よく前から言われていますけれども、民間の検査機関の中には、マンションの建築主が株主だったり。","respondent":"山崎マスタープラン担当課長","answer":"ハード系の指導ということに加えまして、居住後のコミュニケーションを確保するというような、引っ越しをされてきた方が柔軟に住民の方と一定の良好なコミュニケーション、町会の加入でありますとか、先ほど申し上げた区としましては。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"建築確認のこういった申請の減少によって、区にいる専門の職員の方たちがいらっしゃると思うんですけれども、そういった方たちの技術的なレベルの低下というか、建築確認申請が減っていることによる低下というのもあるのかなと思うんですけども、こういったことについては、どういった対応、人数は結構いらっしゃるかもしれないんですが、そういった対応はどうされているのでしょうか。","respondent":"中村建築課長","answer":"今、相談件数が大分増えているという現象がございまして、建築基準法の中で、判断に苦慮する非常に難しいケースがたくさんあります。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"あわせて、大変これは歩道にあって、結構そんなに広い歩道じゃないので、歩行者の安全対策ということもどうされているのかなというのが気になっていたのと、あと阪急の駐輪場と何か混乱されている方がいらして、そういうこともあったので、そういったことに対する対策はどのようになっているのかというのをお伺いさせていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"しかしながら、事故の可能性が全くないということではございませんので、区のほうで委託しております指導啓発要員などを配置するほか、あと阪急のと混同しないように看板を設置して、ここは阪急の駐輪場ではないということを明確にするような措置をとっているところです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"あそこはすごく人通りも多くて安全対策という意味で歩道も狭いので、ぜひ進めていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"現在も停電してしまった場合、一切非常電源のようなものをメーカーのほうで備えていないものばかりしかないということなので、この辺がネックとなっておりますので、この辺の問題がクリアされてから、機械の成熟を待ってから検討ということになると思います。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"１６５ページの避難道路機能強化事業、滝王子の避難道路の強化についてなんですけれども、何度かお伺いしているんですが、平成２１年から平成３０年までの事業期間ということで、７.３ｍの道を１０ｍということですけれども、改めてこの事業の意味と、実際に対象の物件や建物は何軒あるのかということをお伺いしたいんですけれども、お願いいたします。","respondent":"品川防災整備担当課長","answer":"現在平成２１年から事業を始めまして、平成３０年までということですが、拡幅に必要な棟数ですが、１３５棟となっております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"１３５棟ということで、この３年間で３件の物件の買収ですけども、あと８年間でどれだけできるのかなというのはすごい疑問なので、やるからにはちゃんとやっていただきたいと思うんですけど、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鶴委員","kind":"確認","question":"私のほうからは、成果報告書１６３ページの公園・児童遊園維持管理費、それから１６７ページの区営住宅管理費についてお尋ねをいたします。公園・児童遊園維持管理費について、確認ですが、公園、児童遊園また防災活動広場の現在数を教えてください。成果報告書の記載の数字と事務事業概要の数字は、タイムラグの関係かと思いますけれども、数字が違いますのでよろしくお願いいたします。","respondent":"稲田道路公園課長","answer":"現在の品川区の公園、児童遊園、防災活動広場等々の数です。公園は、現在１４２カ所、それから児童遊園が６７カ所です。それから、防災活動広場、水辺広場、開放広場とひとくくりになっておりますが、３６カ所です。","id":"exchange-008"},{"speaker":"鶴委員","kind":"確認","question":"かつて震災直後に問い合わせしたときに、結構、防災活動広場とか、要するに所管が違ったりして、教えていただいた数字が違ったということがかつてありましたので、改めて今確認をさせていただきました。それで、今ご報告いただいたうち電源引込盤、いわゆるイベント等で電源供給が可能なイベントコンセント、それが設置されている箇所は何カ所ぐらいありますでしょうか。","respondent":"稲田道路公園課長","answer":"私どもの公園の中で、外部でコンセントに差して電気が利用できるという公園ですが、４公園あります。しながわ中央公園、戸越公園、戸越公園はステージ周りですね。それから東品川海上公園、鮫洲運動公園の４カ所です。","id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"４カ所ということで報告をいただきました。そこで、提案ですけれども、先ほどご答弁いただいた４カ所以外、未整備の箇所、相当数になると思いますが、防災上の観点もあわせて、順次こうしたイベント時にもお使いいただけるように電源引込盤、イベントコンセントを整備されてはいかがでしょうか。既設の箇所で、これまでに地域のイベントなどで電源を利用された公園などがあれば、教えてください。","respondent":"稲田道路公園課長","answer":"一方で、仮設電源というのを引くというふうになりますと、１万円程度の引込料金に設備代等で六、七万円ではないかというふうに思われておりますが、地域の方の利用しやすい公園ということを目指しておりますので、今後ちょっとこの辺も研究していきたいなと考えています。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"今ご答弁いただいたようにランニングコストがそれぞれかかる面もありますけれども、要望の多い地域については、積極的な検討をお願いしたいと思います。次に、区営住宅管理費についてお尋ねをいたします。最初に、区営住宅１３団地、１６棟のうち、エレベータが設置されている棟を教えてください。こうした設置に当たっては、何か基準みたいなものがあるんでしょうか、教えてください。","respondent":"柏原住宅担当課長","answer":"こちらのほう、エレベータの設置ですが、品川区としましては、内規ではありますけれども、４階建て以上の建物で、それから設置をした際に法令等に違反をしない、それから、いろいろな施設が合同で入っているようなところには。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"西中延区営住宅の住民の方のお話によると、今現在入居している４７世帯のうち、８割近い方が６５歳以上の高齢者であるというふうに聞いております。こうした現状を受けて、この西中延区営住宅へのエレベータの設置について、平成２１年度の予算特別委員会における公明党の議員の質問に対して、容積率との関係で設置は難しい。","respondent":"柏原住宅担当課長","answer":"西中延の区営住宅のエレベータの件です。我々もこちらのほうの住宅は高齢者が多くなっているというのは認識しています。そういったところから、エレベータの設置については、さまざまな角度から検討してまいりました。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問","question":"平成２３年度には、新規事業として区営住宅の長寿命化計画の策定に向けた住宅の現況調査等のための予算が計上され、執行されていると伺っております。平成２４年度には耐震補強改修工事が予定されていることも伺っております。そこでお尋ねいたしますが、西中延区営住宅に耐震補強改修工事をした場合、概算で結構ですので経費はどのくらいになるか教えてください。","respondent":"柏原住宅担当課長","answer":"まだ設計半ばですので、正確な数字というのは、なかなか申し上げづらいんですが、現在やっております例えば二葉一丁目であるとか、それから荏原七丁目等々の耐震化工事から申しますと、１億円から２億円以上はかかるんではないかというふうに考えてあります。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"その上でお尋ねいたします。公営住宅法第３５条、ここには「地方公共団体は、公営住宅の整備を促進し、又は公営住宅の居住環境を整備するため必要があるときは、公営住宅建替事業を施行するように努めなければならない」とあります。西中延区営住宅は、この第３６条第２号でうたわれている耐用年数の２分の１を超えているか教えてください。","respondent":"柏原住宅担当課長","answer":"公営住宅法上、そのような規定になっており、委員ご指摘のとおりです。こちらのほうは、築年次が昭和４１年度ですので、一般的に申しますと、そういった時期に入っているというふうに考えられると思います。","id":"exchange-014"},{"speaker":"鶴委員","kind":"質問","question":"ということは、区営住宅の長寿命化計画とか、また先ほどお尋ねいたしました耐震補強改修工事、こうした関係で見ても、仮に建て替えをした場合の費用対効果、また耐用年数に関して、もちろんこの入居者の理解というのが前提であるというふうに考えますけれども、建て替えをしたほうがメリットが大きいのではないかなと思います。","respondent":"柏原住宅担当課長","answer":"建て替えというお話になりますと、居住者の方がいらっしゃいますので、こちらのほうの仮住まいであるとかというところも出てくると思います。工事期間につきましては、都営住宅の例を見ますと、２年近くはかかるんではないかというふうに考えてあります。","id":"exchange-015"},{"speaker":"鶴委員","kind":"質問・要望","question":"時間がないので最後に要望ですけれども、先日特別養護老人ホームを含めた検討がございました。既存の建物の機能もしっかりと活かしていただきながら、複合施設も検討していただきたい、このように思いますので、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"１５９ページの涼のみち整備事業、そして１５７ページの交通安全啓発費、１６１ページの河川管理費の浄化対策についてご質問いたします。最初に、１５９ページの下から３行目の涼のみち整備事業についての質問です。涼のみち整備事業に、３,２３２万５,０６４円とありますが、この事業とはどういうことなんでしょうか、ご説明ください。","respondent":"稲田道路公園課長","answer":"品川区では、道路の保水性舗装、遮熱性舗装という種類の舗装をつくりまして、昼間の気温の上昇の抑制効果がある舗装を導入しまして、道路の温度を下げて、涼しさを感じる涼のみち整備事業として取り組んでいるものです。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問","question":"この名のとおり涼のみちですから、道路の表面の温度を特殊な塗料を塗ることによって道路の表面温度を下げる事業ということがよくわかります。このやり方は１種類だけなんでしょうか、それとも何種類かあるのか。そして、その効果のほどを教えていただきます。お願いします。","respondent":"稲田道路公園課長","answer":"こちらの効果なんですが、遮熱性舗装、塗料を塗るほうはマイナス１１.７度の低減効果があったというふうに私どもの実験では効果を確認しております。保水性舗装におきましても、マイナス７.１度というような結果を得ております。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"私たち大人は道路から離れているので、大分背丈がありますので何とかなるんですけれども、小さな子どもたちは大変路面に近いものですから５０度近い熱を感じているはずだと思います。水まきには、おふろの水でも十分だということで、残り湯の水で十分ということですけれども、水まきをする時間帯、これは午前がいいのか、それとも午後がいいのか、大体何時ごろがいいのかわかりましたら教えてください。","respondent":"稲田道路公園課長","answer":"１平米当たりの単価ということでお知らせしたいと思います。遮熱性舗装ですが、これは塗料を塗りますのに１平米１万２,０００円程度です。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"この事業は、平成１７年度から調査をし、平成１８年度から正式に事業化したわけですが、年間にどれぐらいの道路の舗装を実施するお考えですか。それには何か問題点や何らかの理由があるのでしょうか。都道は東京都がやるということ、そして区道は本区がやるということですが、区道をすべて終わらせるにはどれぐらいの年数がかかるか教えていただけたらうれしいです。","respondent":"稲田道路公園課長","answer":"平成２３年度は遮熱性舗装、塗料を塗るほうのみですが、西小山駅前広場、ロータリーのところを７３９m2既に実施しております。ということで、価格の違いなんですが、これは商店街等の保水性舗装を今年はちょっとやっていないというところで差が出てあります。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"真夏時には道路だけではなく、今度はビルや建物自体が熱を持ってきます。日中に建物の壁に照りつけた熱というんですかね、その熱が時間をかけてじわりじわりと内側に熱が伝わるということで、部屋の温度が夜でも日中と変わらないぐらいになるです。熱中症を防ぐためにも、建物の壁にそういう特殊塗装をする。現在そのような事例がこの品川区にはありますか。お願いします。","respondent":"中村建築課長","answer":"外壁の仕上げにつきましては、確認申請のときに仕様がそこに書かれておりますけれども、特に遮熱性能そのものが審査の基準になっておりませんので、現状では把握はしておりません。","id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"続きまして、先日歳入で質問いたしましたけれども、今度は１５７ページ、中段の少し下ですが、交通安全啓発費と駅周辺等放置自転車対策について質問いたします。普及啓発経費の主な使われ方についてご説明を願います。","respondent":"藤木交通安全担当課長","answer":"高齢者や自転車の交通安全教室の開催ですとか、あと広報関係では、広報紙の作成、また交通安全に関する資機材の購入ですとか、広報啓発看板の設置にかかる費用等です。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"ただいまのご説明の中に高齢者の交通安全教室とありましたが、具体的にはどのようなことを行っているのか、そしてその効果のほどはいかがですか。本区で年間高齢者が事故に遭う、また巻き込まれる件数や人数、また特別な例としては、死に至ってしまうケースなどもあると思いますけれども、おわかりになりましたらお願いいたします。","respondent":"藤木交通安全担当課長","answer":"参考までに、昨年の交通事故につきましては、全体で１,３０６件、平成２２年中に交通事故が発生しているんですが、そのうち高齢者の方が絡んだのが３５２件という統計が出ております。","id":"exchange-023"},{"speaker":"木村委員","kind":"質問・要望","question":"講習だけではなく自分で体験をしてもらうということ、これは交通安全に効果的だと思います。ぜひそのように進めていただきたいと思います。次に交通安全協会補助金４９０万円とありますが、交通安全協会とはどのような団体で、どのような活動をしているのか、わかっているようでなかなかよくわからないところがありますので、ご説明をいただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"交通安全協会についてですが、こちらの団体は地域の住民ですとか、地域の企業からなります任意の団体でございまして、法人格等はございません。ボランティアの団体です。おおむね警察署単位で設置されておりまして、品川、大崎、大井、荏原各警察署に交通安全協会があります。","id":"exchange-024"},{"speaker":"木村委員","kind":"質問","question":"時間が余りないので、今度は１６１ページの浄化対策、河川費についてです。我が区には２本の河川、立会川と目黒川がありますが、汚れた工業用水や家庭から出る汚水によって川自体が汚れがちになっていますが、現在の川の状況はいかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"しかしながら、まだまだ品川区内の河川の中には余り好ましくないにおいがしたり、あるいは白く濁ったりということで、まだまだそういうような状況もありますので、今後も河川の浄化対策については進めていく必要があるというふうに感じてあります。","id":"exchange-025"},{"speaker":"木村委員","kind":"質問","question":"私も二十数年前に立会川の近くに住んでいたんですが、きれいな川というよりは、水かさの少ない川というイメージでした。何年になるんでしょうか、一時ボラの大群が川いっぱいに来たことがありましたけれども、当時のテレビのニュースなどで取り上げられました。あの現象はどうして起こったのでしょうか。あれ以来、何かそういうような変わった出来事というのはありますか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"立会川のほうですけれども、平成７年だったと思うんですけれども、立会川のほうにはＪＲの東京駅等から水を引っ張ってきて、今そこの地下水を流しています。補足します。立会川だけではありませんで、東京湾の中小河川みんなに上ってきたんですね。","id":"exchange-026"},{"speaker":"木村委員","kind":"質問","question":"魚の勘違いなのか、自然現象ですね。どうも失礼をいたしました。これから作業をやるわけですけれども、一度の浄化作業で大体どれぐらいの期間もつのか。そして、１６１ページの下から４番、５番目ぐらいに水質改善実験費というのがありますが、浄化以外に何を実験しているのか、わかりやすく教えてください。","respondent":"藤田水とみどりの課長","answer":"その下の水質改善調査費ということで掲載していますのは、その実験で出てきたデータ、これをもとに机の上でいろいろデータの分析をするということで、平成２２年度については行ったものです。","id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"わかりました。先日台風１５号がもたらした雨量、これは立会川の警戒水域を超える警報が出された。水域を超えるというのか、警報が出されましたけれども、大きな被害には至りませんでしたが、最近の雨は広範囲に降るんではなくて、集中的に降る傾向があるというお話を聞きました。そのような傾向を実際に感じられますか。","respondent":"藤田水とみどりの課長","answer":"河川の状況を見ていますと、例えば立会川の現地で確認をしていると、実際にそこでは雨が降っていない、しかしながら、河川の水位が上昇してくるということで、上流のほうで雨が降るとその水が河川に流れ込んできて水位が上昇するという現象がやはり見られますので。","id":"exchange-028"},{"speaker":"木村委員","kind":"意見","question":"友人に立会川のそばに住んでいる人がいるんですけれども、その方から川からではなくて、川に注ぐ下水道から悪臭がするということを言われました。下水道の能力と川との関係、もし、もう時間がありませんね。ということで、終わりにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"成果報告書１６４ページの市街地整備事業費より、再開発事業について伺いたいと思います。区役所近くの一本橋の開発も次々とビルが高くなっておりますけれども、区内各地でこうした大型公共事業が進んでおります。伺いたいことは、平成２２年度末までに完成した地区、総住宅戸数、オフィスビルについて業務系のビルが何平米か、税金による補助支援が幾らか、それぞれ合計を伺いたいと思います。","respondent":"三宅都市開発課長","answer":"補助支援の額としましては、約５３０億円です。それから、今後の見込みですけれども、都市計画決定を経まして、計画中あるいは工事中のもの、現在４地区ございまして、そこでは約２,２００戸の住宅と約２７万m2の業務系の床を整備する予定です。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"西品川一丁目地区ですけれども、先日のアセスメントの資料を私も見させていただきましたが、そこでは住宅が４６０戸、業務系の床が２１万８,０００m2でした。伺いたいのは、こうした計画を一体いつまで続けるのか、どこまで続けるのか、今後の計画を伺いたいと思います。","respondent":"三宅都市開発課長","answer":"もう少し広く見ますと、再開発事業というのは、市街地整備基本方針で定めます都市活性化拠点や、地域生活拠点を中心に進められておりますけれども、これらの拠点はその周囲から多くの人々が集まる場所でございまして、それぞれの地域の牽引役。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"続く限りはこれからも進めていきたいと、そういうご説明だと思います。再開発マンションだけでもあわせると６,１６０戸、これは八潮の住宅戸数を大きく上回る、そういう状態です。業務系ビルだけでも１０８万m2、ざっと見たら東京ドームの２.３倍でした。ぜひここを伺いたいのと、そう考える理由もあわせてご説明いただきたいと思います。","respondent":"三宅都市開発課長","answer":"再開発事業につきましては、先ほどの答弁と少し重複しますけれども、やはり道路など、公開空地など、そうした整備を進めるものであるということと、市街地整備基本方針に基づいて、各地区の拠点となるような地域の整備の促進を図ることによって品川区の活性化を図っていくと。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"どうして再開発マンションばかりができるのかと、大体税金が使われる意味がわからない、そうした声をたくさん伺います。直近の品川区の世論調査を見ても、再開発による地域整備はわずかに４％です。これ以上の高層ビル、マンションはやめてほしい、これが率直な区民の思いだと思いますけれども、なぜ望んでもいない事業を進めるのか、逆にこれがなぜ望んでいると区は考えるのか、そこを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"基本的には市街地整備基本方針で位置づけております、その拠点というエリアを中心に進めていきたいと考えておりますので、低層住宅市街地などで、そのど真ん中で高層住宅ですとか、そういうオフィスビルを建てるというような考えは持ってございません。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"区民が望んでいるのかと伺うと、一生懸命必要性を説明するわけです。しかし、必要だというのであれば、では、どういう行政需要の見通しを持っているのか、そこを伺いたいと思います。品川区はこの行政需要が一体どこにあると考えているのか伺いたい。そして、このマンション建設やオフィスビル建設について、行政需要のピークというのは、一体いつだと考えているのか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"住宅やオフィスのニーズに関するお尋ねです。基本的に市街地整備基本方針で定めてあります都市活性化拠点など、交通の利便性の高い場所においては、社会情勢が変動いたしましても、特性によりまして、その住宅ですとかオフィスのニーズは基本的に高いと考えています。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"今日的に考えると、東日本大震災が起きました。こうした傾向については加味しないということなのか、行政需要にどういう影響を与えると考えているのか伺いたいと思います。結局は、どういう行政需要かはっきりしないのに、具体化しているのは計画だけ、これでは公共事業となぜ呼べるのか、そこにどうして税金を入れるのか、私はとても区民が望んでいないということだと思いますけれども、いかがでしょうか。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"今回の大震災では、超高層住宅自体の安全性に問題はありませんでしたけれども、居住性の面で改善の余地があるとは考えてあります。それぞれの地域の特性を踏まえて、それぞれのまちづくりの更新をしていくというのは当然の話だと考えています。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"まちが新陳代謝をするということはそのとおりだと思います。じゃあ、何で大きいビルになるのかと。しかも品川区民はそれを望んでいるのかと。私は望んでいないと思います。先ほど子育て世代の定住化というお話がありましたが、ならば、これまでにつくった３,５００戸の住宅、２,６００戸の住宅、これが完売する見通しがあると思っているのか最後に伺いたいと思います。","respondent":"三宅都市開発課長","answer":"多少時間はかかりましても、完売すると考えております。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"１５７ページ、交通安全啓発と駅周辺等放置自転車対策、１５８ページの補助２０５号線整備についてお伺いをします。交通安全のほうでお伺いしますが、交通安全担当課長は、警視庁から派遣をしていただいておりますが、改めて警視庁ではどんな仕事を担当していたか、具体的に教えてください。","respondent":"藤木交通安全担当課長","answer":"私はここの前は新宿警察署の交通課長をやっておりまして、その前は警視庁の交通部で主に自転車の交通安全対策などを担当しておりました。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"ものすごくモチベーション高く品川区に来て、品川区の自転車対策、安全も含めてやっていこうという熱き思いで品川区に来られたというふうに私は思っております。品川区内の自転車のマナーなんですけれども、余りいいとは言われていないんですが、その辺の苦労がどういうふうにあったかということを伺います。","respondent":"藤木交通安全担当課長","answer":"警視庁のときにも自転車のサイクリング協会ですとか、そういうところと一緒に安全教室をやりましたけど、そういう自転車の専門家みたいな人たち、そういう対策なんかも必要ではないかと考えております。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"そこで、改めてお伺いするんですけれども、そういう思いで課長は品川区に来たと思うんですね。自転車はいいですよという協会じゃないですか。そういう思いで品川区に来たら、品川区の基本方針を聞いて、ちょっと驚いちゃったと思うんですけれども、その辺についてはいかがでしょうか。","respondent":"藤木交通安全担当課長","answer":"委員おっしゃっている品川区の基本というのは、不要不急の場合の自転車の利用は自粛をしなさいと、このようなことだという認識の上で発言しますが、区内におきましては、特に狭い道路などが非常に多いと、また自転車、歩行者が交錯して、交通量が非常に多いということで。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"現実はそこなんですよね。駅の放置自転車対策とか安全対策とかを一生懸命やる。やっぱり、ここの基本的な、品川区は自転車を乗るのをやめましょうという基本的なところを変えないと、私はちょっと時代に合っていないんじゃないかと思うんですけれども、この辺については、担当課長、政策的には部長だと思うんですけれども、この辺で変えていかないといけないという思いがあるんですけど、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"自転車で行かなきゃいけないところは自転車を利用してもらうしか仕方がないんですけども、でもそのときは、きちっと道路交通法の車両に当たりますから、交通ルールをきちっと守っていただいて、安全に利用していただきたいというのが品川区の基本の考え方です。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"これはやりますが、一般の区民の方は、そういう説明ではわからないと思いますよ、やっぱり自転車は楽だから。次は補助２０５号線整備に行きますけれども、私はこれを何年もずっと追い続けていますが、例の私の近所の信号の件でお伺いしますが、今の状況をお知らせください。","respondent":"武藤都市整備下水道課長","answer":"補助２０５号線の交差点の信号機設置の改良のお尋ねですけれども、委員ご指摘のとおり、当該交差点につきましては現在信号がなく、自動車と歩行者、また自転車等の交通が入り乱れる形で危険な状態というふうには認識しております。","id":"exchange-041"},{"speaker":"藤原委員","kind":"意見","question":"毎回答弁が所轄の警察に上げているというんですけれども、もっと区でできる具体的な案というのがあると思うんですよ。警察に上げるだけじゃなくて、設計の問題とか、その辺については、区としてどういうふうに考えていますか。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり、所管の交通管理者との調整の中では、信号機設置につきまして、所管のほうでは交通量の問題から設置はなかなか厳しいかもしれないけれどもということが１点。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問・要望","question":"私が住んでいる町会の町会長からも区政協でこの信号機のことについては上げさせていただいたと思いますが、まだちょっと弱いんですよ、答弁が。ここまで来て、期は熟したという感じなんで、これはやるしかないと私は住んでいる地元議員として、どうしてもここで訴えをさせていただきたいもので、その辺を考慮して、ちょっと答弁をまたお願いいたします。","respondent":"武藤都市整備下水道課長","answer":"繰り返しで恐縮ですが、委員の強いご指摘のとおり、この交差点につきましては、我々としても信号機を設置してもらえるよう、先ほどの設計の配慮を引き続き行いまして、再度強く交通管理者に要望を行っていきたいと考えています。","id":"exchange-043"},{"speaker":"阿久津委員","kind":"確認","question":"１点目の八ツ山・元なぎさ通り整備基本設計委託なんですが、１６０ページによりますと、全長２.４kmあるんですけれども、１区間とあるんですが、その１区間、確認のため、どの部分か教えてください。","respondent":"武藤都市整備下水道課長","answer":"本事業につきましては、八ツ山通りおよび元なぎさ通りの全体の区間について検討を行っております。今お問い合わせのその１の設計の区間につきましては、その一番南側の区間、元なぎさ通りの一番南側の鮫洲運動公園の付近の設計の区間になっております。","id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問・要望","question":"我が会派では、平成６年から、直近では平成２２年の第２回定例会まで、この八ツ山・元なぎさ通りの整備事業について質問とご要望をしています。３点お伺いをします。１点目は、この新品川橋地域の整備基本設計というのは、いつごろ予定をされているんでしょうか。２点目に、この整備基本設計にこうした区民の要望とか安全に対する対策というのは反映をされるんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"１点目の新品川橋付近については、いつごろ具体的な設計に取り組むかというご質問についてですけれども、先ほど申しましたように、現時点では元なぎさ通りの一番南側から今設計をしておりまして、順次北側を検討していきたいと考えています。","id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問・要望","question":"何度もこれは要望させていただいているんですが、これも定例会でのご答弁、防災まちづくり事業部長のご答弁の中で、さらなる利便性の向上に向けて、引き続き鉄道事業者と協議を重ねていくというようなご答弁をいただいておりますけれども、今年の２月２５日のご答弁ということで、まだ８カ月しかたっておりませんが、８カ月たっているといえばたっておりますので。","respondent":"山崎マスタープラン担当課長","answer":"今回北口にバリアフリー新法によるワンルート確保の観点ということで設置をさせていただいたものですけれども、南口のエスカレーターについて、車いす対応型に改良する等々の、一定の利便性の改善をさせていただいてきているところです。","id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問・要望","question":"エスカレーターの設置、車いすに対応しているエスカレーターを設置していただいているということですけれども、これも地元の要望が強いので、鉄道事業者との協議をぜひお願いいたします。続きまして１６２ページ、まちづくりマスタープラン推進費、あと品川浦周辺地区まちづくり推進費に関しまして、ちょっとあれなんですが、総合特区について伺います。","respondent":"山崎マスタープラン担当課長","answer":"お尋ねの総合特別区域、特区の件です。品川駅周辺地域が羽田空港とリニア中央新幹線の結節線として今後重要な地域であるということで、エリア指定の予定になってあります。","id":"exchange-047"},{"speaker":"阿久津委員","kind":"提案","question":"この特区について、国への主な提案としてビジネス支援、例えば外国法律事務弁護士の規制緩和とか外国人留学生に対する就労ビザの緩和、これが今回品川のところに当たっているかどうかはちょっとわからないんですけれども、いろんな提案がされております。本区のマスタープラン、既存のマスタープラン、これからのマスタープランやまちづくり計画にどのように影響していくのか教えてください。","respondent":"山崎マスタープラン担当課長","answer":"東京都あるいは国のほうから先ほど申し上げた理由で、品川駅周辺の地域的なポテンシャルの高まりというようなことで認識しています。そうした観点は、品川区におきましても同様です。","id":"exchange-048"},{"speaker":"阿久津委員","kind":"提案","question":"非常にいいチャンスだと思います。この前、一般質問でもご提案させていただきましたけれども、特に品川浦地域、旧東海道地域、都市の景観と伝統的な街並みが非常にマッチした魅力的な地域でありますし、ぜひそういった玄関口として、こちらの旧東海道、品川区に人が流れるように、ぜひそういったご提案、またそういう働きかけをしていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"委員おっしゃるとおり、残念ながら利用件数０件ということで、執行がございません。","id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これはネットでもやっていましたし、私も報道で見ました。このシェルターの助成というのは、東京都の助成があって、なかなかこういったものに直接使うというのは難しいかもしれないんですけれども、本区は海に面しておりますので、ぜひこういったものを独自に研究されて、助成をしていただきたいと思うんですが、これについてのご見解を伺います。","respondent":"品川防災整備担当課長","answer":"それで、この津波のシェルターなんですが、耐震とまたどう絡むかとか、そういうところも非常に問題はあると思いますが、今回の３・１１で、津波がすごく注目の高いものとなっておりますので、こういうシェルターの購入状況。","id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"私は１５７ページの交通安全啓発費、同じく自転車を中心に伺っていこうと思います。やはり直接事故にならなくても、怖いねとか、いろんな話題を目にしたり、耳にしたりします。そういう中で、車の事故についてはいろんな資料を見ると減少傾向にある。そういう中で、今現在この品川区の交通安全の計画の中で重点政策は何かまず伺いたいと思います。","respondent":"藤木交通安全担当課長","answer":"委員おっしゃるとおり、自転車につきましても、当区でも重要な交通安全上の課題ということで認識しております。","id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問","question":"事故のイメージというと、やはり車がどうしても主体でとらえがちだったと思います。それを裏付けるようなデータ等があれば教えてください。それとあと、ごく最近ですが、やはりテレビなんかでもスポーツ型の自転車というんですか、ピストバイク等の取り締まりが強化されているという報道もありました。","respondent":"藤木交通安全担当課長","answer":"ピストバイクという、これも若者が乗っていたり、中年層が乗っていたり、いろいろな方が乗られていますけれど、もちろんこの自転車自体がブレーキがついていないことで、それだけで整備不良に当たりますし、最近流行してきているということで。","id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"聞こうと思っていた特にという年代のところ、２０代、３０代、４０代という中で、主に取り締まりはもちろん警察だと思います。そういう中で、やはり未然に防ぐ仕組みという点で、区がやるべきこと、あるいは区が警察と協力してやるという視点で、現在の自転車利用の対策の取り組みを教えてください。","respondent":"藤木交通安全担当課長","answer":"街頭で、これも警察と一緒なんですが、広報啓発のキャンペーンですとか、あるいは広報紙の発行、また区のほうで予算立ていたしまして、平成２１年からスタントマンによる交通事故再現を中心とする交通安全教育などを導入いたしまして、現在、事故防止対策を推進しています。","id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"そもそも自転車運転マナーはなぜよくないのかという中で、もちろん今だけの話ではないかと思うんですが、当然一部の人の話であって、多くの方は守られているかと思います。そういう中で、今考えられることとしたら、責任というのをキーワードに考えると、先ほどの質問でも答弁がありました。責任について軽い意識ではないかという指摘もあるかと思います。それと責任といっても幾つかあると思います。","respondent":"藤木交通安全担当課長","answer":"若干正確ではないところがあるんですが、これは神奈川県のほうの裁判例だったと思います。携帯電話をしながら夜間自転車に乗っていた女子高生が、前方を歩いていたたしか看護師の女性に衝突しまして、５,０００万円を超える損害賠償命令が出たというふうに記憶しております。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問","question":"そこで、ちょっと伺いたいんですが、法的な面もあるという中で、未然に防ぐということと、あと区のかかわりという中で、交通安全を目的としたカメラ、こういう考え方は定点で設置する場合もあるでしょうし、ぱっと浮かぶ中で、高速道路のスピードの取り締まりがあるように、同じく、仮の話なんですが、公的にはどうか伺いたいんですが、可能性があるのかどうか。","respondent":"藤木交通安全担当課長","answer":"ご質問の１点目の自転車の交通違反などを抑止するための監視カメラの設置ですけれども、防犯カメラというものが年々普及しておりますとおり、設置することによって一定の効果はあると考えます。","id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問","question":"あるいは、修理点検へ補助制度、まちの自転車屋なんかの協力を得た中で、そういう中で修理点検補助制度などの検討をしたり、保険加入の特典があったり、要はさっき言ったように、知ってもらう、事故防止のための重要性だとか、法的なルールの知識を知ってもらって広めるための手段として、こういう講習会をより一層グレードアップする手段として、こういったものはどうかなと思うんですが。","respondent":"藤木交通安全担当課長","answer":"そのような自治体の情報収集をいたしまして、いろいろ問題点等、課題等を明確にしていきまして、調査研究はしていきたいと考えています。","id":"exchange-056"},{"speaker":"渡辺委員","kind":"質問・要望","question":"本当に多岐にわたる交通安全の啓発というのは、非常にあると思います。最後に、実効性のある、やはり呼びかけだけではなくて、行動が伴うような点を踏まえて、品川区が将来的にこういったマナーに関する宣言などに進められたらいいと思うんですが、その辺、お考えはありますでしょうか。","respondent":"藤木交通安全担当課長","answer":"委員がおっしゃっているのは、自転車のいろんな交通安全利用宣言だとか、そのようなことかと認識しております。最近、近隣では世田谷区あたりもそのようなものを新たにつくったような事例がありますので、その辺を十分調査してまいりたいと考えております。","id":"exchange-057"},{"speaker":"向委員","kind":"質問","question":"私からは、成果報告書のページ数で申し上げますと１６２ページの都市景観形成事業、そして続いて１６５ページの都市防災まちづくり事業、特に密集住宅市街地整備促進事業についてと、時間があれば、１６３ページに戻りまして、子ども達のアイディアを活かした公園整備についてお尋ねします。一つ目、都市景観形成事業についてお尋ねします。","respondent":"藤田水とみどりの課長","answer":"品川区景観計画のほうですが、この４月１日より運用を開始をしたところです。景観計画は品川区のまちづくりと密接な関係を持ってございまして、その中でいろんな動きがあった際には、この景観計画も見直しながら進めていくべきというふうに考えてあります。","id":"exchange-058"},{"speaker":"向委員","kind":"質問","question":"こういった計画が整って、まちづくり、街並みを特に旧東海道のあたりとか、古い街並みを整えていこうというお考えで計画を進められていると思うんですけれども、このあたりにある公共の建物とか、交番であったりとか、住民の皆さんの安全性とかを補助するために、機能を損なわないためにという、ある程度こういった計画と住民の方の安全とか。","respondent":"藤田水とみどりの課長","answer":"品川区における旧東海道のまちづくり、これにつきましては、区がいろいろ取り組む前から地域の方々が一生懸命取り組んでいるまちです。","id":"exchange-059"},{"speaker":"向委員","kind":"質問","question":"わかりました。私、つい先日ですけれども、全国都市問題会議に参加、出席させていただきました。宮崎県の飫肥地区に関しては、こういった条例を制定して、建て替えるたびにさらにまちが本当に整っていく、古い街並みが蘇っていくとか、そういったお話を伺ってきました。","respondent":"藤田水とみどりの課長","answer":"私どもの景観計画の中で、今重点地区は１カ所ということになっておりますが、こうした地区を自分たちの地域でも、景観重点地区にしてもらいたいんだというような話があれば、その方々とはいろんなお話をする中で。","id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"わかりました。成果報告書、１点だけちょっと実際の金額のところでお伺いしたいんですが、景観計画書印刷等ということで、１６５万５,５５０円計上されていますが、予算のほうの項目には、品川区景観計画書等印刷ということで、若干項目名が違うというか、これは同じものということで考えてもよろしいでしょうか。","respondent":"藤田水とみどりの課長","answer":"今回の景観計画の冊子をつくるための経費でございまして、同じものです。","id":"exchange-061"},{"speaker":"向委員","kind":"質問","question":"失礼しました。６０万円ですね。では、続きまして、都市防災まちづくり事業の密集住宅市街地整備促進事業についてお尋ねします。こちらは、幾つか事務事業概要も見まして、既に終了した戸越一丁目・二丁目地区とか荏原北地区もあれば、まだ今引き続き促進事業が続いていて、私も昨年度ですかね、東中延の同潤会地区の勉強会に数回ちょっと参加する機会を得ました。","respondent":"品川防災整備担当課長","answer":"状況ですが、平成１９年６月から約８回にわたり懇談会のほうを行いまして、その後平成２２年７月に１０名の発起人の方に協力いただきまして、平成２２年１２月から検討会を立ち上げております。この検討会の中に委員のほうも何回かご参加いただいたという状況です。","id":"exchange-062"},{"speaker":"向委員","kind":"質問","question":"わかりました。大分人数も増えてきているのではないかなと思います。今後温度差のみが原因になるとは思いませんけれども、こういった地域の方からいろんな意見が出てきて、事業期間が、今決まっている１０年ぐらいと決まっていると思うんですが、この期間が延びたり変動してくる可能性があるんでしょうか。","respondent":"品川防災整備担当課長","answer":"この旧同潤会地区で建て替えのほうが反対とか、そういった場合が出たらどうかということですが、まず今勉強会でやっている中で、こういう木造住宅が密集した地域、この地域の防災性を高めるためにはどうしようかということを、共同建て替え、それからいろいろ地区整備とか。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"あわせて補助２０５号線も完成をするということでちょっとご質問させていただきたいと思います。渋滞予測をどうされているのか。あの辺も地域の方からあと１０cmでいいから右側に、いわゆる東方向に向かう車、広げてもらえれば右折と直進ですか、並べて行けるようになるのにというようなことをずっと言われているんですけれども、その辺の改良等を含めてお教えください。","respondent":"武藤都市整備下水道課長","answer":"あわせまして、補助２０５号線につきましては、震災の影響で、一部工事に影響が出ましたけれど、現在進めている２期区間と呼ばれる大井三叉交差点の側の約５５０ｍの区間につきまして、来年度に向けて完成で、今事業を進めている予定です。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問・要望","question":"確かに走りづらいなと思う反面、台風のときですから、９月十何日でしたでしょうか、タクシーがそこに思いっ切り突っ込んで大破するような事故が実際に起こっていて、そのガードレールは撤去されていますが、あそこというのは、結局補助２０５号線の工事をしていく途中で、早急に何とか中央分離帯はここですよ、ここからここは歩道ですよとわかるように、実は急ぎでやっていただきたいと思うんですけど。","respondent":"武藤都市整備下水道課長","answer":"委員の今のお問い合わせは、補助２０５号線の今整備を進めている２期区間と言われます小野学園と東京浴場前の約１６０ｍの区間の整備についてのご質問ですけれども、委員ご指摘のとおり昨年度一方通行だったものを、早期に事業効果を発揮するために暫定的に整備を行いまして。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"ちょっと時間がなくなったので１件だけ先に行きます。１５８ページ、街路灯について伺います。１点だけ。子どもたちが動く時間もあるので、先ほど聞いたらセンサーでつく、つかないというような仕組みだということなんですけれど、できれば街路灯はつけておいてほしいなと思うんですが、冬場にもし同じような対策をとらなければならなくなったときに、どのようにされる予定なのかだけお伺いしたいと思います。","respondent":"稲田道路公園課長","answer":"それで、冬場なんですが、まだ正式なというか、詳しい情報が私どものほうにも入ってきておりませんで、今後情報をより早く正確にとりながら、またやり方、その他考えていきたいと考えています。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"ともかく日が短くて、活動する時間が長くなっています。子どもたちが普通にすまいるスクールが終わって帰る時間帯でも、もう真っ暗になっている時間帯ですので、なるべくつけられるところはつけておいていただきたい、そのように思っておりますので、よろしくお願いいたします。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"金野委員","kind":"質問","question":"よろしくお願いします。私のほうからは、１６６ページ、分譲マンションの管理支援についてまずお伺いします。この支援の予算額に対して、決算額は多少減という形になっておりますけれども、まずこの事業内容と、そして減の要因をまずご説明をお願いします。","respondent":"柏原住宅担当課長","answer":"こちらのマンション管理の部分ですけれども、こちらの事業のほうは三つございまして、まずはマンションの管理相談ということで、毎月第二・第四水曜日の午後に実施しております。本日も今やっている最中です。","id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"そうすると、例えばセミナー、相談、こうしたところでの、セミナーは講師を派遣して、このマンションの管理に当たるいろいろなノウハウ、こうしたところをセミナーをされているんだろうというふうに思うんですけれども、また、相談は個別のいわゆる管理に当たって相談を受けると、こうしたものだと思うんですが、主にそのセミナーの内容と、あと相談で受けている内容というんでしょうか。","respondent":"柏原住宅担当課長","answer":"こちらのセミナーのほうは、毎年、テーマを決めて行っておりまして、９月に行った分につきましては、大規模修繕、こちらのほうをテーマにして講演を行いました。こちらのほうは参加の方は５９名の方が参加しております。","id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"そうした中で、どういった業者を選んだらいいのか、あるいはどういったところをポイントとして修繕をしていったらいいのか、そんなことが多く相談の内容としてというか、私もお聞きしたことがあるんですけれども、そういったことが多いかと思いますが、そういったことも含めて、派遣をされながらここはこうしたほうがいい、ああしたほうがいいというノウハウをされているかと思うんですけれども。","respondent":"柏原住宅担当課長","answer":"例えば、管理組合をつくっていますけれども、管理会社に委託をしている部分であるとか、自前で全部管理をしているとか、いろいろなご事情がありますので、そういった中で、その管理組合に合わせた形での修繕の方法であるとか計画。","id":"exchange-070"},{"speaker":"金野委員","kind":"質問","question":"区としては、確かに自主管理のところもあれば、管理組合にお願いをするところもあればということなので、区としてはこれという一つの方向性ということではないのは理解できます。そこで、マンション管理士ですけれども、マンション管理士の方というのは、いろいろといるという話を聞きます。その中で、区はどのようなポイントでマンション管理士の選定をされているのでしょうか。","respondent":"柏原住宅担当課長","answer":"品川区のマンション管理士会のほうに我々のほうはお願いをしているわけですけれども、ご相談の内容は、マンション管理士会のほうにお話をしまして、得意分野等々、例えば実務経験が長い方、それから建築士の資格を持っている方、それから弁護士の資格を持っている方。","id":"exchange-071"},{"speaker":"金野委員","kind":"質問","question":"そこで、マンション管理士を派遣し、そして大規模修繕でいろいろと選定をした業者とうまくいく仕事もあれば、そうじゃなくて、いろんな遺恨を残してしまうようなケースもあればということですけれども、この支援をしてうまくいった、大規模修繕でマンションがうまくいくケース、そういう結果が出たという、支援の効果というのはどのぐらいありますでしょうか。","respondent":"柏原住宅担当課長","answer":"こちらのほう、その派遣をした後にアンケートといいますか、感想を聞いている部分がございまして、なかなかやはり修繕に関してはお住まいになっている方々、プロではない方がほとんどですので、マンション管理士の支援をいただいて、わからないことがわかってきたということで。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"区内に一つしかない老人保健施設ですから、利用する方もたくさんいるんですけれども、そういう中で、入所される際の手続とか利用されている家族の洗濯物を届けたり、引き取ったりと、長居はしないけれども、少しの間とめておきたいというときに、駐車場がないんだということで、そもそもこのさくら会には、利用者の家族が使える駐車場はあるんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみませんでした。それで、駐車場をつくってほしいということで、さくら会の正面玄関のところの道路に白枠で囲ったような路上駐車場なんかをつくれないものなのかという声もあるんですけれども、その辺は可能性としてはいかがでしょうか。","respondent":"藤木交通安全担当課長","answer":"周辺に一般的な交通規制の一つでありますパーキングメーターのようなものだったら設置してあると認識しております。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"近くにあるパーキングなども空いていない、時によっては空いていない、いつも空いているという状況ではないという声も聞かれますので、さくら会用の駐車場として道路のところに設置はできないんでしょうか。","respondent":"藤木交通安全担当課長","answer":"あくまで道路上ということでございましたら、道路にはそういう私権のようなものは設定できませんので、そのような交通規制の一つであります短時間のパーキングメーターのようなものに限定されるものですので、設置は不可能です。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現にそこにとめておいて駐車禁止の切符を切られたという利用者の家族の方もいましたので、またそのたびにタクシーで来るというのも、お金もかかって大変だという声も聞かれますので、この実態をちょっとどうにか解決していただきたいなと思うんです。この道路のところで何とか改善というか、改めて検討していただきたいなと思うんですけれども、工夫の余地はあるでしょうか。","respondent":"松代都市計画課長","answer":"今委員からのご質問は、例えばお見舞いに来たとか、そういうときの車というふうに考えられますので、それは周辺の有料駐車場等をご利用いただければというふうに思います。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問","question":"でしたら、路上駐車場というのは、どうしたらできるんでしょう。どうやったらつくれるんでしょうか。路上駐車場をどうやったらつくれるのか。","respondent":"岩田都市環境事業部長","answer":"担当課長がお答えしましたように、道路交通法で道路の駐車場の設置権限は、東京都公安委員会のみが持っておりますので、現実には設置不可能です。","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問","question":"そしたら、東京都のほうが認めるというのは不可能なんですかね。それを認めてもらうような交渉なり、こちらからの申し入れというのはできないんでしょうか。","respondent":"岩田都市環境事業部長","answer":"道路交通法で認められておりますのは、緊急患者用の表示、既に設置されていると思うんですけれども、そういった救急病院のみでございまして、その他のものは一切例外なく認められません。","id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コミュニティバスについてですけれども、以前も請願が幾つも出されて議論をされていると思うんですけれども、区民の要望とコストと、こういうところの狭間に行政がいるわけですけれども、こういったところの整合性はどのようにしてとられているのか教えてください。","respondent":"松代都市計画課長","answer":"すべて不採択という形の結果になってありますけれども、その間、いろいろと質問を受け、お答えをしてまいりました。私どもの基本的な姿勢としましては、やはり今委員からもありましたように、経済性です。２３区のうち、今１８区が運行しておりますが、すべて赤字です。","id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問","question":"請願等でも、答弁の中でも今これに踏み込むべきではないときで、当面少し見送るという状況にあるということもおっしゃっていましたけれども、どういった状況になれば踏み込む状況になるんでしょうか。","respondent":"松代都市計画課長","answer":"そういった形の整備をまず進めていこうと、このように考えてあります。","id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"赤字なんだけれども、区民要望にしっかりとこたえて頑張っている自治体がこれだけあるということは、しっかりと区民の思いに応えて、やさしいまちづくりとして進めていけば、そういう視点に立って進めていけばできることなんではないかなと思うんです。でも、確かにこの都の補助金が少ないのは確かだと思います。都からの補助が増えたら、可能性はあるのかお聞かせください。","respondent":"松代都市計画課長","answer":"残念ながら、今のところ補助等があっても、区がそのことに踏み込むつもりはございません。","id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、やはりこういった方々を、せめて生活の買い物にまちに出てもらうとか、こういった自立をしてもらうという、自立を進めていくという上でも、品川区は、今、介護予防なんかもすごく進めていると思うんですけれども、こういった点でもすごく予防になるし、孤独をなくすという意味でも、やさしいまちづくりというところにかかってくるんではないかなと思うので。","respondent":"岩田都市環境事業部長","answer":"今後、都市計画道路ができるのを待って、そういう道路にも路線バス網を増やしていく、まずそれが最優先だということで、福祉関係の問題については、別途視点を変えて検討すべき問題だろうと考えております。","id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり先ほどもお話ししましたけれども、さくら会までの交通網がなかなかないんだと。ですので、これから特別養護老人ホームもさらにできてくるという状況で、高齢化も進んでいくというのは、区のほうでもご存じのことだと思いますので、こういったところにしっかりと公助として手を差し伸べていく、援助をしていくということが今必要なのではないかなと思うんですけれども、いかがでしょうか。","respondent":"松代都市計画課長","answer":"例えば福祉タクシーを今やっておりますが、そういった形で対応するとか、コミュニティバスですべて満足すると、そういった形には環境的にはないというふうに考えているところです。","id":"exchange-083"},{"speaker":"原委員","kind":"質問・要望","question":"私は成果報告書の１６１ページ、目黒川水質改善、それから同じく成果報告書の１６２ページ、都市景観形成事業、それから１６７ページの区民住宅費等についてお伺いします。ですから、木村委員の質問とダブらないように他区とか、それから東京都、その辺との調整関係、具体的に言うと今後どうなる、どうなっていくのという、そこを教えていただきたい。それについてお教えください。","respondent":"藤田水とみどりの課長、柏原住宅担当課長","answer":"今後は、東京都の重い腰を上げるために働きかけを行っていきたい、東京都みずから取り組んでもらえないかということをお願いしてまいりたいというふうに考えてあります。それから区民住宅のほうです。平成２２年度につきましては、４,０１５万９,３８３円、平成２１年度につきましては、３,６７６万６,５９３円です。","id":"exchange-084"},{"speaker":"原委員","kind":"質問・要望","question":"その次の段階、３番目の住宅の未収部分なんですけれども、何でこういう言い方を申し上げてしまうかというと、確かに専門家、宅建協会ですとか弁護士をお使いになるのも当然のことかと思うんですけれども、まず取れないとか払わないのに出ないとか、いろいろな問題はあろうかと思うんですけれども、だったらば、その前にそういう状況にならない方法がないんだろうかと、その辺についてお考えがあれば。","respondent":"柏原住宅担当課長","answer":"一月滞納してしまうとその金額、さらに二月となると１０万円、２０万円、３０万円という形になりまして、そこからなかなか厳しい状況になるということがありますので、我々としましては。","id":"exchange-085"},{"speaker":"原委員","kind":"質問","question":"それからあと、民間の今賃貸状況なんかを見ますと、居住が今、敷金・礼金、ゼロ・ゼロというのがはやっていたり、３カ月ただにしますよという大家さんがいたり、それこそ事務所系なんかであれば、１年がただじゃなくて、今１５カ月ただですよと、そういうような住宅関係の展開になっているんですけれども、ですから、私は何を申し上げたいかというと、保証人、それから保証会社をもっと活用できないか。","respondent":"柏原住宅担当課長","answer":"未収につきましては、いろいろなところを研究しながら、特に保証人についても、今までは４カ月たたないとお話ししなかったのを、１カ月、２カ月ですぐご連絡するとかというふうに運用上変えてきている部分もあります。","id":"exchange-086"},{"speaker":"原委員","kind":"質問","question":"ですから、しっかり同じような形で、そして時期をずらさないで、これは金額だけの問題じゃなくて、督促等はタイミングというのもあろうかと思います。ですから、その辺も考えてお願いをできればと思います。時間があともう少しあるようですので、ページは戻りまして、１６１ページの橋梁、歩道橋なんですね。全体の幅を言いますと、３分の２が階段になっております。これは区ではなくて都なのかもしれない。","respondent":"松代都市計画課長","answer":"将来的には、やはりユニバーサルデザイン、やさしいまちづくりで、そういった障害者等にも対応できるような歩道橋をというのが国の政策でありますし、東京都もそういった方向で考えてありますので、しかるべき時期にはそういった計画が出せるものと。","id":"exchange-087"},{"speaker":"原委員","kind":"質問","question":"実際にいつスタートするかわかりませんけれども、ＪＲが五反田駅、いろんな考え方をお持ちになり出してきたというような話もちまたには伺いますので、うわさかもしれませんけれども、もしそういったことが出てきましたらば、ぜひとも東京都に対して歩道橋に関しては改善、改善というか改良していただけるように、もう一度そこのところをお聞かせいただければと思います。","respondent":"松代都市計画課長","answer":"したがいまして、ＪＲも含めて、東京都も含めまして、品川区もしっかりと周辺等々、皆様と一緒にまちづくりを考えていきたいと、このように思っているところです。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問","question":"街路樹等維持管理費ですが、道路環境の整備と、まちの緑化を推進するために区道に街路樹の植栽や植樹帯を設置し、定期的に剪定し、そして除草、支柱取り替えおよび害虫防除等を行っていらっしゃるということですけれど、ここでちょっとお伺いしたいのは、平成２１年度は成果報告書に剪定数が記載されておりますが、平成２２年度は載っておりませんので剪定数を教えてください。","respondent":"稲田道路公園課長","answer":"それから基本剪定、これは冬場に行うものでございまして、木の骨格的な形をつくってやる剪定というのが１,４４０本行いました。中木刈り込みが７４８本、あと除草が５万３,２３５m2、低木刈り込みが２万６,１０５m2というふうな実績です。","id":"exchange-089"},{"speaker":"吉田委員","kind":"意見","question":"ここで台風についてちょっとお話ししたいんですけれど、２００９年に発生数は２２個で接近は８個、２０１０年は発生数は１４個で接近は７個でした。今年ですが、台風１５号の上陸に伴い、区道・公園等で被害の報告がありましたが、その状態を統計数値でお願いいたします。","respondent":"稲田道路公園課長","answer":"９月２１日の台風です。このときの倒木数なんですけれども、全体で、私どもの施設以外で６５カ所の倒木等あったんですが、区の道路・公園でいきますと、合計で４４本の倒木、枝折れ等があった本数を確認しました。","id":"exchange-090"},{"speaker":"吉田委員","kind":"質問","question":"そのうちで、倒木が車にぶつかり、事故発生ということをお聞きしましたが、けが人等がなくてよかったと考えています。私が一番心配しておりますのは、こういう街路樹等の老朽化なんですけれど、台風などに備える意味でもありますが、老朽化対策はどのようになっているのでしょうか。専門家の判断基準などがございましたら、お教えください。","respondent":"稲田道路公園課長","answer":"年に１回程度全体的な街路樹等の点検も行っております。そして、台風が近づくときにおきましては、また強化して点検を行っているです。その中での点検基準というものなんですが、基本的には外観の点検を行うのが常です。","id":"exchange-091"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから一つつけ加えしますが、これは要望なんですけれど、街路樹を支える添え木というんですかね、こういう二股になっているんですけれど、それが老朽化しまして、百反坂のほうでは針金等だけになっている、また外れているところがまだまだ見られますので、点検等もよろしくお願いいたします。本区の公園全部を完全にバリアフリー化するのか、その辺をちょっとお伺いしたいと思います。","respondent":"稲田道路公園課長","answer":"この公園バリアフリーなんですが、公園２４５カ所ある中で、まずは入り口の段差をなくしたり、まずはそういうところから始めていくということで、順次１カ所ずつ進めていると。","id":"exchange-092"},{"speaker":"吉田委員","kind":"質問","question":"もうちょっと具体的に計画的に、例えば何年までにこうするみたいなことはありますでしょうか。","respondent":"稲田道路公園課長","answer":"２４５カ所のうち、１５８カ所が整備済みです。その中の段差を解消するというのも、４９％は終わっているというところでございまして、未整備があと８９カ所、これは順次行っていきたいというふうに考えております。","id":"exchange-093"},{"speaker":"吉田委員","kind":"質問・要望","question":"順次行っていっていただきたいと思います。ここで一つ、雨の日なんですけれど、坂の下の公園など、細めタイプの横断側溝なんですが、滑って危ないと。転んじゃったよという話もお聞きしたんですけれども、この細めの横断側溝で、そういうお話は聞いたことがありますか。","respondent":"稲田道路公園課長","answer":"といいますのは、滑りにくく改良したといいますのは、細い鉄のバーが通っているんですが、最近のものはそこにぎざぎざがつくようになっております。そういうものに変えていきながら、またそういう坂道等ではそういう滑りどめのものを使っていきたいというふうに考えております。","id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"最初に、放置自転車の件ですけれども、旗の台駅南口、何回も質問していますけれども、東急電鉄が南口に住宅を建てるときに、駐輪場とか駐車場、オートバイですね、建設をすると約束をしていたけれども、結局できたのはバイク用の駐車場だけだったということで、この件については、これからどのような形でやっていくのかなということですが、自転車法では、鉄道事業者が駐輪場を設置しない場合は。","respondent":"藤木交通安全担当課長","answer":"最近の情報ですと、再度具体的に検討しておりまして、できましたら年度内にはどうにかしたいような、そのような情報を聞いております。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"私道整備事業につきましては、９７％を超える執行率だったと私の計算によるとなっているんですけれども、平成２２年度内に申請された件数と工事が完了した件数、そしてまた平成２２年度に完成したけれども、前年度以前に申請されて完成した件数、また平成２２年に申請をしたけれども、残念ながら平成２３年度以降に持ち越しになった件数、こちらのほうをお伺いしたいと思います。","respondent":"中村建築課長","answer":"申請いただきましてから、着工するまでの期間ですけれども、こちらは通常の場合ですと申請いただいて、申請者の方にお話を聞きに行きまして、設計の内容を十分吟味した上で設計を行い、そして工事の発注、着工というところまで、通常は３カ月を要します。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"最近、この申請につきましても、私も聞いたところによりますと、年度当初、結構年度の早いうちに申し込みをしても、完成は翌年度ですと言われるケースも、私も２年続けて区民の方から伺ったことがありますので、ぜひとも何とか早くしていただければと思うんですけれども、例えば予算、補正予算もかなり毎年のようにとっているかと思うんですけれども、一度大きく予算をつけて。","respondent":"中村建築課長","answer":"今後、また状況を見まして、どのように待ち時間を短縮していくかどうか、この辺を設計の努力とあわせて、ほかに方法があるかどうかを検討してまいりたいというふうに考えております。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"土地の所有者に責任があるということですので、長い間穴があいたまま放置ということもできないので、ここら辺も含めてなるべく早く対応していただければと思います。次に、耐震診断助成ですけれども、こちらは予算の１割にも満たない状況かと思います。例えば、３階以上、また１,０００m2以上を対象としている助成制度を何とかもう少し条件をつけながら下げていくという考えはあるのかどうかお伺いします。","respondent":"品川防災整備担当課長","answer":"それからマンションのほうですが、基本的には大規模マンションということで、１,０００m2３階建て以上ということで、事業のほうを展開しておりますが、それ以下のマンションにつきましては、他区の動向も踏まえて考えていきたいというふうに思います。","id":"exchange-098"},{"speaker":"高橋委員","kind":"質問・要望","question":"目黒川の水質改善は、ほかの委員からも質問があったので、私としては、品川区行政評価委員会の評価結果でも、水質浄化の抜本的な取り組みは、河川管理の主体である東京都の責任において行うべきであり、引き続き東京都へ働きかけること、区が行うべき事業の内容を具体的に検討することということで、区がこれまで行ってきたことを評価しつつも。","respondent":"武藤都市整備下水道課長、藤田水とみどりの課長","answer":"もう１点、鮫洲運動公園の改修工事につきまして、子どものアイディアを活かした整備を平成２２年度から、一部震災の絡みもございまして、平成２３年度に一部事業を実施しておりますけれども、その成果についての区の考え。河川の関係の浄化の部分ですけれども、都からの補助金等が入っているかですが、立会川、目黒川の浄化とはちょっと違うんですが、清掃委託、それから汚泥浚渫委託ということで、これらのものについては。","id":"exchange-099"},{"speaker":"高橋委員","kind":"質問・要望","question":"それが一つ。事務事業概要によると、城南河川清流復活事業負担金を４６０万円、１０年間支払っています。それを全額都に負担するように求めている、おそらく平成１３年から求めていると思うんですが、十数年たっています。それをほかの区、つまり、品川区以外のところでこのようなことが行われているのか、それならばなぜ、獲得して品川区がそれだけのことができるのかということをお尋ねします。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"城南河川の清流復活の関係ですが、もともと東京都が城南河川の６区に対して、都の事業として行うということでスタートしたものでございまして、その後東京都のほうが財政状態が厳しいということで。下水道局と品川区の関係ですけれども、これは大分昔になるんですが、この受委託関係というのは、昭和５６年から始まっております。","id":"exchange-100"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、過去にこのような大きな形で受託事業は、どのようなものがあったかということ、それから事業を行う際に、区の職員の方のいわゆる事務費というんでしょうか、人件費がかかると思うんですが、その点については受託費の中に含まれているんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"受託の過去の状況ですけれども、特に目黒川につきまして浸水被害がひどい状況がございまして、目黒川の左岸および右岸、両側に大規模な下水道の浸水対策用の管渠の工事を受託して、昭和６１年度から最近までずっと事業を進めておりました。","id":"exchange-101"},{"speaker":"高橋委員","kind":"質問・要望","question":"とすると、言い方はあれですけども、持ち出しなしでこの事業、下水道管耐震化推進事業を行われているというふうなことでよろしいでしょうか。ということは、事務事業評価でも、拡充ということの事業でありますし、区民の方々のサービスに直結する事業なので、さらなる拡充を目指していっていただきたいと思います。","respondent":"稲田道路公園課長","answer":"ただ、分煙化というところなんですが、一応１,５００m2という公園の面積で、分煙化にするか、禁煙にするかというふうな考えを区のほうでは持っておりまして、分煙化する公園は１,５００m2以上の公園、禁煙化は１,５００m2以下の公園ということで考えております。","id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"今のようなお話の形で進め、ＪＴさんの協力も必要だと思いますので、ぜひ推進していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も私道の整備の工事に関しては、本当に申請をしてから長い時間がかかるということで、これが何とかもっとスムーズにできないものかなと思って質問をするんですけど、先ほどもほかの委員からも質問があったんですけど、改めてちょっと平成２２年度と今年度、平成２３年度の申請件数と工事件数、それとその工事件数の中で、前の年か前々年度か。","respondent":"中村建築課長","answer":"それと今年度、平成２３年度ですが、現在までに２５件の申請をいただいております。そして、同じく９月いっぱいまでに工事をした件数が１５件です。それと、持ち越した件ですが、これは先ほど申し上げましたが、平成２２年度から平成２３年度に持ち越したのが３１件です。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当に１年から１年半くらいかかるのが当たり前という状況で、この私道の場合は、合意をとるのにも結構時間がかかりますので、何とかしたいというふうに思って合意をとって申請をして、工事が終わるまでに本当に１年半とか２年とか、本当に長い間かかってしまうわけなんですけど、少なくとも申請してからなぜこんなに時間がかかるのかといえば、それは予算の問題ということになるんでしょうか。","respondent":"中村建築課長","answer":"緊急性、先ほども申しましたが、緊急性だとか、その辺を勘案して、危険を最小限あるいは安全な状態を保持できるように、そういった配慮をしながら計画的に進めていきたいというふうに考えております。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大体私道の整備をしてほしいということで相談に行くときには、本当にでこぼこがあって、転んでけがをしたとか、そういう整備をしてほしいという状況があって、大体相談に行くんですよね。それからかなりの時間が余りにもかかり過ぎるということで、何とか予算をつけて増額して、翌年度までに持ち越さないという感じで増額していただきたいと思うんですが、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"ただ、区のほうとしては、円滑に工事が進むようにきちっと必要な予算についは調整を行っていきたいと考えていますし、合意形成に向けてもそういう対応を行っていきたいと考えています。そのような状況です。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、かなり本当に公道から公道に通じているような道路でも、２.５ｍ以下ということで１割負担があるとなると、なかなか合意形成がとれなくて、本当にでこぼこで危ないような道路でも、そのまま何年間にもなってしまうという状況になっていると思うんですけど、そこのところを何とか全額区の負担になるような方向にしていただきたいなと思って質問したいと思っているんですが。","respondent":"中村建築課長","answer":"過去１０年間ですけれども、私道の整備の制度が始まりまして、１５１件が工事の件数です。そのうち９割助成、１割を申請者様に負担していただいた件数、これが８０件です。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９割助成が８０件ということで、私はなかなかこの１割負担があるために合意がとれないという相談を何件か受けていましたので、こんなにたくさんあったということはちょっと意外だったんですけど、それにしても１割負担があるために合意がとれないで、でこぼこの道路がそのままになっているという状況がずっと続いているというところが何件かありますので、そこのところはぜひとも１割負担をなくして。","respondent":"中村建築課長","answer":"今私道といいますと、それぞれ権利者様の合意が得られなければ着工ができないという私有財産です。ですので、この私有財産にさらに手を加えるということになりますと、一定程度のやはり負担はやむを得ないというふうに考えております。","id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区では、この公共性に着目して、区民福祉の増進を目的に生活環境の改善、安全で快適なまちづくりに努めていますということで、こういう形で拡大をしたわけなんですが、区としても本当にだんだん増やしてきていただいて、２.５ｍ以上は全額助成ということで拡大されているということはよくわかるんですが、さらにもう一歩２.５ｍ以下の道路に関しても全額助成ということでご検討いただきますように。","respondent":"品川防災整備担当課長","answer":"平成２３年のまず耐震診断につきましては、９月末現在で１５５件、それから耐震改修につきましては２件、耐震建て替えにつきましては２０件という状況になっております。","id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この９,８００棟で、そしてまた年間１,１００棟という目標からすると、まだまだ遠いんじゃないかなというふうに思うんですけど、それでも今年度は耐震診断が急激に伸びていると思うんですね。それと、耐震診断の体制は現在何人でされているのか、それは今回の急激にこの耐震診断の申請が増える中で、強化されたのかどうかについてもお聞かせいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"それから体制ですが、こちらはちょっと職員のほうか、また建築士のほうかわかりませんが、職員のほうに関しましては、やはり窓口の申請がかなり多いですので。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"私は１５７ページ、交通安全啓発費に関連して、それから１６１ページ、立会川浄化対策、１６３ページ、しながわ水族館に関連して質問いたします。結果として渋滞が起きました。つまり、車列が行くわけですよね。激励に行く。だから、啓発に行きながら、そういう事態を引き起こしたのは、どうも余り格好よくないと思いますので、まして、警察の方々が乗っているわけですから、交通安全のプロなわけですよ。","respondent":"藤木交通安全担当課長","answer":"警察のほうで交通安全運動期間中にテントのほうを激励に参りまして、結果的にそのような交通渋滞を招いてしまったとなりますと、まさに本末転倒ですので、その辺、駐車場所の事前の十分な徹底ですとか、その辺につきましては。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"確認","question":"大体場所が、テントがあるところは限られているでしょうから、例えばそこに行ったら、ほんの少し手前といいましょうか、あいたところに車を置いて、そこまで歩いてもらうとか、それからどうしてもの場合にはまさに警察官が同行されているわけでしょうから、後続の車をうまく誘導していただくとか、そうすればこの問題は解決すると思いますので。","respondent":"藤田水とみどりの課長","answer":"それで、現在行われている立会川の高濃度酸素溶解水の機械ですが、５年で一応リース切れになりますが、通常であれば七、八年使えるですので、何とかもう少し頑張っていただいて、それまでの間いけば、その後については汚れたものが流れてこなくなれば川自体はきれいになる。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"確認","question":"それをつまり抑えるためにいろんなことをやっているということを聞いたんだけれども、それがもう少し時間がかかることは確かなことで、その間のある意味つなぎとして、こういう高濃度酸素溶解水の導入があったということを聞いているんだけれども、今のお話を聞いていて、もう少し確認したいのは、やっぱり５年ということだけど、あと二、三年頑張るということだけれども。","respondent":"岩田都市環境事業部長","answer":"先ほど水とみどりの課長が申し上げましたように、今でいきますと、平成二十七、八年で下水道局の工事が終わる予定ですので、２年から３年ぐらいリース切れですけれども、一部部品の交換をしながら、それまで活動してもらう。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"提案","question":"違う方向で提案するんであれば、またそれは相当な覚悟をしなきゃいけないと思う。つまり、それぐらいの思いと、それから民間の観点を入れていかないと、しながわ水族館の将来に大きな禍根を残すと思いますので、確認したいのが、区内で検討するのはもちろん正しいことなんだけれども、それに加えて多くの民間の視点といったらいいのかな、民間の導入は考えていらっしゃるでしょうか。お願いします。","respondent":"藤田水とみどりの課長","answer":"そうした中で、本年あり方検討ということで行ってありますが、このあり方検討を、例えば区の内部だけで行う、それから水族館の運営事業者の中だけで行うということになると、やはりどうしてもひいき目に水族館を見る中でのあり方の検討になってしまうということで。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"難しいんですよね。遊園地でも水族館でも何でも、同じものをずっと展示し続けていけば、やがてあきられる。だからこそリニューアルが必要だということで質問するわけでありますけれども、ここはぜひ品川区の中心的な施設ですから、濱野区長の水族館にかける思いをお聞かせください。お願いいたします。","respondent":"濱野区長","answer":"その検討を待って、今後の推移を考えたいというふうに思っております。","id":"exchange-115"},{"speaker":"山元委員","kind":"質問・要望","question":"よろしくお願いします。私は１５７ページの土木総務費の中の道路・公園等の監察、占用許可、それからその後は、１６３ページの、先ほども出ましたけれども、公園新設改良費の中の子ども達のアイディアを活かした公園整備、こちらのほうをお聞きしたいと思います。具体的にどういうものを取り締まったのか教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"この総件数の内訳ですが、まず一番多いのが商品の道路へのせり出し、これの指導が１,０４９件、それから路上生活者もあります。これが２３件。不法占拠処理９件、それから放置屋台というものもございまして１件あります。その他もろもろ１３１件という内訳です。","id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"公の道路をそのようにいろんなせり出しとか今ご案内いただきましたけれども、それに対して区としてはどのような対応をなさっているのか、具体的に教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"対応としましては、大きく二通りございまして、一つは警察、道路交通法の問題もありますので、無断道路使用ということでは交通管理者という機関と連携いたしまして、年間の合同パトロールということで実施しています。","id":"exchange-117"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に小さなお子さんがいらっしゃる、ベビーカーを押したりとか、またご高齢の方のシルバーカー、そこにまた自転車が通るとその商店の看板とかいろんなものが出ているものですから、本当に危ない思いを、冷や冷やする思いをする方がたくさんいて、私のところにも、「あそこの店、どうにかならない」とか、いろんなふうにあります。これはどういうことなのか教えていただきたいと思います。","respondent":"井浦土木管理課長","answer":"商品のせり出しにつきましては、町会あるいは商店街の方とも連携いたしまして、２０回余りの年間の、平成２２年度の警察との合同パトロールの中では、４回については地元の商店街あるいは飲食店組合の方、あるいは町会の方と連携して、合同して行っていくということで。","id":"exchange-118"},{"speaker":"山元委員","kind":"質問・要望","question":"どうかよろしくお願いします。では、１６３ページの子ども達のアイディアを活かした公園整備についてお伺いいたします。ところが、ベンチとかがあるんですが、その上には何もないものですから、炎天下の中で食事をしているということで、その辺何か日陰になるようなものができないものなんだろうかというお話を伺いました。実はそれは漢字で書いてあるものですから、小さいお子さんにはちょっとわかりません。","respondent":"武藤都市整備下水道課長、稲田道路公園課長","answer":"この差についてご説明します。１点は、工事を起工して、契約したときの落札の差で約１,１００万円程度、それと震災の影響によりまして、平成２３年度に工事を繰り越した関係で１億４,０００万円程度というものになっております。倒木の跡の穴ぼこ、それからベンチの上の日陰等、それからトイレのボタンに絵をつけるというところですが、直ちにやりたいと思います。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問・要望","question":"自転車対策です。これは先ほどほかの委員も言っていましたけれども、自転車を使うと、利用するという前提で政策を考えたらどうかということがありました。それで、先ほど違いますよと、そういうことではありませんよというお話を受けましたが、その辺、もう一度お考えいただきたいんですが、いかがですか。","respondent":"藤木交通安全担当課長","answer":"区の基本方針ですけど、先ほど申し上げたとおりでございまして、自転車の利用は自粛をしていただきたいということで進めております。","id":"exchange-120"},{"speaker":"西本委員","kind":"意見","question":"総務費のところでもお話をさせていただきましたが、例はあまり出したくはないんですけれども、伊藤学園の話です。一般開放をするよという中で、いろいろ建築をしている。しかし、あそこの駐輪場は、学校側に言わせると、これは学校のものであって、一般開放するものではないと。そうすると、あそこには駐輪場がないという形になりますが、それはどういうふうにお考えになりますか。","respondent":"石田（秀）委員長","answer":"駐車場、さっきは、それで道路に設けてくれというから少し許したけれども、まさに学校の中で駐輪場だけとなると、学校施設の問題になるから、それはそれ以上続けると注意せざるを得なくなっちゃうので考えてください。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"質問を変えます。学校施設、明日もありますので追求しますけれども、ただこの要因は、学校開放に限らず、区の政策として先ほどの答弁のように区民の自転車を使用するということに対して、啓発はしなければいけないと思います。その中で、やはり自転車は使用するという前提でさまざまな政策を立てていかなければならないのではないかと思いますが、いかがですか。","respondent":"岩田都市環境事業部長","answer":"特定の施設は別にいたしまして、公共施設におきましても、必要最小限のそういったサービス施設は設けておりますけれども、それをあふれるものについてはやっぱり自粛をお願いせざるを得ないという実情をご理解いただきたいと思います。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"ただ、区の政策の中で、やはり自転車を使う区民の方が多いということは、やはり認識をした形でのさまざまな政策づくりをしていくべきではないでしょうかということを言っているので、それに対してのお考えと、それから商店街についても同じことが言えるんじゃないかと思うんですね。それから、料金の見直しをするということも図るということもお聞きしていますが、その進捗状況もお聞きします。","respondent":"藤木交通安全担当課長","answer":"ご質問の３点目、駐輪場における電子マネーの関係ですけれども、それは今具体的に指定管理者などとこのような導入ができないかということで、また区内部でもいろいろ調整を今進めているところです。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひちょっと区の考えを変えていくべき時期に来ているのではないかというふうに思っておりますので、ご検討していただきたいと思います。次に行きます。１６２ページの景観形成、それからあと二つは関連してなんですけれども、１０月２日の景観まちづくりシンポジウムに参加させていただきました。これらはまだまだ改善すべきところがあるのかなというふうに思いますので、そのお考えをお聞きいたします。","respondent":"藤田水とみどりの課長","answer":"そういうような人たちの力も活用しながら、まだ１カ所しかない重点地区、これを複数の箇所に広げられるように、私たちもいろんな方と連携しながら進めていきたいと考えています。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"キーパーソンとなる方たちというのは非常に大切だなというふうに思っております。コーディネーターというのがどういう意味でここの中で整理されているのか、これももしかしたら、地域をつくっていくためにも有効活用できるのかなというふうに考えるんですが、それらの考え方についてお聞きします。","respondent":"藤田水とみどりの課長、山崎マスタープラン担当課長、三宅都市開発課長","answer":"そういう面では、まちづくりの支援事業、このほうを活用するほうが、地域の人たちを主体にまちづくりが進められるというふうに考えてございまして。区民の自主的なまちづくりの支援ということで、まちづくりにつきましては、ある意味区民の方がまちづくりにきっちり関与して。都市再生総合整備事業におきますコーディネート業務ですけれども、大崎駅周辺地域では、幾つもの地区で再開発事業が行われている関係で。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、ばらばらに行動することではなくて、しっかりと協力しながら、補い合いながら推進していっていただきたいというふうに思っています。この遊具は、選定はどのような基準なのか、例えば幼児用、２歳から１２歳とか、大きいんですよね。広いんです。それらをすると、どうしてもけがとかをしやすいということになりますので、具体的な基準と、それから今後の進め方についてお聞きしたいと思います。","respondent":"武藤都市整備下水道課長","answer":"具体的には公園のそれぞれの遊具について、メーカーが定めるいろんな基準等がございまして、その辺を見ながら設置を検討しております。","id":"exchange-126"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１６３ページの公園管理費と１６４ページの公園バリアフリーについてお伺いさせていただきたいと思います。先ほどもほかの委員からもご質問がありましたが、１５８カ所現在終了していて、これからもこうしたバリアフリー化を進めていくというお話でした。失礼しました。最後の部分は抜かしていただいて、予算で８カ所となっているところが、１１カ所に増えた理由を教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"予算では８カ所というふうになっておりますが、実績は１１カ所というところです。これは公園８カ所、それに公園の中のトイレの手すり等も設置したほうがいいんではないかというところで、トイレ工事を３カ所つけ加えまして、１１カ所の実績となった次第です。","id":"exchange-127"},{"speaker":"大倉委員","kind":"質問","question":"予算では、バリアフリー化が６カ所、安全・安心の公園づくりが２カ所と書いてあったんですが、手すりを増やしただけではなく、バリアフリー化を増やしたのも２カ所あるということでよろしいでしょうか。","respondent":"稲田道路公園課長","answer":"バリアフリー化と安全・安心の公園づくりで、見通しをよくするというのが安全・安心の今回やったところなんですが、鎗ケ崎公園、谷垂公園等を、見通しをよくした安全・安心ということで、全部含めて公園関係８カ所、トイレ３カ所、全１１カ所です。","id":"exchange-128"},{"speaker":"大倉委員","kind":"質問・要望","question":"この公園バリアフリー化がいつから始まっているのか、これを教えていただきたいと思います。","respondent":"稲田道路公園課長","answer":"公園バリアフリー化の事業ですが、平成１８年からやっております。平成１８年からです。","id":"exchange-129"},{"speaker":"大倉委員","kind":"質問・要望","question":"平成１８年からということでしたが、前年度６カ所で、今年度が１１カ所ということで、あと事業が残っている公園が８７カ所近くあると思うんですが、毎年このぐらいの箇所数でいくと８年ぐらいかかってしまうと思うんですが、早急にバリアフリー化したほうがいいと考えているんですが、もちろん災害時とか公園等が一時避難場所になり得るのかなという思いの中で早い整備が必要だと思っているんですが。","respondent":"稲田道路公園課長","answer":"私ども計画を立てておりまして、予算等もありますので、年間８カ所程度前後というところで、現地の優先順位等も考えながら約１０年近くはかかるとは思うんですけれども、やっていきたいと考えております。","id":"exchange-130"},{"speaker":"大倉委員","kind":"意見","question":"優先順位を決めてということでしたが、その優先順位というのはどういった優先順位、例えば利用が多いとか、そういったところをちょっとお願いいたします。","respondent":"稲田道路公園課長","answer":"施設の老朽度、それから委員おっしゃられました利用の頻度、それは現場を見て、私どもの担当者が判断して次年度はここをやっていこうというふうに予算等で計上しているものです。","id":"exchange-131"},{"speaker":"大倉委員","kind":"質問・要望","question":"公園管理費についてお伺いをさせていただきたいと思います。２３６カ所ありますが、前年度も２３６カ所ということで、前年度に比べて決算ベースで金額が減っているのですが、その理由と、先ほどちょっと間違ってしまいましたが、平成２２年度の予算では２,０００万円比べて上がっているんですが、その上がった理由もお知らせください。","respondent":"稲田道路公園課長","answer":"公園・児童遊園維持管理費です。７億９,８４７万９,５８６円と平成２２年度はなっております。こちらと平成２１年度の比較ということでご説明いたしますと、約３,０００万円ちょっと、平成２２年度は決算が下がっているという状況です。","id":"exchange-132"},{"speaker":"大倉委員","kind":"質問","question":"公園の管理なんですが、地域を回っている中で、新しくできた公園は当然新しくて、バリアフリー化もできておりますし、大変すばらしいと思うんですが、昔から親しまれている公園というところで、もともと公園に植えてある植栽というか低い木のものであったり、公園の中で抜け落ちていたり、かなり煩雑な感じになっているところで、ほかにも雑草がコンクリートのところから生えていたり。","respondent":"稲田道路公園課長","answer":"委員ご指摘の、そのような植栽が抜けていたり、また雑草が生えていたりですが、私ども巡回点検作業等で日々回っているんですけれども、より一層その辺のきめ細かな維持管理というのを心がけて、公園の利用者にも喜んでいただけるようにやっていきたいと思います。","id":"exchange-133"},{"speaker":"大倉委員","kind":"質問・要望","question":"２４５カ所中の２３６カ所を維持管理でやっているということなので、ぜひそうした公園が利用者にとって安心して利用できる公園にしていっていただきたいなという思いがありますので、ぜひともそれに取り組んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"本多委員","kind":"質問","question":"成果報告書の１５８ページ、道路維持費、路面維持管理費についてと、１６４ページの百反歩道橋架替関連整備実施設計委託。それと、同じく１５８ページ、その下の安全施設整備で交差点改良、こちらも予算が２０カ所のうち、決算１４カ所、スクールゾーンカラー標示、予算１５０m2、決算４３m2、その予算執行についてあらましで結構ですので教えてください。","respondent":"稲田道路公園課長","answer":"それを現地調査の上やりまして、当初の予定とは若干少なくなったんですが、１４カ所という実績です。それから、スクールゾーンですが、スクールゾーンにおきましても、現地の調査の結果というところで減っております。","id":"exchange-135"},{"speaker":"本多委員","kind":"質問・要望","question":"プレス発表で、２３区初で、要するに平日しかやっていなかった巡回サービスを、土日でもやる、祝日でもやる、これはやはり区民から見て期待する部分で、すごく多分成果があったと思うので、多分すごくいいことだったと思うので、成果報告書に１行堂々とあればよかったなと、そんな思いで、素朴にちょっと聞いたまでで、要するに台風の話とかもいろいろ出ていて。","respondent":"稲田道路公園課長、岩田都市環境事業部長、藤木交通安全担当課長","answer":"スクールゾーンの全体で何カ所ぐらいあるかというところですが、７０３カ所あるです。区では、その隅切った後の管理、これは従来はその土地の所有者が管理をしているわけですけれども、そこに石を置かれたり。そういうような実態がもしＰＴＡですとか学校とかからありましたら。","id":"exchange-136"},{"speaker":"本多委員","kind":"質問・要望","question":"３月１１日より以前から起きておりまして、当然区のほうも十分連絡が入って対応していただいていると聞くんですけれども、場所によっては３０cmぐらい地盤沈下が起きていて、ビルは杭を打っているからみんな現状なんですが、道路を中心にすごい勢いで陥没をしておりまして、こういうのはやはり巡回して見つけて対応するのにはかなり時間がかかるのはしようがないと思うんですけれども。","respondent":"稲田道路公園課長","answer":"ただ、それが何が原因かというところで、まず空洞ができるということは、水道とか下水、水関係がその中で流れているんではないかというふうに私どもは考えまして、それが一般的な考え方なんですけれども、東京都下水道局、水道局に調査を依頼しまして、東五反田一丁目７番、８番。","id":"exchange-137"},{"speaker":"本多委員","kind":"質問・要望","question":"この地盤については、本当に注視して取り組んでいっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、建設委員会に私は所属していまして、その中でも質問させていただいたんですが、また来年、再来年、今後何年続くかわかりませんが、この節電の関係で、また特に夏ですね、同じようなことをやらなきゃいけない状況が続く可能性が高いということで、１本１本やるんじゃなくて、遠隔で何か操作できるような、そういう街路灯がないんでしょうかということを建設委員会で聞きましたところ。","respondent":"稲田道路公園課長、品川防災整備担当課長","answer":"今後このような新しいシステムやＬＥＤ等も検討しながら、ご提案等のものも含めまして、街路灯の明るさ、その辺を品川区に合った明るさに設定していくというふうに考えております。今後、またこの対象地区で品川区がなった場合は、当然密集事業を進めている地区ですので、積極的に協力していきたいというふうに考えております。","id":"exchange-139"},{"speaker":"武内委員","kind":"質問・要望","question":"街路灯につきましては、まだ新聞発表段階ですので、私も全然詳しいことはわからないんですけど、こういうものがこれからどんどん出てくると思うので、来年度以降１本１本やるというのをお聞きして、本当に大変だなと思いましたので、こういうものが費用対効果を見ながら、もし取り入れられるならぜひ研究していただきたいなというふうに要望します。","respondent":"品川防災整備担当課長","answer":"空き家の件ですが、こちらについては、なかなか区としてもどういうふうに進めていったらいいかということをいろいろ検討している状況です。空き家が解消されない一番の要因としては、やはり固定資産税の関係が考えられると思います。","id":"exchange-140"},{"speaker":"須貝委員","kind":"確認","question":"私は１６６ページの建築確認事務についてお聞かせ願いたいと思います。先ほどもほかの委員からありましたが、建築確認事務は品川区でやっている事務と、それから民間でも実施していると。それで、実際数字を見ても品川区でやっている建築確認事務が減って、民間のほうは増えている。ところで、確認事務の前の事前相談が、これだけ増えてきている。平成１８年と比較すると、約４割も増えている。","respondent":"中村建築課長","answer":"所要時間としましては、道路などの種別をお聞きになる方は５分ぐらいで終わってしまう場合もあります。設計の詳細に入る場合は１時間ぐらいかかる場合もあります。５分から１時間ぐらい、平均すると大体２０分から３０分ほどと思います。","id":"exchange-141"},{"speaker":"須貝委員","kind":"確認","question":"事前相談というのは任意という話ですが、円滑に建築確認事務を行うためにかなりの方が、ほとんどの方が利用されていると思うんですが、これだけの件数が増えて、１日６０件から８０件、そして、やはり法律、法令の相談ですよね、建築基準法を含めて。そうすると、そこでお聞きしたいんですが、この相談に応じる職員の方は、１級建築士などの資格を持っているんでしょうか。","respondent":"中村建築課長","answer":"建築士の資格につきましては、全員が持っているわけではございません。一部の人間です。今、数については確認をしておりますけれども、全員ではございません。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"全員では仮にないということで、じゃあその中で今相当の件数の方が来庁されて相談をされている。そうすると、この方たちは全員が資格を持っていないということですから、意匠、構造、設備に対してもその方たちが、資格を持っていない方たちが対応されているということですか。","respondent":"中村建築課長","answer":"図面を審査することにつきましては、建築士であることは非常に好ましい、あるべきだと思いますが、現在、実情としましては、資格のない職員もあわせて図面を見たり、あるいは窓口で相談に応じているというのが実情です。","id":"exchange-143"},{"speaker":"須貝委員","kind":"確認","question":"そうすると、皆さんやはり、より正確な、やはりしっかり対応できる、職員の方はもちろん教育を受けているわけですから、それはそれでわかりますが、私は品川区、公で、公のところが許可をしているわけですよね、建築確認ということで。そうすると、安心して品川区に家を建てて住んでいける、そういう安心感を私は持つんじゃないかと思うんですが、その辺についてご見解をお聞かせください。","respondent":"中村建築課長","answer":"今、建築課でも資格を持った人間、１級建築士が９名、２級が３名、建築技術職が約２０名ほどおりますので、半数ぐらいということになりますが、今後も資格の取得に向けて進めてまいりたいと思います。","id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"その方たちもいて、相談に応じる方もいる、それでちょっと私もあれですが、いっとき聞いた中では、建築課はその人数を減らしているという話を聞いたような覚えがあるんですが、私はこれだけ相談件数が増えて、多くの区民の方が安心して建物を建てられて住んでいくということならば、逆に私は区民サービスも含めて、安心感も含めて増員するというのが必要じゃないかなと思うんですが。","respondent":"片田防災まちづくり事業部長","answer":"ただ、一応そういう相談についても、資格を持っていない者が担当したとしても、やはり明らかに言えるものは担当者で対応しますけれども、必ず係長あるいは私のほうにきちっと上がってきますので、適正な審査ができるような体制で現在組んでいるような状況ですし。","id":"exchange-145"},{"speaker":"須貝委員","kind":"確認","question":"ちょっと私はね、どうなんですか、これだけ相談件数が増えているんだから、逆に私は人数を増強して、いなければいいです、相談件数といっても、事前相談といっても、事前審査みたいなものですよね、今ね。その中で何かやりくりしているというのは、まして、これだけ相談件数が増えているというのは、私はちょっと区としても考えていく方向じゃないかなと思いますので、一言ありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"宮崎委員","kind":"質問","question":"初めに聞きたいんですけれども、このビジョンをざっと見ますと、ゆうぽうとと、そしてＴＯＣにどうやって客を誘導するか、そういう計画になっているかというふうに思うんですけれども、なぜこの時期の計画なのかということをちょっと伺いたいと思います。ちなみにこのビジョンを見ますと、いつ時点の、日付がこのビジョンにはないんですけれども、なぜこの時期なのかというのを聞きたいと思います。","respondent":"三宅都市開発課長","answer":"それ以上の具体的な計画はございませんでしたけれども、こちらの地域は、区画整理などが実施されてから４０年ほど経過しているということ、あとＴＯＣをはじめとしまして、この地域の建物の更新が必要な時期に差しかかっている。","id":"exchange-147"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やっぱり今このタイミングを聞いていたので、これはちゃんと的確に答えていただきたいんですよ。ＴＯＣまでの道路と低層階への店舗の配置、誘導ということを言っていますけれども、これは具体的にどういうふうに進めていくのかということを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"具体的な方法としましては、開発の機会をとらえながらそういうものを誘導していくということでございまして、何か強制力を持った形で直ちにどうするというものではございませんが、そういう開発の機会あるいは地区計画といった手法なども視野に入れて整備を働きかける。","id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問","question":"具体的に誘導というふうになると、今の要するに建て替え等にあわせてやっていくんだというのが中心で、法的な拘束力はないというふうに言うんですけれども、そうすると、誘導ということは具体的に何かどういうふうに進めていくのかということを伺いたいと思います。例えば、補助金をどのぐらい入れていくとか、そういう計画があるのかないのか、そこも伺いたいと思います。","respondent":"三宅都市開発課長","answer":"１点目ですが、地区計画というのはもちろんそれが成立すれば強制力を持ってくるわけですけれども、それは最終的にそういうこともあり得るということであって、地区計画をつくるまでにもちろん合意形成という前のプロセスがありますので。","id":"exchange-149"},{"speaker":"宮崎委員","kind":"質問","question":"今、いわゆるハードの点はまだはっきりしたものはない。もしかしたら、これからつくるかもしれない。特に低層部に商店を入れるとか、これは本当に生半可な計画じゃないと思うんですけれども、現時点でどういうふうな合意になっているのか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"ちょっと繰り返しになって申しわけございませんが、こちらはあくまでも市街地整備基本方針で設定されたにぎわいゾーンのもう少し詳細な計画というレベルのものでございまして、地区計画の直前の計画というような具体性。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"質問","question":"そこでちょっと伺いたいんですけれども、ＴＯＣは、実際に先日の請願審査のときのお話では、１００ｍよりも低くなるだろうというお話ですけれども、具体的にどういうふうに伺っていますか。請願審査のときには、かなり緊密に連携をとって連絡をとってやっていると言っていますけれども、このまちづくりビジョンの一番肝心なＴＯＣの計画は今どうなっているか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"都市計画的な手法の活用も含めて何案か比較検討している状況です。したがいまして、幾つも案がありまして、高さ、どうこう、そこら辺はまだ公にご説明できる状況ではございません。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問","question":"これは税金を使ってビジョンをつくってきたやつですね。それで、ＴＯＣにお客を誘導する計画です。今幾つかの案があると言いましたけれども、その主な内容をちょっと伺いたいと思うんですが、よろしくお願いします。","respondent":"三宅都市開発課長","answer":"すみません、先ほどと同じ答弁になりますが、今内部検討を主にやっておりまして、まだ公にできる状況ではございません。ちょっとこちらのビジョンの内容ですが、このＴＯＣのほうにお客さんを誘導することを主目的にしているわけではございません。","id":"exchange-152"},{"speaker":"宮崎委員","kind":"質問","question":"私は、やっぱり税金でつくってきた計画ですから、これは今具体的にどういうふうに検討しているのか、そこのところはしっかり言うべきだと思います。具体的な計画が言えないのであれば、具体的に今のところでは、現状のテナントの数を維持するのか、それとも減る可能性もあるのか、そういうところはどういうふうに考えているんでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"一定の方向性を決めた中で、そういう大きな方針に基づいて指導していくといったような観点からつくったものですので、そういう方向で理解していただければと思います。","id":"exchange-153"},{"speaker":"宮崎委員","kind":"意見","question":"今まちづくり協議会の話もありました。でも、このビジョンを見ますと、まちづくり協議会とはと説明があるんですけれども、具体的にだれが、どういうメンバーがやっているのか、本当にこの地域を、本当に代表できる、そういうメンバーなのかどうなのか、それもわからないんですよね。この点も指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-154"},{"speaker":"井上委員","kind":"質問","question":"私からは、１５８ページの道路維持費、１６２ページの都市計画費の区民の自主的なまちづくりへの支援、１６２ページ、まちづくりマスタープラン推進費についてお伺いをいたします。区民の自主的なまちづくりへの支援についてお伺いをいたします。２０１０年度は、実績は専門家派遣団体が１件、専門家派遣が６件で、先ほどの団体だけが専門家の派遣を利用したというものです。","respondent":"山崎マスタープラン担当課長","answer":"それで、この事業につきましては、先ほども申し上げましたとおり区民が主体的なまちづくりに関与していくために区が必要な支援を行うという非常に根幹な仕組みですので、有効に今後活用できるよう、いろんな意味で改善等々検討してまいりたいというふうに考えてあります。","id":"exchange-155"},{"speaker":"井上委員","kind":"質問","question":"今、地域のまちづくりの熟度だというふうに、区民側の責任であるような発言だったんですけれども、周知とかいろんな部分で改善をする必要があるのかなというふうに思っているんですけれども、まずこの制度を申請するのに提出書類がたくさんあるかと思いますが、申請書が何号まであるのか、そういった煩雑さが活用を躊躇させるのではないかというふうに思うんですが、区の見解を伺います。","respondent":"山崎マスタープラン担当課長","answer":"所要の書式が要綱に定められておりまして、いろいろ変更等々の様式も含めまして、第１５号様式までというようなことで規定しているものです。","id":"exchange-156"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、一度登録したら、相手方から取り消しを求めなければずっとそのままになっているのではないかというふうに思うんですけれども、３年とか５年とか、期限を切って登録の意思確認をするなど、活用を推進しようという意識を持った対応をすべきというふうに思うんですけれども、現状はどのようになっているのでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"まちづくり専門家の登録の状況です。現在登録をいただいております団体は５３団体です。","id":"exchange-157"},{"speaker":"井上委員","kind":"質問・要望","question":"これを簡略化するということとか、あるいは１回１回、団体が登録、派遣をするのに書類を書かなければいけないとか、そういった問題もあるかというふうに思うので、団体が計画するまちづくりの企画や学習会など、パッケージで派遣を依頼できる、そういうふうにするとか、運用を工夫したことで、もっともっとＰＲも可能になるだろうというふうに思うんですが。","respondent":"山崎マスタープラン担当課長","answer":"ただ、公金を支出する際の確認書類として、必要な部分もありますので、いろいろ委員ご指摘の意味も勘案して手続を簡素化できるところはそうした観点で改善に努めてまいりたいというふうに考えてあります。","id":"exchange-158"},{"speaker":"井上委員","kind":"質問・要望","question":"それから次は道路維持費なんですけれども、２０１０年に２３区初の新規事業で、閉庁時のパトロールが始まりまして、昨年の予算特別委員会では既に平日民間事業委託をしているということでしたので、この事業が含まれている清掃等委託の中で、平日の委託料と休日の委託料の決算額をお伺いいたします。そして、これは委託先はどこなのか教えてください。","respondent":"稲田道路公園課長","answer":"閉庁時道路巡回点検委託の決算額は、８６３万３,９４０円です。それから平日のほうですが、道路巡回点検委託という名称でございまして、６,４０７万９,１００円です。こちらの業者ですが、平成２２年度は区内の道路業者です。","id":"exchange-159"},{"speaker":"井上委員","kind":"質問","question":"初めて、２３区初で、休日の緊急対応に備えるということだったんですが、その問題意識の前提で、休日の緊急対応が必要な件数が民間委託前の５年間ぐらいでどのぐらい年度にあったのか教えてください。","respondent":"稲田道路公園課長","answer":"委託前と委託後の土日、休日の緊急委託の件数ですが、正しい把握はしておりませんけれども、基本的には変わらないです。","id":"exchange-160"},{"speaker":"井上委員","kind":"質問・要望","question":"一番言いたいことは、震災対策特別委員会で、災害時など被害調査班が町中に出て調査をしていただいたということを説明を受けまして、日頃から民間任せではなくて、区の職員の方々がまちのことを知っていただいているということは、震災に対して本当に区民にとって安心感があるということで、本当は実績を伺ってから、必要がないのではないでしょうかと言いたかったんですけれども。","respondent":"山崎マスタープラン担当課長","answer":"市民参加ということの観点では、基本的にはマスタープランの策定の状況は、ホームページ等々で公表するようなこと、それからパブリックコメントをするというような基本的なことから、広報のほうのさまざまなツールを使いまして。","id":"exchange-161"},{"speaker":"井上委員","kind":"意見","question":"本来マスタープランの策定というのは、前回のマスタープラン作成にも市民参加を保証するということが定義づけられていたかと思います。今回計画についてパブリックコメントという中ではなくて、計画策定時に参加をしていくことでないと、パブリックコメントはなかなか難しいと……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-162"},{"speaker":"若林委員","kind":"確認","question":"１５８ページの街路樹等維持管理費から１６３ページの公園管理費に入ると思います。街路樹のほうは、今回９月２１日、先ほどもお話が出ておりまして、区で区有の樹木というんでしょうか、４４本が倒木をしたというふうなことでございました。その事実関係を確認するのが一つと、正しいとすれば、いずれにしても流された原因というのはどういうところにあるのかというのを一つお聞きをしておきたいと思います。","respondent":"稲田道路公園課長、藤田水とみどりの課長","answer":"そういうことで、今後より一層の点検、それから対応をしていきたいと思うんですが、専門家等も入れながら考えていきたいと、一部やっていきたいと考えています。２月に流出をしまして、その後腐食により流れてしまったということで、港湾局のほうで今後の維持管理をしっかりできるような維持管理の計画書を提出しなさいということが今求められておりまして。","id":"exchange-163"},{"speaker":"若林委員","kind":"提案","question":"私、款別かなんかのずっと前ですけども、こういう専門家、樹木医の紹介をしながらご提案をさせていただいたことがありますので、これからそういう樹木医等の専門家を交えて今後の対策を立てていくということでよろしいか、一つ確認をさせていただきたいのと、木が倒れるというのは、ちょうど今だんだん秋になってきましたけども。","respondent":"岩田都市環境事業部長、藤田水とみどりの課長","answer":"委員ご指摘のように普通は台風以前に夏季剪定、特に覆い繁るような樹木等については、夏季剪定で葉っぱをかなり落として風速に耐えられるような形状に整えてはおりますけれども。その辺を含めまして、防災面、それからにぎわい、そういった面の活用を広げていきたいというふうに考えてあります。船を持つことにつきましては、さまざまな面から検討させていただきたいと思います。","id":"exchange-164"},{"speaker":"松澤委員","kind":"質問","question":"自分の質問に入ります前に、先ほど倒木、木が倒れちゃった後どうするの。特にあそこの鮫洲運動公園は、子どもたちの意を取り入れてつくった公園ですから、それとの整合性も図らなくちゃいけないかなというふうに考えたときに、すぐやりますという答弁はちょっと安易過ぎたかなということで苦言を呈しておきます。成果報告書の１６０ページ、踏切改良事業４３８万円、この事業内容についてお知らせください。","respondent":"武藤都市整備下水道課長","answer":"踏切改良事業についてのご質問ですけれども、道路幅員の狭い踏切道におきまして、踏切内の拡幅を行うほか、交通安全の観点から当該部分をカラー化して、車の運転手に歩行者の通行帯を認識させるなどの事業です。","id":"exchange-165"},{"speaker":"松澤委員","kind":"質問","question":"簡単にお答えをいただきました。これはたしか３カ所の改良工事で、最後かな、苗木原踏切あるいは下神明１号踏切、戸越銀座の駅の南側ですかね、これの最後の工事かなということで、やっと終わったなというような感じで質問させていただきました。","respondent":"山崎マスタープラン担当課長","answer":"大井町線は５両編成でございまして、現在大井町から下神明側に向かって下神明２号踏切を車両が２両ふさぐ形で停車をするということで、５両編成に必要なホームの長さが戸越公園の場合は得られていない状況だということで、大井町側から向かいまして。","id":"exchange-166"},{"speaker":"松澤委員","kind":"質問","question":"ただ、区にするとメリットよりもデメリット、区道を整備しなくちゃいけない、見守らなくちゃいけないという負担が多いように感じるんですけれども、そのメリット、デメリットを考えたときに、品川区はどのように東急電鉄側に、今地域貢献施設ということで、いろいろこういうふうにしなさい、先ほども旗の台駅の南口でしょうかね、駐輪場をつくる約束なのにつくっていないという話がありましたけれども。","respondent":"山崎マスタープラン担当課長","answer":"今回のドアの開閉を解消するというところで、戸越公園利用者の利便性の向上、それから何にも増して、車両が踏切をまたぐ形でとまっているということで、１時間に４０分以上踏切がしまっているような状態、いわゆるボトルネック踏切というような表現をしておりますけれども。","id":"exchange-167"},{"speaker":"松澤委員","kind":"質問","question":"そういうことで地元でも運動しているんですけれども、東急電鉄側としてはこの国土交通省からいわれていた踏切の解消をしてしまうと、いや、まだまだ先でもいいじゃないかと先延ばしになるんじゃないかというふうに私は思っているんですけれども、この辺、東急電鉄側から高架化について地元と話をしていますけれども、しっかりと進めていきますよというしっかりとしたコメントはとっているんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"東急電鉄のほうは、今回のホームドアの件の解消が図られた後も連立化の検討に向けて区あるいは地元のほうと協議は進めていくということで聞いております。","id":"exchange-168"},{"speaker":"松澤委員","kind":"質問・要望","question":"よくわかりました。次の質問ということで、同じく１６０ページの排水施設建設事業、出水対策・立坑原状回復工事費、これが上げられていますけれども、これは戸越幹線ができたんだけども、原因不明の出水があったということで、今それが直されて、今現在は公園もでき上がっていますけれども、この原因というものがはっきりわかったんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"これにつきましては、東京都も含めて検討の調査委員会を立ち上げまして、原因について究明をしましたが、水が出てきている状況は把握できたんですけれども、その根本的な原因については究明ができなかったというものです。","id":"exchange-169"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。それで了としておきます。１時間換算で４８mm、品川区は５０mm対応ですから、それで水が出なかったのかなとは思いますけれども、床上・床下浸水はありませんでした。このときに目黒川の雨水貯留池、あるいは西品川の貯留池、戸越幹線の今言いました地下の貯留管、あるいは第二立会川幹線、これがどのような働きをしたのかということを教えていただきたいと思います。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり品川区内につきましては、１時間５０mmに対応できる下水道の整備を進めているところですけれども、さまざまな今ご指摘のような貯留管が整備されまして、当日９月のときの雨の状況なんですけれども、河川の調節池については流入はございませんでしたが。","id":"exchange-170"},{"speaker":"松澤委員","kind":"確認","question":"そうしますと、目黒川の貯留池には入ったけども、第二立会川幹線とか戸越の幹線は水を入れるに至らなかったということなんでしょうか、確認したいと思います。","respondent":"武藤都市整備下水道課長","answer":"もう１回確認しますが、河川の目黒川の調節池には流入はございませんでした。その他下水道の調整池、区内に何カ所か、約８カ所程度ありますけれども、そのうち約５カ所の調整池において流入が確認されております。","id":"exchange-171"},{"speaker":"松澤委員","kind":"確認","question":"そうしますと、調整池が十分に働いたということで、現状５０mm対応ができましたよということですけれども、実際にそれができたということで、今後ともまだ余裕があるということでよろしいですよね。その確認だけして質問を終わりたいと思います。","respondent":"武藤都市整備下水道課長","answer":"実際降る雨につきましては、さまざまな降り方がありますので、一概に余裕があるという形にはなかなか申し上げられないんですけれども、今の設計上の考えであれば、１時間５０mmに近い雨に対応できるという考え方で今整備ができているという状況です。","id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/796486?Template=document&Id=1348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":111068,"voices":391}},{"id":"h23-20111013-4","meetingId":"h23-c-settlement","date":"2011年10月13日","dateIso":"2011-10-13","committee":"決算特別委員会","time":"午前１０時００分～午後５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件抜き出しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計歳入歳出決算","agenda":"平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"成果報告書の１７２ページ、教科書採択事務についてお伺いさせていただきたいと思います。本区の教科書採択の仕組み、検討委員会での絞り込みはなかったとのことですけれども、そういったことも含めて、どういう仕組みになっているのか、また一般質問で教育長よりご答弁いただいた公平・公正とは何をもっての公平・公正で、基準は何なのかご答弁いただきたいと思います。","respondent":"冠木指導課長","answer":"この報告を学識経験者や保護者、地域の代表等からなる教科用図書調査検討委員会において、その分析や表現が適切であるかどうかを検討し、調査資料として教育委員会に提出をしていただいております。今、委員のお話のように、絞り込み等は一切ございません。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"その領土に関してなんですけれども、北方領土が我が国の固有の領土であることなどの「など」には、竹島や尖閣諸島が我が国の領土であることも入るのでしょうか。例えば教員からこういった質問が来た場合は、どのようにお答えになられるのでしょうか。","respondent":"冠木指導課長","answer":"教員からそういった質問が教育委員会にあった場合は、固有の領土というふうに指導するように説明をしておりますが、そういった事例はございませんので、教員はすべてそういった見解で指導しています。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"今の答弁の整合性から考えて、また政府の見解や歴史的経緯、何を見ても、竹島が不法占拠であって、尖閣諸島は領海侵犯が繰り返されているということを、教科書の記述はこうなっていますが、今、現場の教員が明確にこの点がはっきりと、教科書はこういう記述であったが違うということを指導していくことが大切だと思いますが、今、指導課長がご説明されたとおり、そういったことを教員に指導というか。","respondent":"冠木指導課長","answer":"何より日本の固有の領土であるということは間違いのないことです。私どもとしましては、まず小中一貫教育要領に明記をいたしまして、学校を指導していますので、そういった点につきましては、今後も日本の固有の領土だということで指導するように指導しています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのときのやりとりで、メールが使えないという教員がいらしたんですけれども、何かしらの理由があってのことだと思うので、その教員についてとやかく言うつもりはありませんけれども、一応確認させていただきたいんですけれども、品川区では教員１人に１台ずつパソコンを支給しているということですけれども、その利用についての講習、または使いこなせているのかということと。","respondent":"冠木指導課長","answer":"ただあまり神経質になり過ぎますと、仕事の進みぐあいにご迷惑をかけるということもありますので、その辺は適切に渉外活動ができますように指導してまいりたいと思います。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったこともあると思うんですけれども、せっかくパソコンが１人１台ある以上、先生方が使えるような講習とか研修を進めていただいて、なかなか対外的にほかの会社の方とかとやりとりをするとか、学校以外の方とやりとりするときに、メールが使えないというのは今の時代ではおかしいなと思うので、その辺の改善はしていただきたいと思います。","respondent":"冠木指導課長","answer":"平成２２年度のデータでお答えいたします。８８件ということで、品川区のほうにご視察いただいております。人数は４６７名です。","id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"それは主にどういった内容で視察に、品川区は小中一貫教育をやられているということとか、そういったこともあると思いますが、どういった内容が一番視察にいらっしゃる方が多いのかというのをお聞かせください。","respondent":"冠木指導課長","answer":"一番多いのは小中一貫教育についてのご視察です。続いて市民科について、それから幼少連携という順になっております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"それと次、１７２ページの文化財保護費のところでもちょっと質問させていただきたいと思います。これも第２回定例会の一般質問で行ったんですけれども、区指定の天然記念物保存樹についてということで質問させていただきました。その後どうなられているでしょうか。","respondent":"齋藤庶務課長","answer":"天然記念物の木をお持ちの方、１３人の方が保存樹と同じサービスを受けたい、７人はこのまま継続したい、３人の方は検討中ということで、以上、そのような形で対応させていただいているところです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"樹木を管理する上では、天然記念物とはいっても教育委員会の所管になっていますけれども、保存樹は水とみどりの課が管理する。行政の効率的な観点からもぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"私は質問順に、成果報告書１６８ページの教職員人材育成経費の同和教育指導推進委員会、１７１ページの調査研究等受託事業、１６９ページのプラン２１推進事業のマナーキッズ教室委託、１７１ページの経済活動体験学習経費、同じく１７１ページのすまいるスクールについてお尋ねいたします。初めに、同和教育指導推進委員会と調査研究等受託事業についてお尋ねいたします。","respondent":"冠木指導課長","answer":"１点目の件ですけれども、私ども子どもたちにあらゆる差別や偏見はしてはいけないものだということで、当然学校でも指導しておりますし、あるいはご家庭でもそういった指導をしていただけるようにお願いをしていますけれども、子どもたちの世界というのは。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"先日も私、総務費の質問で紹介させていただきました。このようなことも取り入れていただき、より一層の人権教育、人権尊重の態度育成に取り組んでいただきたいと思います。次に、マナーキッズ教室委託についてお尋ねいたします。マナーキッズ教室の内容と対象年齢、それとこの教室がいつから行われているのかについてお尋ねしたいと思います。短期の委託事業なのか、簡単で結構ですので、教えてください。","respondent":"冠木指導課長","answer":"始まったのは平成２０年からでございまして、今、幼稚園なども入りまして、順次学校数は増えているところでございまして、今、約３０校ほど取り組んでいるところです。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問","question":"今、お聞きした限りであっても、スポーツを通じてそうしたマナーを教えていく、非常に大事なことかなと思います。テニスを通じてというところを本当に率直にうれしく思いましたけれども、テニス以外のほかのスポーツにも展開していく予定はありますでしょうか。今後検討しながらとありましたけれども、教えてください。","respondent":"冠木指導課長","answer":"例えばサッカーなどの取り組みの中でも、リスペクトといいますか、選手同士がきちっとあいさつをして握手をするというような取り組みが行われておりますので、応用の範囲は広いかなと思ってあります。先ほどの検討の中でそういったところは議論になっております。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"ほかのスポーツへの展開も含めて、より一層の充実をご検討いただきたいと思います。次に、経済活動体験学習経費についてお尋ねいたします。平成２１年の成果報告書の同費目のブランチには、スチューデント・シティとファイナンス・パークがそれぞれ記載されていて、平成２２年度に記載がないのは、八潮学園から品川学園への移設に伴う一時的な閉鎖で実施しなかったということでしょうか。","respondent":"冠木指導課長","answer":"これは委員のお話のように、この平成２２年度はスチューデント・シティとファイナンス・パークが引越しということで、八潮学園のほうから、今現在は品川学園のほうに来ておりますけれども、その関係で実施しておりません。","id":"exchange-012"},{"speaker":"鶴委員","kind":"確認","question":"私が確認する中では、平成１８年から導入されているかと思います。５年経過しましたが、この言われるところの進路選択や将来設計について、何か具体的な事例や報告はありますでしょうか。","respondent":"冠木指導課長","answer":"さらに品川区の納税者として育っていってくれるように、応援してまいりたいと考えています。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"そのものの目的は少しずつ見えてきているのかなと。そこでお尋ねします。日本では江東区豊洲と兵庫県西宮市にある子ども向けの体験型テーマパーク、キッザニアがありますが、ここはご存じのとおり、約８０の職種が体験できる施設です。当然規模の問題になりますけれども、将来的に体験できる職種を拡大する、そうした可能性はありますでしょうか。","respondent":"冠木指導課長","answer":"それで社会全体がつながって、自分たちの経済活動に生きてくるんだなと、生かされているんだなというような考え方から、お願いする企業の設定にしましても、そういった私どもの基本的な制度設計の中で業種を選んだりというところでご賛同いただいているですので。","id":"exchange-014"},{"speaker":"鶴委員","kind":"確認","question":"すまいるスクールについてお尋ねいたします。１０月９日に放送された日本テレビの朝の情報番組、「シューイチ」ですまいるスクールが紹介されたのを拝見しました。そこでお尋ねしますが、すまいるスクールの参加児童のうち、要配慮児、特別支援児の登録数と登録率、参加数と参加率を、それぞれ確認の意味で教えてください。","respondent":"齋藤庶務課長","answer":"区内には特別支援学校から来られているお子さんが７名いらっしゃいます。区内の小学校に８つの特別支援学校がありまして、９０人の方がすまいるスクールに登録されております。普通教室に通われていらっしゃいますが、介護等を必要とされている方が１８０名おります。","id":"exchange-015"},{"speaker":"鶴委員","kind":"質問","question":"平成２３年度の小学生全体の登録率が９,１１７人で７１％、参加率は今、３５.数％とご答弁いただきました。そこでお尋ねいたしますが、要配慮児、特別支援児の放課後対策として、すまいるスクールとしてどの程度の障害をお持ちの方を受け入れることができるのか、教えてください。","respondent":"齋藤庶務課長","answer":"登録にあたって、区の職員が必ず特別支援学校や特別支援学級に行って、支援のコーディネーター、養護教諭の方とお話し合いをして、すまいるスクールでの指導が対応できるかということを確認してお受けしているです。","id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"ちょっと専門的な部分になるかもしれませんけれども、医学的措置の詳細というか、わかる範囲で教えてください。","respondent":"齋藤庶務課長","answer":"具体的に申しますと、注射をするだとか、あとは一定の処置、家族ならできる処置、他人はできない処置、いろいろな病気によって程度が違いますので、それは個々のお子さんの状況を確認しながら、医学的な視点で相談、アドバイスをいただいて対応しています。","id":"exchange-017"},{"speaker":"鶴委員","kind":"質問・要望","question":"さまざま全体的なことも含めて今、見直しをされていると思いますけれども、またその中で受益者負担をどうするのかという議論もあるようですけれども、障害の程度にかかわらず利用ができる、そうしたすまいるスクールの体制を整備していただきたいと思いますが、ご所見を伺います。","respondent":"齋藤庶務課長","answer":"すまいるスクールはあくまで学校の現場で対応しているということがあります。物理的に特定の医療行為を伴うものにつきましては、なかなか学校施設では難しいということでございまして、可能な限り引き続き受け入れをしていきたいと考えています。","id":"exchange-018"},{"speaker":"鶴委員","kind":"意見","question":"逆に健常者の方も、今度はそうしたどりいみんぐが運営していただいているようなところにも足を運んで、そうしたことにもサポートしていくとか、そういったことも幅広く含めて、主の目的を外さない中で、そうした障害のある方もすまいるスクールに積極的に参加ができるような体制の検討を、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１７４ページ、学校環境整備事業、１６９ページ、小中一貫教育推進経費、１６８ページの区教員経費についてお伺いさせていただきたいと思います。１７４ページ、学校環境整備事業で、関連しまして、校庭芝生化についてご質問させていただきたいと思います。それとまたそのグラウンドごとでどのくらいの年で更新をしていき、幾らぐらいの費用がかかるのか、わかれば教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"天然芝ですけれども、これは毎年、現時点で２５０万円ほどかけて養生しておりますので、養生を繰り返していくということです。土の場合は、１,３００万円から１,５００万円かけて、おおむね１５年を更新時期と見て、計画的に対応しています。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"そして天然芝の身体的効果というかメリット、教育的な効果、そういった部分も教えていただければと思います。第一日野小学校や第三日野小学校、先ほどだと鮫浜小学校でしたっけ。限られた学校で天然、人工芝のグラウンドになっているということなんですが、なぜそこになったのか教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"第三日野小学校は地盤が池田山公園、ずっと下にあって水はけが悪いので、人工芝にすることで稼働率を高めたいということで考えております。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"校庭に芝生と人工芝で今、学校の校庭で放射能測定とかをされておりますが、人工芝と土、天然芝で違いがあったら教えていただきたいと思います。校庭の放射能測定の結果と概要等を教えていただきたいのと、また仮にそうしたグラウンドが除染が必要になった場合は、どういった方法があるのかなというところと、区としてどのような対応をとっていくのかというお考えがあれば、教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"したがって、土壌について区のほうで入れかえる、あるいはかえなければいけないという事情はありませんけれども、放射線が高かった場合の対応につきましては、文部科学省から通知がございまして、土壌については２つ、表層の５cmを削って。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"それと関連してなんですけれども、１７９ページの校庭芝生管理用備品購入等というのがあるんですが、これは６００万円ぐらいかかっていると思うんですが、これは何校でそのぐらいかかっているのかというか、１校だったら、これは毎年かかるものなのか、ちょっとそこだけ教えていただければと思います。","respondent":"和氣学務課長","answer":"これは芝刈機等を基本的に今後養生していただくために、今、ボランティアにやっていただいておりますが、そのための備品等でございまして、１回限りのものです。","id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"続いて１６９ページ、小中一貫校教育推進経費に関連いたしまして、初日、款をまたいで入ってしまったんですが、武道必修についてお伺いをしたいと思うんですが、武道の授業の内容、今、どういった授業が行われているかを教えていただきたいのと、その目的というか、教育面としての武道の目的と、今までやってきた子どもに関する成果、子どもたちにどういった変化があったとかというのがもしわかれば。","respondent":"冠木指導課長","answer":"武道についてお答えいたします。内容ですが、小学校におきましては、柔道に取り組んでいる学校が２５校、剣道が１１校、相撲が２校です。中学校においては、柔道が１４校、剣道が２校、その柔道、剣道両方ともやれるという状況を整えている学校が１校です。","id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"あいさつがちゃんとできるようにするという、どちらかというと技術的な部分というよりも、そうした礼節だったり精神的な部分なのかなという中で、なぜ今、柔道と剣道と相撲がありますが、その武道になったのかちょっと疑問に思いましたので、そこをお答えいただきたいのと、また指導者確保も基本的には教員ということなんですが、小学校だとそれでいいのかもしれないかなと思ったんですが。","respondent":"冠木指導課長","answer":"そんなところをバリエーションをいろいろと仕組みながら、この授業は進めていきたいと思ってありますけれども、当然地域の協力者であるとか、今、委員がお話しのスポーツ団体ともご協力をいただきながら進めてまいりたいと思ってあります。","id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"中学校に関してもさまざま競技、小学校から続けていく中で、上手になったら、例えば部活に入ろうとか、地域の剣道教室だったり、柔道教室だったりに行こうという中で、そうしたところでぜひこれからも力を入れて取り組んでいただきたいなと思ってはいるんですが、例えば小学校に関しては、心の成長ということで取り入れているということですが、例えばそれが何で５年生なのか、例えば小３とか。","respondent":"冠木指導課長","answer":"国のほうの学習指導要領ですと、武道については中学生からということになっておりまして、そこを品川区としては小中一貫教育要領ということで５年生から取り組んでいるところでございまして、そういった中で、文部科学省とのいろいろな話し合いの中でも、指導する中身と。","id":"exchange-026"},{"speaker":"大倉委員","kind":"質問・要望","question":"これで武道のほうは終わりたいと思います。最後に、１６８ページ、区教員経費で、品川区で独自採用している区の教員のことについてお伺いさせていただきたいと思います。例えば採用後、働く現場が都と区の職員が同じで働くわけですから、そうした中で「ちょっとおまえ、何だ」という、そういった部分があったりするのかなと。そこで区の採用の待遇の違いがあるのかないのか教えていただきたいと思います。","respondent":"冠木指導課長","answer":"当然学校の中での仕事を一緒にやるわけですから、委員のようなお話は一切ございませんし、それでは仕事が回っていかないわけですので、学校の中で一致団結して子どもたちの教育にあたっているです。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"私立の大学とかの面接対策とかもかなり行われていて、そうした中で、例えば実習に結構行っている人のほうが不利になったり、面接の練習をなかなか時間がとれなくてできないとかという方がいる中で、品川区としては、区の教員採用に関してどういった基準があるのか教えていただきたいと思います。","respondent":"冠木指導課長","answer":"そういったところで、人間性も豊かで力も持っている教員を採用してまいりたいと思ってあります。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうした熱意がある方を採用しているということで、安心をしておりますが、ちょっとこれは款が変わってしまうかもしれないんですが、ちょっと仕事が増えている中ですが、国でも３０人学級というのを目指していると思うんですが、品川区としてもそうした教員の採用を増やして、３０人学級というのができるように目指していくのかなというところがあれば、ぜひお聞かせいただきたいのと、例えば人が増えると。","respondent":"和氣学務課長","answer":"この導入は３０人学級を目指してやっているものではございませんので、全く別物です。品川区の教育を充実させるために、品川区に意欲を持って働く教員を採用しているところで、５年をもって終了と考えています。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１７５ページ、学校運営費、通学路の安全監視に関連してと、もう一つ同じ１７５ページで教育振興費、就学援助について伺いたいと思います。都市環境事業部長はそういう答弁でしたけれども、私どもは子どもたちが集まるところは安全を確保しなければいけない、調査が必要だと思うんですけれども、教育委員会は都市環境事業部長と同じような考え方なのか、伺いたいと思います。","respondent":"齋藤庶務課長","answer":"教育委員会といたしましても、環境課を中心した区長部局と連携しながら、対応については検討しているところで、考え方は同じです。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"世田谷区と大田区であったら、大体品川区もあるのではないかというのが普通の感覚だと思うんですね。これは私は普通の対応だと思うんですけれども、区と同じ対応だということですと、ホットスポット探しというのが風評被害を広げるからやらないというお答えでしたけれども、なぜホットスポットを探すことが風評被害を広げることになるのか。教育委員会の立場でわかりやすく説明いただきたいと思います。","respondent":"齋藤庶務課長","answer":"都合、土壌検査も１００カ所近くで行っておりまして、品川区の地図、２２km2をプロットで、メッシュで落としましても、ホットスポットを探す必要があるという値は出ていない。したがいまして、私どもとしては、教育委員会といたしましても区長部局と同様の考えです。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"そこを調査して、雨水で流れてきて、水が蒸発したら凝縮されていたということでしたけれども、今の、例えば校庭ですと、大体真ん中あたりを調査するとか、そういうことが中心ですけれども、それで安全だと言っているのが、私はどうも理解できないんですけれども、例えばそういう雨水がたまりそうなところをなぜ調査しないのか、そこのところを伺いたいと思います。この違いは何なのか。","respondent":"岩田都市環境事業部長","answer":"先ほど庶務課長がお答えしましたように、基本的には２カ所の定点観測がベースになるわけですけれども、区はそれ以外に土壌およびプールの水の測定を全施設において行っているわけです。その結果が今月いっぱいで一巡しますので、全施設の測定が終了します。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、各所管のところで必要だというところは調査していくということだと。そうすると、区の教育委員会がどういう対応をするのか、どういう考え方なのかということを改めて伺いたいと思います。","respondent":"齋藤庶務課長","answer":"今の都市環境事業部長の答弁と全く同趣旨でございまして、先般の校長会でも、今度新しい機械が２台入る。必要に応じて、区が庶務課ではかる、場合によっては学校ではかるということで対応するということにしておりますので、区長部局、教育委員会とも見解は全く同じです。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"必要なところを調査するということで、ぜひお願いしたい。こっちのほうでも出て、これとダブっていないだろうと思うんですけれども、そうすると、就学援助の基準以下の方というか、これはこの人数よりも生活保護を受けている方もプラスになるということだと思うんですけれども、それもあわせて伺いたいと思います。","respondent":"和氣学務課長","answer":"認定数は日々変わりますので、ここに書かれている数字が実数と考えていただくしかありません。転出入があります。認定が取り消しになる場合もあれば、途中から認定になる場合もありますので、これは実数というふうにお考えいただきたいと思います。平均的な数といえます。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"一方、先生方のところでは、例えば給食費がなかなか集まらないとかという声も聞くんですけれども、そうすると、かなり就学援助を受けている方というか、またそれのボーダーというか、あるいは対象になっているけれども、あえて申請していないとか、そういう方もいらっしゃるんじゃないかと思うんですけれども、そこら辺の認識がどうなのかということを伺いたいと思います。","respondent":"和氣学務課長","answer":"ですから、私どもはボーダーの人で滞納になっている人がいて、就学援助を受けられるという方については、その場で課税の申告の指導までして就学援助を受けていただいて、給食費の未納を防いですので、結果未納率が０.０８％という大変低い数値に抑えられているです。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、この子どもたちの教育に関しての負担を増やしていかないという対応は、今年の予算特別委員会のときも、私ももっと無償化等を広げる必要があるのではないかという要望をしました。具体的にどういうふうになっているのか伺いたいと思います。それと小中一貫の標準服も援助をやっていきますけれども、あわせてほかの援助の拡大については、何かあるのかないのか伺いたいと思います。","respondent":"和氣学務課長","answer":"それから就学援助の拡大をという話ですけれども、これにつきましては、私どもは父母負担調査というのをやっておりまして、実際に幾ら各学校で払っているかというのを確認していますので、それとあわせながら、それを平均的に見ながら。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと時間がないので、私がぜひ検討していただきたいのは、例えば特に卒業アルバム代ですと、子どもの多い、少ないで負担も変わってくる。こういうのはやっぱり不公平になってきますので、特に全員が対応する、関係するところの負担減、こうしたアンバランスのところの対応をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は成果報告書の１７７ページの学校保健費と、１７０ページの教育指導費の市民科・各教科充実経費についてお伺いしたいと思います。成果報告書１７７ページの第４目学校保健費の児童・生徒健康管理費のうち、寄生虫卵検査についてお尋ねいたします。小学校費から６９万円が支出されておりますが、これはどのような検査なのか、具体的なご説明をお願いいたします。","respondent":"和氣学務課長","answer":"寄生虫は小学校１年生から３年生に対して実施をしてございまして、検査方法としましては、シールでやってあります。","id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最近、無農薬野菜だとか食の多様化によって、回虫だとか、俗にサナダムシという条虫、このような寄生虫は貧血だとか、倒れてしまうとか、栄養障害とか、激烈な症状を起こすので、こういう寄生虫というのは十分検査して駆虫することというのは非常に大切なことなんですが、先ほどお話ししたように、現在行われているぎょう虫の検査というのは、ほとんど無症状で。","respondent":"和氣学務課長","answer":"この検査につきましては、医師会ともしくは、学校医と相談をしながら今後どうしていくか決めてありますので、今のところは変更するという話もありませんし、必要ないというご意見は今のところいただいていないので。","id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"成果報告書の１７０ページのマナーキッズ教室についてお尋ねいたします。さらに具体的に言いますと、このテニスを行うことによって、あいさつとお礼を身につけさせるというお話でしたが、このマナーキッズ教室というのはテニスをするだけなんでしょうか。テニスをすることに始まってテニスをすることで終わる、要するにスポーツ教室と同じような形態の事業だと理解してもよろしいでしょうか。","respondent":"冠木指導課長","answer":"このマナーキッズの事業の流れといたしましては、当然テニスの中で相手方との握手であるかと、目と目を合わせてあいさつをする、そういう活動がありますが、その後で参加者を集めまして、講師はいろいろな方が入っておられますけれども。","id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私もお子様相手に日々診療しているわけでありますが、非常に友達感覚というか、公と私事、公と私の区別をつけることができないお子様というのが非常に目につきます。そのような観点からの教育というのは、もっと充実させたほうがいいのではないかと私は考えるんですが、これに関して区のご見解、取り組みの仕方をお伺いしたいと思います。","respondent":"冠木指導課長","answer":"いろいろなご評価をいただきましたけれども、その中に意義をきちっと保護者に伝える、そういう活動もしているところでございまして、さらに充実させてまいりたいと思います。","id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今後ともご努力をよろしくお願いいたします。質問を終わります。","respondent":"和氣学務課長","answer":"原委員。","id":"exchange-042"},{"speaker":"原委員","kind":"質問・要望","question":"成果報告書の１６８ページ、教育委員会費、１７１ページのすまいるスクール、やはり成果報告書１７６ページの学校給食費、これに関連してお伺いしていきます。括弧して限界値２ベクレルと書いてあります。品川区が購入されたのは高精度とありましたけれども、これはゲルマニウムの半導体、ゲルマニウム半導体でなくてもいいんですけれども、給食の食材の数値確認ができるものかどうか、そこが１点です。","respondent":"和氣学務課長、岩田都市環境事業部長","answer":"ですから、ほかの区も実は本当に１回限りで終わりであるとか、ほとんどすべてが食べた後に検査をして、後から結果が出るですので、ご趣旨のことは、気持ちは非常によくわかりますが。最近、安い機材で数時間でできるものも出たようですけれども、やはりきちっとはかるには二、三日かかるということで、先ほどの学務課長のお答えのとおりになります。","id":"exchange-043"},{"speaker":"原委員","kind":"質問・要望","question":"ご丁寧なご説明ありがとうあります。ですから、これは都、国、その辺に再度強く要求をしていただきたいと思います。先ほど申し上げたように、教育委員会費とすまいるスクールについて伺います。実際に全国で今、１６０を超える箇所に広がっているという話も聞いております。それは小中一貫校だけではなくて、プラン２１、この辺まで広くなっても結構ですけれども、その辺のご見解をいただければと思います。","respondent":"冠木指導課長、齋藤庶務課長","answer":"後半の私ども品川区の教育の今までの流れと今後の展望といいますか、そういったところでの全体的なご質問と伺いましたけれども、小中一貫教育を平成１８年度から導入いたしまして展開してまいりまして、学力であるとか。したがいまして、正規職員１人、非常勤が１人、その他は民間のスタッフで対応しておりまして、常時１日当たり２３０人のスタッフですまいるスクールを運営しています。","id":"exchange-044"},{"speaker":"原委員","kind":"意見","question":"すまいるスクールからなんですけれども、やはり質と量、今、２３０人というお話だったんですけれども、ちょっと気になるのが臨時職員のところなんですけれども、臨時職員もそうですし、気になるのはもう一つ、先ほどの一つ目の教育委員の報酬ですね。それは何かといいますと、実際に品川区の教育に対する成果が上がっていないのであればそうではないという。この２点をお答えいただければと思います。","respondent":"齋藤庶務課長","answer":"今の最低賃金が８３７円です。２時間半、おおむね５時間来ていただいて、仕事の質の量としては見合いだと考えております。教育委員の報酬につきましては、他の行政委員とのバランス、勤務していただいている内容に応じて適切なものだと私どもは考えております。","id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問","question":"私からは、１７２ページ、社会教育費、ＰＴＡ関係費から校庭開放についてまず伺います。続きまして１７７ページ、学校保健費、児童・生徒健康管理費について伺います。１点目の校庭開放について。ＰＴＡ関係費の２,８７２万円余のうち８６０万円余という大きな割合を占めている校庭開放ですが、どのような内容なのか教えてください。","respondent":"齋藤庶務課長","answer":"日曜日や夏休みなど、９時から５時の間、子どもたちが遊ぶ場所ということで提供させてもらっております。ただその見守り、サポートの仕事は各ＰＴＡにお願いしております。ＰＴＡに委託料としてお支払いしている金額がこの金額のほとんどになります。","id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問","question":"もう一点、続けてお伺いするんですが、ＰＴＡの方へ報酬、協力費として支出しているものということだったんですが、これは１日当たりお幾ら支払われるのか、金額というのは学校ごとに違うものなのでしょうか。","respondent":"齋藤庶務課長","answer":"指導員の謝礼は、お一人当たり、半日は９００円、１日お願いする場合は１,８００円ということになっております。お支払いする金額は、半日を開放するか、１日中開放するか、各学校ごとに計画がありますので、計画数に応じて前払いをしているということになっております。","id":"exchange-047"},{"speaker":"阿久津委員","kind":"質問","question":"この校庭開放の運営にかかわることで、ちょっと細かいことでご相談を受けたものですから、本当に細かいことなんですが、ちょっと質問します。１点目なんですけれども、指導員への協力費の支払いと受け取りについてです。協力費を払ってしまえばそれは手を離れてＰＴＡ内部の話になってしまうのかもしれないんですが、このようなお悩み、教育委員会として把握をされていますでしょうか。","respondent":"齋藤庶務課長","answer":"基本的にはＰＴＡにお願いしている事業で、ＰＴＡの内部自律といいますか、ＰＴＡの中でご検討、解決していただくべきことだと考えています。ＰＴＡの皆さんとお話し合いをする場もありますので、いただいたお話を十分お伝えして、解決策を模索するように努めてまいります。","id":"exchange-048"},{"speaker":"阿久津委員","kind":"提案","question":"中にはこの協力費をＰＴＡ費として積み立てて使いたいと思っている方が多くいらっしゃると伺っています。そこでご提案なんですけれども、例えばＰＴＡの方が協力者として登録をする場合に、自分は協力費として受け取らないで、これを遊具等の購入に充てる、ＰＴＡ費として積み立ててほしいとい明白な意思表示があった場合に、この場合はＰＴＡ費の積み立ての流用というのは可能にならないんでしょうか。","respondent":"齋藤庶務課長","answer":"そして実績に応じて、校庭開放しない場合は返していただく、そういう財務会計の仕組みがありますので、直接ＰＴＡの会費へそのまま流用というのはちょっと難しいと思いますが、例えば受け取っていただいて、指定寄附、この学校の遊具を買ってくださいなど。","id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問・要望","question":"続きまして１７７ページ、学校保健費、児童・生徒健康管理費、関連して脳脊髄液減少症の周知についてお伺いします。平成２１年第３回定例会で、我が会派の金野委員より、この病気について質問、要望しておりますが、改めて学校においての対応について伺います。お伺いしますが、教育委員会が把握している中で、本区には脳脊髄液減少症の児童・生徒がいるかどうか、お教えください。","respondent":"和氣学務課長","answer":"そこで私どもはそこを受けて、養護の先生を中心に、担任とも協力をしながら、授業であるとか、日常生活であるとか、それぞれの注意を払って、もしくは言動とかに注意を払って、差別が起こらないような形で対応してまいりたいと考えていますので。","id":"exchange-050"},{"speaker":"阿久津委員","kind":"質問","question":"私も平成１９年以来、お子様がこの病と戦っておられる患者団体の方たちと何度もお会いして、患者ご自身またそのご家族の方からお話を伺ってきた経緯があります。私が直接お話を伺った方のお話、これは品川区の方ではないんですけれども、その方の息子さんは、学校でいじめに遭って、同級生から突き飛ばされて壁に頭を打ちつけて、この病気を発症されました。病も気からですと。直近のデータで結構です。","respondent":"冠木指導課長","answer":"不登校のデータについては、３０日以上の欠席者ということを一つの基準として報告をしておりまして、平成２２年度ですと、小学校で４２名、中学校７・８・９年生で１２１名という報告をしております。","id":"exchange-051"},{"speaker":"阿久津委員","kind":"質問・要望","question":"その方が直接この病気かどうかというのは、安易に結びつけられるものではないと思いますけれども、そういう不登校の児童・生徒への対応として、病気の情報提供を行って、例えば医療機関への受診を勧めると、こういったきめ細やかな対応をお願いいたします。先ほど対応については今、しっかりとやられているということがありましたので、これは要望です。１６８ページ、学校ＩＴ化推進経費について。","respondent":"和氣学務課長","answer":"日々先生方がいろいろ集積したものが、そのまま例えば通知表に反映したりとか、指導要録に反映したりとか、テストの結果の集計がシステムでできたりとかということでいいますと、大変役に立つというふうになってございまして、これは実はほかの自治体がといいますか。","id":"exchange-052"},{"speaker":"阿久津委員","kind":"確認","question":"続いて児童・生徒たちが使用する電子黒板等のＩＣＴ化についてもまた伺います。これらはあくまでもツールであり、どう活用して指導に生かしていくのかということについて研究を重ねていると、そのようなご答弁をいただいておりますが、確認の意味で、学校の、特に子どもたちの学習で使用するこうした電子ツールの導入について、本区のご見解を教えてください。","respondent":"和氣学務課長","answer":"ツールとして使うための基本的な調べ学習の基本だとか、どうやって物事を組み立てていくかとか、そういうことを発達段階に合わせて使っていくことが、その発達段階を考えながら適宜にＩＣＴを使うということが重要だろうと私どもは考えてございまして。","id":"exchange-053"},{"speaker":"阿久津委員","kind":"質問","question":"練りに練られた学校ＩＣＴ化のロードマップというんでしょうか、来年度中に一定の方向を出されると今、ご答弁いただいたんですけれども、本区の言うようにわかったつもりになってしまうというのは理解できますし、本区としても、ＩＣＴ化というのを別に投げてしまったわけではなくて、真摯にこの課題に取り組まれているというのがよくわかりましたので、ビジュアルで理解しやすい。","respondent":"和氣学務課長","answer":"そういう意味で、そういうときに時を得て、子どもたちを遊ばせたり、地域の方に開放しておりますが、先日は映画会がここで開かれました。芝生の上に寝ころがって映画を見ようという、そんな形での取り組みもやっているところです。","id":"exchange-054"},{"speaker":"阿久津委員","kind":"質問・要望","question":"東京の中では一回芝生にしてまた戻す。手入れが大変で、通常の校庭に戻してしまったという例もあると聞いておりますが、第一日野小学校のシンボルとして、ぜひ続けていっていただきたい。できれば広げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"向委員","kind":"質問","question":"私からは、成果報告書のページ数で申し上げますと、１６８ページの教職員住宅維持管理費と、１７１ページの帰国児童・生徒等適応指導費、時間があれば、教育費の一番最後、１８０ページの幼稚園の講師採用経費についてお尋ねしたいと思います。帰国児童・生徒等適応指導費とありますが、これは具体的に概要を教えていただければと思います。日本人の児童のみ対象としているのか、そのあたりをお願いします。","respondent":"冠木指導課長","answer":"この事業の対象になっているのは、日本人で海外からお帰りになった児童・生徒、それから外国籍であるんだけれども、日本の学校に通っておられる児童・生徒の中のご希望の方です。","id":"exchange-056"},{"speaker":"向委員","kind":"質問","question":"地域的に区内でどこの学校に偏っているというか、まんべんなく学校に１人、２人はいるものなのか、どこかの学校に１０人、２０人とか、そんなにいるとは考えにくいですが、そういう傾向があるのかもあわせて教えてください。","respondent":"和氣学務課長","answer":"それから学校別で多いところで言いますと、八潮学園が一番多くて、小学校段階で１７名、中学校段階で１１名、続きまして多いところで言いますと、日野学園が多くて、小学校段階で１４名、中学校段階で１４名、続きまして伊藤学園で、伊藤学園は中学校段階が多くて１３名。","id":"exchange-057"},{"speaker":"向委員","kind":"質問","question":"１番目が愛知県で、２番目が神奈川県、ちょっと少なくて３番目に東京都ということで、現状はそういった現状ということで、中国籍の方が多い、フィリピンの方が多い、韓国の方とか、しっかりと把握しながら取り組んでいかなければいけない事業だと私も認識をしております。コストの面以外とか、何か特別な理由があるのか、実績があるＮＰＯ法人なので委託されたとか、そういう経緯を簡単に教えてください。","respondent":"冠木指導課長","answer":"ＩＷＣ国際市民の会に委託をお願いし始めたのは、平成９年からです。それまでこういった子どもたちへの指導というところでの実績があった団体ということでお願いした経緯があります。ほかにはそれに匹敵するような団体は当時なかったと聞いております。","id":"exchange-058"},{"speaker":"向委員","kind":"質問・要望","question":"こういった帰国児童の数とか、実際、外国から来た日本国籍を持っていないほかの児童の数というのは、世界の情勢とか、過去にはおそらくバブルが崩壊した後に、海外の日本企業が閉鎖して数が減ったとかいう実情もあったように私も記憶しておりますし、本当に現場との定期的な意見交換とか、問題改善に取り組んでいっていただきたいと思うんですが、こういったミーティングとか。","respondent":"冠木指導課長","answer":"実は私も自分が区内の中学校の教員だった時分に、ミャンマーからおいでになったお子さんがいて、そのとき私もミャンマー語を幾つか教えてもらったんですけれども、やっぱり学校の先生方と日本語指導員との十分なコミュニケーションが必要なのかなと思ってあります。","id":"exchange-059"},{"speaker":"向委員","kind":"質問","question":"先日も別の歳出の際に、母子手帳をいろいろな言語で扱ってあるとか、そういったお話も伺っていますので、品川区にいろいろな国籍、日本人だけではなくて、いろいろなゆかりのある子どもを増やしていってほしいなと私も期待をしております。１８０ページになりますが、この幼稚園費の中の講師採用経費というのは、具体的にどういった経費なんでしょうか。教えてください。","respondent":"冠木指導課長","answer":"この幼稚園講師につきましては、例えば入学当初の子どもたちが入った４月当初、子どもたちのケアのために非常勤として採用したり、運動会の練習、あるいはプール、それから外出をするとき、それからまれにですが、幼稚園の先生が体調を崩されたときの補充という形で。","id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"この人数というのは大体どれくらい採用されていて、臨時ということなので、長期間というケースと短期間、数日間というケースで採用されることがあるのか、臨機応変の対応をされているとは思うんですが、そのあたりがわかれば教えてください。","respondent":"冠木指導課長","answer":"公立幼稚園は９園ございまして、それぞれが年間の指導計画を進めていく中で、その季節季節で必要になってくる人材というのを大体園長は把握しておりますので、直近の資料ではないんですが、平成２３年３月現在ということで。","id":"exchange-061"},{"speaker":"向委員","kind":"質問","question":"採用に関しては、何かしら試験があるとか、先生方の質の問題といったら言い過ぎかもしれないんですが、そのあたりはどのように保持されているんでしょうか。","respondent":"冠木指導課長","answer":"非常勤講師と申しましても、ほぼ教員と同じ仕事をやっていただくものですから、資格としては基本的に幼稚園の教諭の免許、あるいは保育士の免許等をお持ちになっている方で、例えば一度退職されて家庭に入っておられて、少し子育ても落ちついたのでもう一回仕事をしたいとか。","id":"exchange-062"},{"speaker":"向委員","kind":"質問","question":"続けて成果報告書１６８ページの教職員住宅維持管理費について少しお尋ねしたいと思います。いずれの建物も古いということでよく伺っております。ゆたか教職員住宅が昭和４８年、伊藤教職員住宅のほうが昭和６３年ということで伺っているんですが、ここ一、二年の事務事業評価を見ました。毎年決算で上がっている維持費については、どのような使い方をされているのかを簡単に教えてください。","respondent":"冠木指導課長","answer":"住宅の戸数ですけれども、ゆたか教職員住宅については、所帯用が１４戸、単身用が１２戸の２６戸です。伊藤教職員待機寮の一部分を教職員待機寮ということで使っているわけですけれども、そこは所帯用が６戸、単身用が６戸の１２戸です。","id":"exchange-063"},{"speaker":"渡部委員","kind":"意見","question":"成果報告書１６９ページ、プラン２１。毎回聞いています選択制のことについて１０分聞いてまいりますが、その選択制を聞くにあたりまして、今回も平成２４年度新入学時、これは小学校のほう、新入学児童用の学校案内を見させていただきました。完全に学校にお任せで、１回つくって、次にまたどういうふうにつくろうかと考えているのが、その辺だけ一つお聞かせください。","respondent":"和氣学務課長","answer":"今までは私どもである意味ではお仕着せといいますか、こういうフォーマットでやりなさいということで進めてまいったんですが、なかなか学校の伝えたいことをちゃんと伝えられない、もしくは学校がきちっと自分のことをアピールできないのではないかということで、今年。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"来年度、また出ましたら、来年度のこの機会にご質問します。そもそもこの通学区域というものが、この新たなもの、私も４年前から質問させていただいていますが、例えば通学区域が変わることがあったと思います。時代の流れ、子どもたちの増減等により。今の通学区域はいつから生かされているものなのか。逆にその前、２つ前変更されたのがいつぐらいなのか、わかれば教えていただけますでしょうか。","respondent":"和氣学務課長","answer":"通学区域は規則等で定めているわけではないので、一番古いものはいつ定まったかというのは、大体昭和３５年から昭和４５年の間に固まったという形でしか、申しわけございませんが、ご回答できません。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"この通学区域なんですけれども、伺いましたら、昭和３０年代から始まりまして、昭和６０年代にかけては途中いじりがあって、それ以来、二十数年このままということで、区内の人口動向を見てみますと、地域偏差というのが出てきています。学事制度審議会において今後の予測もされている中で、この地域は子どもが減っていくぞ、この地域は子どもが増えていくぞというような記載があった。","respondent":"和氣学務課長","answer":"特に今、子どもが増え続けているということがありまして、私ども学区域についても、見直しも含めて検討してしなければならない時期には来ているのかなと思いますが、人口動向がまだまだ定まってございませんので、慎重に考えていきたいと考えています。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"荏原の一丁目１番、一丁目１番の１から４、その下、一丁目１番の３６から３８、これは第一日野小学校。しかもブロックが違う。指定校変更というので行けるんだというのも毎回伺っていてわかるんですけれども、選択して、あなたのブロックは選択できませよと戻って、また指定校変更するのではなくて、狭い品川区ですから、４つのブロックを僕は本当に外してもいいのではないかなと思います。前も伺いました。","respondent":"和氣学務課長","answer":"どうしても線を引きますとそういう矛盾が出てしまいます。これから人口の分布状況もありまして、学校が足りなくなってしまうというのが一番大変ですので、そこも考えながらブロック、学区域について、全般的な様子を見ながら考えさせていただきたいと考えております。","id":"exchange-067"},{"speaker":"渡部委員","kind":"意見","question":"地域は地域でなるべく自分たちの近所の学校に通ってもらおうと、地域は地域で逆に頑張っています。ある意味選択制が反面教師に、反面教師という言い方はおかしいんですけれども、あるがために近所の子どもたち、自分たちの近所の学校に行ってもらってと頑張っていますから、だんだん数が減ってくると僕は思っています。ぜひこの先、検討を進めてください。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"山内委員","kind":"質問・要望","question":"１６８ページの教育指導費の中から質問しますけれども、先日、台風１５号が上陸しました。その親御さんから、どういうことなんでしょうかということで私のほうに寄せられたものですから、そのあたりを教育委員会のほうに問い合わせました。これは台風が来るという予測のもと、そういった判断というものを教育委員会のほうで統一できないのかということをお尋ねさせていただきたいと思います。","respondent":"冠木指導課長","answer":"今回の台風１５号の対応について、学校の判断ということでございましたけれども、学校の判断は当然現場の校長が責任者ですので、優先されるという基本的な考え方は私どもも持ってあります。","id":"exchange-069"},{"speaker":"山内委員","kind":"意見","question":"現場の判断は大変重要かと思うんですけれども、それはそれでわかるんです。そうなると、やっぱりそこは保護者の方も何でというような、それが説明がちゃんとできればいいんですけれども、説明がされないと、何でうちの学校だけ休校なのかな、何でうちの学校の子だけ午前中登校なのかなという、その統一がされないというのは、私はあまりいい傾向ではないのではないか思うんだけれども、どうなんでしょうね。","respondent":"冠木指導課長","answer":"先ほどもお答えいたしましたが、各学校それぞれの立地条件といいますか、それから通ってくるお子さんの通学範囲、通学路の状況が全部違いますので、もちろん私ども教育委員会として、子どもたちの安全を第一に指示はしますが。","id":"exchange-070"},{"speaker":"山内委員","kind":"質問","question":"そうなりますと、現場の判断ということであれば、これはまた逆の考え方をします。ほかは教育委員会からの指示のもと、その学校が午前中だけ登校されたということであるのならば、今、課長がおっしゃる現場を第一に優先的に考えるということであれば、すべての学校の指示を学校長の指示のもとやっていくという、そういった形での統一というのはできないのですか。","respondent":"冠木指導課長","answer":"常々校長には臨機応変にその場その場できちっと判断ができるように指導していますけれども、私どもとして、現場を預かる校長ももちろんですが、教育委員会としても子どもたちの安全の確保ということは重要なことですので、一定の指示、基準といいますか。","id":"exchange-071"},{"speaker":"山内委員","kind":"質問","question":"学校側と教育委員会側との意見の統一というか、そういうのはどうなっているんですか。","respondent":"冠木指導課長","answer":"今回の台場地区の学校におきましても、五反田地区の学校にいたしましても、事前に私ども協議をして、一定の方向性を校長と共通理解した上で判断をしています。","id":"exchange-072"},{"speaker":"山内委員","kind":"質問","question":"戻ります。休校を判断した学校、それから午前中だけの登校を判断した学校、これは教育委員会としっかりと連携をしたもとで、今回、すべての判断が下されたということでよろしいのか、最後にそこだけ伺います。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおりです。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"成果報告書の１６９ページ、小中一貫教育推進経費のところでお伺いします。小中一貫教育について疑問がたくさんありますので、幾つも質問しますが、答えてください。この理由と、子どもの成長発達に合ったものなのかどうか、これが１点です。中学校教育を小学５年生まで引き下げていることについて、内容を教えていただきたいのと、あと小学校段階で教科担任制や定期テストが必要な理由をお聞かせください。","respondent":"冠木指導課長","answer":"これは中学生だけではなくて、５年生、６年生の段階からそういった子どもたちに勉強の手法も含めて学ばせていくということが必要であろうというところで、定期テストを５年生、６年生で実施しています。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先日、発達心理学の複数の先生のお話を伺ってきたんですけれども、この中で強調すべきは、本来、小学校、中学校は別々の学校であり、ギャップがあり、戸惑いがあるのは当然であると。私はこの品川区が小学校と中学校を区切らないで、続けて連続をしていくということが、今、お話しした発達論から見てどうなのかなと思っているんですが、この指摘に対しての見解をお聞かせいただきたいと思います。","respondent":"冠木指導課長","answer":"そして子どもたちが中学校に入って授業を受けるときに、先生が変わることによって適応できないという状況も過去にはあったわけですから、そういうことではなくて、５年生から教科担任制をやることによって、社会に出ていけば、行ったところ。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５、６年生に中学生らしさを早期に求めるのではなく、小学生時代を小学生らしく活動を行う、このことが大切だと思っています。発達論から見て、４・３・２制、いろいろ考えはあると思いますけれども、成長発達に合っていない面もあると思います。いろいろな考えが出ているんだと思います。そういった意味では多くの人の意見を聞きながら、立ち止まって見直していく必要があると思いますが、いかがでしょうか。","respondent":"冠木指導課長","answer":"品川区では、入学するお子さんについても、他区では知りませんけれども、非常に増えている。品川区の教育に魅力を感じて、品川区に越してきていただいている保護者の方もかなり増えているという状況もありますので、私たちは自信を持って進めてまいりたいと思います。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問","question":"この間、ちょっと気になるのが保護者の評価です。区教育委員会のアンケート、学校教育施設に関する保護者アンケートの中では、義務教育を４・３・２制にすることについて、半数以上が否定的な意見を持っています。小中一貫教育はよい取り組みと思うかというところも、やっと半分の支持といったところでは、親の理解が進んでいないと思いますが、この点はいかがでしょうか。","respondent":"冠木指導課長","answer":"そういった親御さんの声も含めて、私どもの努力は報われつつあると感じております。","id":"exchange-077"},{"speaker":"金野委員","kind":"確認","question":"私のほうからは１７５ページの学校図書館運営費、まずこちらからお聞きいたします。ここに関連して、学校で今現在、行われているということを確認したいんですが、朝の読書運動ですね。こちらは現状どのようになっていますでしょうか。どの程度今、実施をされていて、例えば時間とか、曜日だとか、小学校、中学校の現状をまず教えてください。","respondent":"冠木指導課長","answer":"少し範囲を広くしまして、全校一斉の読書活動という形でお答えいたしますけれども、これは小学校、中学校とも全校やっているところです。その中で、朝の読書活動に取り組んでいる学校は、小学校は２７校、中学校は７校です。","id":"exchange-078"},{"speaker":"金野委員","kind":"質問","question":"今、時間と曜日ともどれぐらい行われているのかというのもお聞きしたんですけれども、次の質問と一緒にお答えください。時間と曜日をお聞きしなければちょっとわからないんですが、現状されている日数、時間帯、それによっては朝の読書を増やしていかなければ、あるいはとる時間を生み出していかなければと思うんですが、いかがでしょうか。","respondent":"冠木指導課長","answer":"は先ほど答弁漏れがございましたので。朝の読書に取り組んでいる２７校、中学校７校については、朝礼のある曜日は別としまして、そのほかの曜日については実施をしているです。","id":"exchange-079"},{"speaker":"金野委員","kind":"質問・要望","question":"朝の時間１０分から１５分、これは大変貴重な時間なので、学校運営の中でも、学校生活の中でもなかなかとりにくいというのはある程度理解ができるところかなと思いますが、何とかこれは頑張っていただきたいというところであります。そこら辺、学校ではどんなふうに本の選定というのはされているのでしょうか。","respondent":"冠木指導課長","answer":"先ほどお答えした後半の部分で、子どもたちの考える力をつけていかなければいけない。","id":"exchange-080"},{"speaker":"金野委員","kind":"質問","question":"続きまして１７０ページの特色ある教育活動経費、こちらをお聞きします。こちらは各学校の独自性を生かした活動として、各学校が必要と思われる教育活動をされているとイメージをしているわけですが、成果報告書では１１項目の活動が記載されていて、学校数も記載されているところもあればというところなので、これはどれがどういうふうに学校の特色なのか、この仕組みはどうなっているのでしょうか。","respondent":"冠木指導課長","answer":"特色ある教育活動ということでまとめたもので、ちょっとわかりづらい部分があったのでおわびを申し上げますが、考え方としては大きく３つございまして、１つは学校がそれぞれの学校の特色化を出していくということで、こんなことをやりたいというご提案を教育委員会が承りまして。","id":"exchange-081"},{"speaker":"金野委員","kind":"提案","question":"３パターンがあるということで、それでは自己提案型と言っていいんでしょうか。こちらはいわゆる予算的なものなんですけれども、上限というのはあるんでしょうか。活動によってはさまざま費用がかかるものもあるでしょうし、そうじゃないものもあるでしょうし、一概に予算の条件というのはあれでしょうけれども、そういうのはある一定のものがあるんでしょうか。","respondent":"冠木指導課長","answer":"その上で私どもが事務局、それから課長の面接、最終的に教育長の面接まである場合もあるんですけれども、そういった中で効果が上がる部分について、私どもで採用していくです。スタートはお金の部分についても提案をいただいております。","id":"exchange-082"},{"speaker":"金野委員","kind":"提案","question":"面接を経て、採用されたものに対しては予算を出してくださるというところで、わかりました。ですので、できるだけこの自己提案型の学校がやりたいというところには、ぜひ協力をしていただいて、面接を経てと段階を少し軽くしていただいて、活動の幅を広げてあげていただきたいと、このように要望して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１７０ページのまちの人々に学ぶ授業経費と、今ありました特色のある教育活動経費の中の有識者講演のところで伺いたいと思います。平成２２年度、まちの人々に学ぶの予算の内訳で、授業経費のところで、件数あるいは何人か、１回当たりの費用の基準がどのようになっているのか、この点を伺いたいのと、有識者の講演というのは、どのような形のものだったのか教えてください。","respondent":"冠木指導課長","answer":"まちの人々から学ぶ事業というのは、基本的に１回３,０００円ということで、大体各学校２０回程度のご案内をしています。件数につきましては、小学校が平成２２年度におきましては６２９回、中学校が２３７回、小中一貫校が１４０回の実施をしています。","id":"exchange-084"},{"speaker":"渡辺委員","kind":"提案","question":"その中で今、提案事業でご説明のありました特にキャリアのある方の活用、あるいは専門性の方という中で、こういった総論はまちの人々だと思うんですが、制度自体に段階とか区分けが、発展したがゆえにそろそろ必要になってくるのかなと思うんですが、この提案型を含めて、今どのようなお考えを持っているのか教えてください。","respondent":"冠木指導課長","answer":"今の制度で行きますと、そういった場合には、私どもの例えば研修会的な実施をする場合には、講師謝礼という形で基準に従ってお支払いをしている。これはそうすると、まちの人の事業のお支払いする額よりも一定程度高いお金をお支払いできるというふうに思ってあります。","id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問・要望","question":"大事なことを言い忘れました。というのは、その具体的な施策として、今、このまちの人々以外にも、スチューデント・シティやファイナンス・パーク、すべて先がけて品川区が取り組んできた理念に通ずると思っているので、その確認をしたいと思います。それを今後どのように、そういう世の中の流れというんですか、進んでいくのか伺いたいと思います。","respondent":"冠木指導課長","answer":"これからも引き続き地域の人であるとか、あるいは企業の方々のご協力を得ながら進めてまいりたいというふうに思ってあります。","id":"exchange-086"},{"speaker":"渡辺委員","kind":"確認","question":"そういう中で、現場の様子をちょっと確認したいんですが、今そういう中で、受け入れる学校サイトがある、そしてそういう専門性、法律や経済、環境などもありますが、何かしたいんだという思い、提供する側、申し出をする側、この２つの関係が大事になってくる中で、見聞きしたり、あるいは今、考えられる課題として、例えば授業時数や組み立て、時期によるもので。","respondent":"冠木指導課長","answer":"いざやってみるとなかなか難しいというふうにお感じいただいたというのは、非常に私としても、逆に言うと心強いお言葉をいただいたなというふうに思ってあります。","id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"仕組みの点で最後に伺います。それぞれ個別に弾力性を持って対応している、そういう中で、教育委員会がすべきことという視点の中で、判断は各学校がされるとして、その一歩前、実施前の段階で、今までもされていると思います。現在も校長連絡会等も含めてやっていると思います。ただ、それを制度化する時期も来ているのかなと思うので、このお考えを最後に伺いたいと思います。","respondent":"冠木指導課長","answer":"こういった取り組みを始める、そしてそれを深めて続けていくというのは非常に大事なことだと思いますので、それにはやはり学校が何を求めて、子どもたちにどういうことを伝えなければいけないか。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問・要望","question":"よろしくお願いします。１７０ページの全国学力調査の全校実施、それと、１７３ページ、学校教育費。それから、学校教育費でいいんだと思うんですが、全般、教員の話になってしまいますが、小中学校の教員の人事権を２３区へという要望を出しているということなんですが、その人事権を置くということへの必要性、重要性と、それへの現在の展望をお尋ねいたします。","respondent":"冠木指導課長","answer":"全国学力調査については、ご存じのように、平成２２年は抽出調査で行われました。品川区は抽出されなかった学校についても予算措置をしていただきまして実施をしたところです。状況ですが、そういう状況ですので、これは全国的に順位とか、そういうことは出ません。","id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"考える力、発展する力云々というお話がありましたが、そういったことの流れの中で、日野学園が夏に休業中の勉強合宿をされているということなんですが、これ、予算上ちょっとどこに出てくるのかわからないのですが、そのことで、その費用はたしか大学生などお手伝いの方の費用だったような気がするんですが、それは日野学園の正規の授業以外のいわゆる力をつけるためのものだと伺っています。","respondent":"冠木指導課長","answer":"ほかの学校の学力向上策、勉強合宿について先に申し上げますけれども、勉強合宿については、この日野学園の実施状況については、かなり成果が上がっている、保護者の声も大きいと、評価も高いという状況ですので。","id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"それをして正規の授業プラス力をつけるための日野学園のほうでやられている、そのほかの中学校で、今、広げるというお話がありましたが、合宿ではなくて、夏休みに正規の授業ではなくて先生が声をかけて補習をしたりとか、あるいは学校として組織的に中学校は今週１週間は英語と数学と国語、１時間ずつやるとか、そういった夏季講習というか、補習についての取り組みが組織的に行われているところや。","respondent":"冠木指導課長","answer":"合宿以外のところですけれども、これは小中学校全校で、今、中学校というお話でしたけれども、小学校も含めて全校でサマースクールを実施しておりまして、授業時数以上の部分で取り組んでいるところです。","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"受験生チャレンジ支援、東京都の施策で、福祉部局でやられているもので、中学３年生、高校３年生が塾に行ったりする費用を借りられると。品川区では、就学援助を受けている方が中学校でいうと３０％を超えているというところから、このような受験生チャレンジ支援貸付事業を中学校のほうでぜひ生徒や保護者の方に周知していただきたいと思います。","respondent":"和氣学務課長","answer":"この制度については生活福祉課のほうでやっていますので、生活福祉課を通じまして各学校に周知をしています。","id":"exchange-092"},{"speaker":"高橋委員","kind":"質問・要望","question":"書類はちょっとどこで配るかわかりませんが、受付のほうは福祉系のところでやられているということなので、すみません、ちょっと款がまたいでしまったかと思いますが、そういったことで、学力の格差につながらないような方策が幾つかそうやってありますので、学校のほうでフォローしていっていただきたいと思います。","respondent":"平澤生活福祉課長","answer":"受験生チャレンジ支援貸付についてお答えいたします。本年度から名称が変わりまして、受験生チャレンジ支援貸付となりましたが、８月末現在の実績で５５件の申請がございました。","id":"exchange-093"},{"speaker":"吉田委員","kind":"質問","question":"成果報告書の１７７ページ、学校保健費の歯磨き指導指導法研究委託についてと、１７１ページの和楽器による音楽教育経費と、できれば、１７１ページのすまいるスクールについてお尋ねしてまいります。初めに、１７７ページ、歯磨き指導法研究委託ですが、小学校費のみですけれども、中学校費にはありませんが、そのわけを教えてください。","respondent":"和氣学務課長","answer":"この事業につきましては、小学校２校を今対象にしまして実験的にやっているですので、小学校費だけになっているところです。","id":"exchange-094"},{"speaker":"吉田委員","kind":"質問","question":"区内の歯科医師の方数人にお話をお伺いしてまいりましたが、小学校１年生から中学１年生の間は、永久歯と乳歯が混在して、とても歯が磨きにくいと。特に生え立ての永久歯は虫歯になりやすいとお聞きしてまいりました。中学校二、三年になりますと、統計的に全く虫歯がないお子さんと、虫歯ばかり多いというお子さんに二分する傾向があるというお話もお伺いしました。そのようなことをどのようにお考えか。","respondent":"和氣学務課長","answer":"これまでは学校歯科医が学校で講演をしたりとか、個別指導をしたり、歯科健診のときにお話をしてくださったりしていたんですが、特にこの小学校の歯磨き指導というのは、２校で毎日５分間、子どもが全員一斉に歯磨きをするという、そういうことを実施して歯磨き習慣をつける。","id":"exchange-095"},{"speaker":"吉田委員","kind":"質問・要望","question":"小学校で試験的というお話ですけれども、できれば中学校でも歯磨き指導法の研究委託を取り入れていただきたいと。やっぱり健康は食からとも言われておりますし、忘れがちな歯の大切さを学校という集団の中でしっかりしたプロの歯周ポケットのブラッシングの仕方などをこれからご指導していただきたいと思いますが、ご意見をお願いします。","respondent":"和氣学務課長","answer":"さらに歯科医師会とも相談しながら、いい啓発方法について考えてまいりたいと考えていますし、施設的にも鏡などを増やして、歯磨きができる環境を整備しています。","id":"exchange-096"},{"speaker":"吉田委員","kind":"質問・要望","question":"前向きなご答弁ありがとうあります。楽器の種類や実施方法などの検討とありましたが、私、個人的なんですけれども、琴は選択はとてもいいんじゃないかと考えています。小さいお子さんでも弦をしっかり押さえれば音階にもなりますし、ここでお聞きしたいのは、各学校を回していらっしゃるみたいなんですけれども、その期間を教えていただきたいんです。お願いします。","respondent":"冠木指導課長","answer":"和楽器の指導で、琴であるとか、鼓であるとか、そういったものを巡回をしていくという形をとらせていただいておりまして、期間については、１年を通して巡回をしていくという形をとってありますので、特にその一定の期間というのは。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問","question":"３時間という音楽の時間でやっていらっしゃるそうなんですが、私はとても短いなと思うんですよね。せっかく日本の伝統に触れるチャンスですので、１校１校もう少し長く時間を置いていただきまして、お子さんができたという少しの達成感を感じてもらえたらいいなと私は思っておりますが、その辺はいかがでしょうか。","respondent":"冠木指導課長","answer":"ですから、この和楽器の授業で琴の授業については、これは基本的なベースということで各学校進めてまいりますけれども、そこから発展する部分については、また別の応援の仕方があろうかなと考えておりますので、委員のおっしゃるように。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問","question":"一応、琴のお値段なんですけれども、大体９万円ぐらいから１５０万円ぐらいですよね。頑張ってください。すまいるスクールについてご質問いたします。すまいるスクールは学童クラブを発展させたものとお伺いしておりますが、改めて学童クラブとの違いや特徴などを教えていただけますでしょうか。","respondent":"齋藤庶務課長","answer":"特徴ですが、教育的な要素ということを多分に含んでおりまして、勉強する時間、地域と連携したお茶やお花、将棋、囲碁といったような講座を設けまして、伝統文化を子どもたちに伝えているです。","id":"exchange-099"},{"speaker":"吉田委員","kind":"意見","question":"たしか学童クラブでは、国の基準で１人当たりの占有面積がありまして、定数の弾力化は難しいと認識しておりますが、すまいるスクールでの１人当たりの占有面積はどうなっているのか、その点はクリアされているのかをお教えください。","respondent":"齋藤庶務課長","answer":"ただ、実際に参加しているお子さんの数で割り返すと、３８校中２１のすまいるスクールで達していると。学校ですので、グラウンド、体育館、特別教室も活用しておりますので、この基準を大まかな上ではクリアしているというふうに考えております。","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"すまいるスクールは、親にとって大人の目があり、防犯カメラや電子錠など守られた場所で安心して子どもを預けられるところなので、これからも頑張っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"本多委員","kind":"質問・要望","question":"学校改築、完成したときに、日野学園のときに近隣に配慮し過ぎて、設計変更もしたり、完成したら今度は廊下側の窓をあかないようになど、近隣に配慮しまして、今年の夏、すごく暑くて、去年もそうですが、児童・生徒に熱中症が出てしまって、その対策はもうやっていただいて窓があくようにはなったんですが、近隣に配慮し過ぎだなという感がありますので、今。","respondent":"冠木指導課長、齋藤庶務課長","answer":"しかしながら、そういった状況があったことは私も確認をしていますので、そういった部分については、引き続き、これ、未来の子どもたちですので。第三日野小学校で、南校舎、道路側の窓、これは近隣の方からプライバシーを配慮してほしいということで、目隠しのシート張りをしております。品川学園、渡り廊下があります。ここの渡り廊下を同様な理由で窓を少し小さめにしています。","id":"exchange-102"},{"speaker":"本多委員","kind":"質問・要望","question":"教科書なんかにつきましては、品川区小中一貫教育要領も平成２２年５月１日に改正されて、歴史や我が国の領土問題が明記されておりますので、大変充実してきているなと思いますので、ぜひその辺も考慮しながら進めていただきたいと思うんですが、あと、出版会社も含めまして、ニッポニアニッポンというトキの生息のこととかが、最近出なくなってしまったのが非常に残念だなと。","respondent":"冠木指導課長、齋藤庶務課長、安藤文化スポーツ振興課長","answer":"それからあと、いろいろと教科書のことであるとかご意見をいただきましたので、踏まえて対応してまいりたいというふうに思います。この件につきましては、教育委員会では所管しておりませんので、どの学校が一般開放できていて、できていないかは私どもでは把握しておりません。ただいまのグラウンドの件に関しまして、一応、私ども地域スポーツ開放をしている関係上、そういう近隣との関係で摩擦といいましょうか。","id":"exchange-103"},{"speaker":"本多委員","kind":"質問","question":"学校のマナーのことで、１つ質問させてください。私、ＰＴＡのある方からお手紙をこの平成２２年度のことでいただきました。それで、帰るときに、「校長先生、ありがとうございました」と言って帰るんですね。それで、校長先生がかわいそうだというお手紙をいただきました。これは全校の校長に教育委員会からフォローするべきだと思うので、その必要性を答えてください。","respondent":"齋藤庶務課長","answer":"今初めてお聞きいたしました。事実として把握してございませんでした。同様なことについては、今後対応してまいろうと思います。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、成果報告書１７６ページの学校給食費についてお伺いしたいと思います。区としても、先日の６月の請願審査の中では学務課長が、手づくり給食を基本とする姿勢に変更は全くないということで答弁されていますけれども、全面委託となったこれからも完全手づくりを守っていくということで確認させていただいていいか、このことをお聞かせいただきたいと思います。","respondent":"和氣学務課長","answer":"給食の調理代行というのは、調理を代行するだけであって、私どもの給食に対する考え方を変えるものではございません。このため、基本的に手づくりということについては遵守するということで契約をしています。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"完全手づくりでこれからもいきますよということは、どこかに明記されているかどうかというのをちょっとお聞きしたいんですが。","respondent":"和氣学務課長","answer":"契約の際にも、手づくりでいくというのは条件に入ってありますので完全手づくりでやる。ですから、逆に言いますと、調理代行が勝手につくってもらっては困るということです。私どもが指示したとおりにつくっていただく、そのことが前提で契約しています。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"完全手づくりということが明記されている。これから先も完全手づくりというのは担保されていくということで確認させていただいてよろしいですね。","respondent":"和氣学務課長","answer":"調理の手順書も含めまして私どもは調理代行に提供していますので、いつ、どういうふうにだしを入れなさいも含めまして細かく指示をしていますので、手づくりでやっていくことに変わりございません。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、栄養士からの指示というところで学校給食の調理がされるわけですけれども、そのところで直営であれば調理師がそこをチェックできるというところが、この民間委託というところでは、栄養士の指示をそのまま受け入れるということになるので、栄養士がそこのところをしっかりと守っていくというところがないと、なかなかそこの担保というのが難しいのではないかなと思うんですけれども。","respondent":"和氣学務課長","answer":"この料理はこうつくりましょう。それから、栄養士も含めて反省会をやって、献立反省会等もやります。実際にあと、栄養士がいないところは栄養補助職員とか、他の職員が実際に確認もします。ということで、担保はできるというように思っております。","id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"足立区の例では、１４年かけて全校が民間委託されたところで、委託料を削減するという交換で、献立を複雑にしないですとか、手づくりのジャムやカスタードクリームとかはつくらないとか、手のかかった献立を変えていくというような、そういう交換条件が出されたということなんですけれども、そういうことは品川区ではこれからはされないということでよろしいでしょうか。","respondent":"和氣学務課長","answer":"ご心配のようですが、しないという前提で進めてありますので、繰り返しの答弁になってしまいます。","id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、これ、学校給食における食中毒の手引きというのを見ましたら、学校栄養職員を衛生の管理責任者とすると、現に栄養職員がいないところは、調理師資格を有する学校給食の調理員等というふうなことでなっているんですが、この衛生の管理者というところ、栄養職員がいないところの管理責任者というのは、品川区ではどうなっているのでしょうか。","respondent":"冠木指導課長、和氣学務課長","answer":"現在の学校栄養士の数ですけれども、小学校が１５名です。それから中学校が７名です。国基準では３校に１名という基準なんですが、東京は２校に１名という基準でやらせていただいて、私どもはそれで栄養士が２校をしっかり見ていただいて、それ以外に非常勤職員なり、栄養補助職員を十分活用して。","id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、学校栄養職員のいない学校というのは、この衛生の管理責任者というのは、実際はいないということになるのでしょうか。","respondent":"田村教育次長","answer":"先ほど来、学務課長がお話ししているのは、栄養士は２校に１校配置、それで、給食業務が調理代行に来年４月に全校委託しますので、区の職員で、給食経験があって、さらに栄養士資格を持っている方もいますので、それを給食業務補助という形で。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が見ているのは、これ、学校給食における食中毒防止の手引きということなので、学校給食のことについて書かれているものだと思うんですけれども、ということは、栄養職員がいないところは、かわりに調理師をされていた方が配置されて、そしてそういう業務を行っているということで考えていいのでしょうか。","respondent":"田村教育次長","answer":"２校に１校の栄養士の指示に基づいて、給食業務の人がその対応をしているという形です。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今は過渡的なところでそういう形で配置をされていると思うんですが、２３区の中でも民間委託されたところは、すべて栄養士が配置されているということで聞いているんですけれども、そういう点では、本当にしっかりと民間委託業者を安全な給食を子どもたちに提供するというところで衛生管理をしていくという点で、そういう仕組みが必要なのではないかと思うんですけれども。","respondent":"和氣学務課長","answer":"既にもう残り４校になるぐらい代行は進んでおりまして、その中でしっかり衛生管理していますので、今の体制をさらに充実させるという形で対応したいと思います。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１つお聞きしたいのが、この民間委託を導入するに当たっては、財政効率ということを１つの大きな導入の理由ということで述べられていたと思うんですが、先日の６月の議会のところの議事録を読みましたら、学務課長の答弁で、委託にした場合、シミュレーションでは１校当たり２億円以上の安上がりになるということがありますということで言われているんですけれども、これ。","respondent":"和氣学務課長","answer":"申しわけございません。誤りです。失礼いたしました。１校２億円ということではなくて、最終的に平成２４年度で３億３,０００万円ほど経費が削減できるということで、途中経緯が全校で２億円を、私、１校２億円と言ってしまいまして、大変失礼いたしました。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結局は、全校で導入した場合は、３億３,０００万円ぐらいの予算の削減になるということでしょうか。それが二四、五％ということになるのかについてもお聞かせいただきたいと思います。","respondent":"和氣学務課長","answer":"実際いろいろな経費がかかっていますので、単純には差し引きはできないと思いますが、おおむね３億３,０００万円ほど経費を浮かすことができたというふうに考えております。","id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、チーフやサブチーフでも二十数万円とか、パートの方ですと、本当に１０万円前後という、そういう賃金で働かざるを得ないというところで、これが今、不景気だから成り立つという部分があるんじゃないかなと思うんです。そういう点では、ぜひとも私はそういう中でも質を落とさない基準をしっかりと守るというためにも、直営をこのまま一部残していただきたいと思うんですが、いかがでしょうか。","respondent":"和氣学務課長","answer":"現在、順調に代行が進んでおりますので、このまま経緯したいというふうに考えております。","id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうは、１６９ページの教育指導費の中の教育センター運営費、そして１７３ページの社会教育費の中の図書館経費の中でお聞きしたいと思います。初めに、１６９ページの教育センター運営費ですけれども、その中に維持運営費、また教育相談事業費、そして調査研究事業費というふうに載っておりますけれども、この内容を教えていただきたいと思います。","respondent":"冠木指導課長","answer":"それから調査研究につきましては、教員向けの実技研修であるとか、教育相談研修を実施しておりますので、そのお金ということになります。","id":"exchange-117"},{"speaker":"山元委員","kind":"質問・要望","question":"実際この相談内容というんですか、具体的にどういうことが相談されたのか、また、どういう方たちが来たのか、世代別で中学生の方たちなのか、そういうことも教えていただきたいと思います。近年、傾向性として、こういう問題のご相談が多いということがあれば、またそちらも教えていただきたいと思います。","respondent":"冠木指導課長","answer":"この２,６６４件というのは延べ件数ですので、登録件数、主訴別ということでご案内してまいりたいと思いますけれども、学校生活にかかわる相談については４５.２％、それからご本人の性格であるとか、行動についてのご相談が約３０％、それから、家庭生活であるとか、知能。","id":"exchange-118"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、７人の先生方がいらっしゃるということですけれども、その先生たちというのは、どういう方たちなのか教えていただきたいということと、あと、このご相談なんですけれども、１組というんですか、その相談時間というのでしょうか、そういう時間がどのぐらいとっているのか。大体１日平均どのぐらいの方が相談にみえるのか。","respondent":"冠木指導課長","answer":"臨床心理士を目指して、少しまだ臨床時間が足りないという若手の方も若干混ざっておりますが、基本的に臨床心理士ということで対応しています。相談の時間は、これは長ければいいというものではございませんので、基本的に４０分程度が基本になってくるかなと思います。","id":"exchange-119"},{"speaker":"山元委員","kind":"質問・要望","question":"１日の人数聞きましたけれども、この先生方のローテーション、７人の方たちのローテーションというんですか、それは７人の中で１週間しているかと思うんです。その辺のローテーションを教えていただきたいということと、月平均お一人がどのぐらいご相談に当たるというか、会場にいらっしゃるのか教えていただけますでしょうか。","respondent":"冠木指導課長","answer":"勤務の考え方としては、中にお二人は月１６日勤務していただいておりますので、大体週４日入っていただく方がお二人、それから、週３日入っていただく勤務の方がそのほかという形になっています。","id":"exchange-120"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと計算すると、かなりの高価な、時間で計算すると高額な報酬になるかなと思いました。大変なお仕事かと思いますけれども、その分ぜひ希望のあるアドバイスをしていただきたい、そのように思います。１７２ページの社会教育費の中の図書館経費について伺いたいと思います。その反面、資料整備費が予算に対して今度は半分近くの金額になっていますが、その辺の内容も教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"予算編成の段階で１カ所に固まって入っておりました印刷費等をそれぞれの事業に応じたところに振り分けさせていただいて、今後の予算編成におきましては、児童サービスで使うものについては児童サービスのところで、そのそれぞれの事業で管理をしていこうということで。","id":"exchange-121"},{"speaker":"山元委員","kind":"質問・要望","question":"そのときの館長からは、とってもメリットはあるけれども、検討していきたいと、そのようなお話がありましたし、また、要望がないという、そんなお話も出ました。実際、１年たって、利用者の方からそういう希望といいますか、そのような意見が入っているかどうかを教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"今般、文化庁のほうから、９月１日決定で電子書籍の流通と利用の円滑化に関する検討会議というところから、図書館と公共サービスのあり方に関する事項というまとめが出されておりまして、今後、公共図書館においても、ただ、今後は電子書籍の発行元との利害調整とか。","id":"exchange-122"},{"speaker":"山元委員","kind":"質問","question":"過日、プレス発表に、大井町でもサービスコーナーで本の出し入れがあるかと聞きましたが、今後その計画がありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に、教育指導費に入るのでしょうか、防災訓練についてお聞きいたします。ここの伊藤学園なんですけれども、つくった際には一般開放を視野に入れているわけですから、来場する規模なども当然考えられた設計になっているはずと思っておりました。しかしながら、現在はモラルが悪いということなのでしょうか、この伊藤学園は、駐輪場は一般開放の方たちのためのものではありません。","respondent":"齋藤庶務課長","answer":"ただ、伊藤学園につきましては、狭隘な敷地でしたので、三、四十台、職員用の駐輪場しか確保できなかったです。設計上、伊藤学園につきましては、一般開放用の駐輪場も見込んでの設置が困難だったです。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"締め出ししているわけですから。ですから、もうちょっとやり方はあるんじゃないかなと思うんです。それならば、じゃあ、今後、学校建設、今もずっとやっていっていますけれども、これからも含めて、学校建築の場合、どういう考えをされるんですか。一般開放するという上で、敷地内にとれないから、じゃあ、一般開放のときの自転車置き場はつくらないという方向なんでしょうか。","respondent":"齋藤庶務課長","answer":"来年度竣工する豊葉の杜学園では、５５台ぐらい一般開放用の駐輪場は予定しております。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"それならば、今の考え方、それを、今建設しているところ、それから伊藤学園も含めて、はっきりと地域の方に言うべきだと思います。そうしないと、学校の対応が大変です。伊藤学園はこういう台数しかないので、一般開放のための自転車は使わないでくださいというところまで言わないと納得しないと思います。その件は、これからの方法についても同時にお伺いします。","respondent":"齋藤庶務課長","answer":"品川区２２キロ平方メートルということは、ディズニーランド２２個分です。３個分に１つは温水プールがあります。歩いても、泳いでも、ぜひ健康づくりということにご理解いただきたいというのが教育委員会としての考えです。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"これは非常に問題あるなというふうに思っています。職員のためのということも、あいているじゃないかと言われますよね。地域の方は、土日あいていたら使わせろというふうに言いますよ。そこも含めて、折り合いがつくような方法がもしもあるのだったら、今後ぜひ考えていただきたいなというふうに要望します。危険性と節電の関係、これからの考え方はどのような考え方でやっていきますか。","respondent":"和氣学務課長","answer":"私どもとしましては、今回、節電をしっかりやってくださいということですが、危険な場所はつくらないでほしいというお願いをしたんですが、どうも学校が一生懸命やり過ぎてしまって、私ども、実際に見に行って危ない箇所については電気をつけるように指導してまいりました。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"防災訓練、これ、答弁いただけるかどうかなんですが、今、防災訓練をすると、教えの中に机の下に隠れなさいと言うんですけれども、机がなかったらどこに行くのということで、非常に周りの環境を見た上での防災訓練という、そういう指導の方法がやっぱり必要だというふうに、今、マスコミ等でも騒がれているところですが、その防災訓練について、改善するのか、その一言だけお願いします。","respondent":"冠木指導課長","answer":"今回の３月１１日の大地震を受けまして、各学校全校で防災訓練の見直しをしたところです。","id":"exchange-128"},{"speaker":"伊藤委員","kind":"確認","question":"質問に入る前に、午前中の沢田委員の答弁の確認で、日本固有の領土の確認という話がありました。それが区教育委員会の見解だと聞きました。ならば、なぜそう明記する教科書を選ばなかったのか、その理由を端的に教えてください。お願いいたします。","respondent":"冠木指導課長","answer":"これは教育委員会の責任と権限において、それぞれの教育委員がそれぞれの見識でご判断されたというふうに思ってあります。","id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１点、先ほど中学生という話が出たんですけれども、この事業の本来の目的は、小学校の中で基本的な習慣を身につけて、それで自動的に中学校でもそのことをしていくということがメーンであると思っていますので、安易に中学生に拡大するというよりは、むしろ小学生のレベルできちんと歯磨きをする習慣をつけていくべきだと思うんですが、そのことについての答弁をお願いいたします。","respondent":"和氣学務課長","answer":"しかも、このモデル事業につきましては、集団でみんなで見合いながらやるというところで、しっかりと、逆に言うと、歯磨きを楽しむということも含めまして教えているところですので、ここで得られた知見をさらに拡大しながら。","id":"exchange-130"},{"speaker":"伊藤委員","kind":"意見","question":"それで、生徒指導対策費に関連してということになると思うんですが、３月１１日のときに、荏原平塚学園と、それから三木小学校がディズニーランドに行っていました。だから、３・１１でこれだけの教訓を得たわけなんだから、やっぱりそのことについては品川区の教育委員会としては１つのマニュアルなり、方向性を示していくべきだと思うんですが、お答えをお願いいたします。","respondent":"冠木指導課長","answer":"委員のご指摘のように、３・１１のときには、複数の学校が校外学習に行っておりまして、それぞれがその場その場で判断を求められるという状況がございました。今の三木小学校であるとか、荏原平塚学園についても同様です。","id":"exchange-131"},{"speaker":"伊藤委員","kind":"質問","question":"最終的な判断はもちろん現場に任されていることはわかるんだけれども、だけれども、品川区の教育委員会としては、地震や台風のときにはこうすべきであるとか、それから、その後のさまざまな事由が生じた場合には、生徒児童の安全を確保するために、基本はこうですよと、具体的な現場の責任は学校長で対応してくださいというようなことをしっかりと、これをもとにしてまとめていくべき。","respondent":"冠木指導課長","answer":"３・１１のときの校外学習ももちろんですけれども、各学校の対応にはさまざまな教訓がございましたので、今、委員のお話のような、それをどういった形で学校に伝えていくかというのは、私たちの１つの責務であるというふうに考えてありますので。","id":"exchange-132"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、学校の立地条件であるとか、それから、その学校がどういう地形的な状況があるかということについては、当然一概に言えないし、千差万別なんだから、その最終的な判断は学校長に任せるとしたとしても、もう少し言いますと、地域別にした基本的なマニュアルなりを具体的に落とし込んでいかないと、この３・１１の教訓はより生かせないということを痛感するんですが、いかがでしょうか。","respondent":"冠木指導課長","answer":"例えば、今回、帰宅困難ということもありまして、引き渡しの問題がありました。それに対応して代理人の引き渡しまで保護をする旨、そういったマニュアルを整備し直した。あるいは、引き渡しの場所については、いつもはグラウンドだけだったんだけれども、今度は教室でやりますよ。","id":"exchange-133"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"私のほうからは、１６９ページ、品川区研究学校について、それと１６９ページ、スクールカウンセラー派遣費、１７０ページ、１～６年生の英語科経費、そしてちょっとページ数がわからなかったんですが、性教育について、主に子宮頸がんワクチンについての教育についてお伺いします。よろしくお願いします。","respondent":"冠木指導課長","answer":"そこからそれぞれの学校の取り組みなども入れまして、研究テーマを設定して研究をしていただいているところですけれども、やはり私ども品川区がこれまで小中一貫教育を進めてまいりまして、より具体的で。","id":"exchange-134"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点、小中一貫校のグループでやられるということで、これは小中一貫校は小中一貫校で１校というふうになっていて、要は、予算の時期では、小学校が１０校ですね。それが１８校になっていたりしているので、その点をお伺いしたいので、そこを改めてお聞かせください。よろしくお願いします。","respondent":"冠木指導課長","answer":"考え方として、平成２２年度の研究学校として載っているのは、平成２１年、平成２２年の２年間の指定の後半部分の学校と、それから平成２２年、平成２３年の前半部分の学校があるということで、そこで相違は出てまいります。","id":"exchange-135"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"国が補助金をなくしても、区としてこれをやるべきだという強い気持ちでやられたと思いますので、ぜひ進めていただきたいと思います。この理由をお知らせください。それと以前、スクールカウンセラーについて、増員をしたほうがいいのではないかと、その必要性を考えれば、増員を行うべきではないかという要望をしましたところ、増員はしない方向だというご答弁でした。改めて区の見解をお聞かせください。","respondent":"冠木指導課長","answer":"ただ、人数を多くしてカウンセリングを同じ方について何回も何回もやるということが、それが果たしてカウンセリング効果が出てくるかというところについては、やはり一定期間置きながら、１週間なら１週間置いてカウンセリングを継続していくという手法のほうが。","id":"exchange-136"},{"speaker":"石田（慎）委員","kind":"質問","question":"わかりました。教育センターにも相談員がいる。よろしくお願いします。次に、１～６年生の英語科経費について。これも平成２１年度と平成２２年度の決算で約１５０万円の差がありますが、その辺の理由と、外国語指導助手、いわゆるＡＬＴですか、この方たちの雇用形態はどのようになっているのかお知らせください。","respondent":"冠木指導課長","answer":"お金の差異については、これは実績差ということでございまして、実績が多かった、少なかったということでの差です。ですから、前年の実績にあわせて委託契約していますので、そういった意味での差ということでご理解いただきたいと思います。","id":"exchange-137"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"決算の差が実績によるものだということですが、そうすると、平成２１年度と平成２２年度を比較したときに、平成２２年度のほうがこの英語教育についてより取り組んだという認識でいいのかお答えいただきたいのと、この委託契約でありますが、この委託契約の契約の内容についてお伺いしたいんですが、現場で実際に教えていただいている外国語指導助手、ＡＬＴの方に対して。","respondent":"冠木指導課長","answer":"１つ目の実績につきましては、当然、年度が変わりまして、平成２２年度のほうが子どもたちの数が増えていますので、学級増になってありますので、確実に増えているです。そこも含めてご理解いただければと思います。","id":"exchange-138"},{"speaker":"石田（慎）委員","kind":"質問","question":"委託契約、外国語指導助手の雇用形態について、これは担任の方が教育現場において、その場でやっぱり指示をしたいというときもどうしても出てくるのかな、そんな中で、指示ができない理由の１つとして、雇用形態が委託において契約をしているから、実際に現場で指導ができないという中で、やっぱり教育現場においては、直接ＡＬＴに指示をする必要性があると思うんですが、この雇用形態を変えて。","respondent":"冠木指導課長","answer":"この問題については、非常に悩ましい状況があることは事実でございまして、私も教員の出身なので、今委員のおっしゃるような状況というのがあってこそ、子どもたちの力がついてくるということも１つ認識としてはありなのかなと思ってあります。","id":"exchange-139"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひさまざまな視点で考えていただきたいと思います。平成２２年度、中学一、二、三年生、平成２３年度は７年生となっておりますが、学校における教育、まずどういう病気で、ワクチンはどういうものなのかなど、子どもに、また親御さんにも知ってもらうことが大事だと思います。保健所との連携も含め進めていただきたいのですが、区の見解をお知らせください。","respondent":"和氣学務課長","answer":"ところが、前日、大震災ということで、急遽中止になりまして、残念ながら開催できませんでした。その代替で、今、日程を調整しているんですが、なかなか日程調整がつかないのですが、保護者向けの講演会を開催したいと考えています。","id":"exchange-140"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１６８ページの教職員研修、１７０ページの市民科、１７５ページの学校運営費でお伺いします。例えば今、学校の中で市民科の授業で防災を取り上げていらっしゃるということで、また、３・１１以降、この市民科の中で、この３・１１を踏まえて、何か子どもたちへの教育、対応というんですか、これが変わったところがあれば教えていただきたいと思います。","respondent":"冠木指導課長","answer":"今回、３・１１を受けまして、各学校が避難訓練の形であるとか、マニュアルをよりよいものに変更いたしましたので、それにあわせた避難訓練を、今、随時実施しています。","id":"exchange-141"},{"speaker":"武内委員","kind":"質問","question":"伊藤学園での宿泊、以前は荏原第三中学校時代にもあったと聞いていますけれども、そういった実際に即した非常にいい取り組みだとは思います。釜石の奇跡。学校にも本当に負担がかかりますけれども、やっぱり今回の釜石のものを見たときに、学校で教えられたことを小学生、中学生が守ることで地域の人の命まで救ったという、これをぜひお願いしたいと思うんですけれども、それを一言お聞きしたいと思います。","respondent":"冠木指導課長","answer":"釜石の奇跡につきましては、私もいろいろ勉強していますので、そういった部分についても学校のこれからの指導に生かしていきたいというふうに思ってあります。なお、学校においては、登校直後であるとか、朝の始業前などの避難訓練なども、今、実施をし始めているところです。","id":"exchange-142"},{"speaker":"武内委員","kind":"提案","question":"ぜひよろしくお願いします。実は私、平成１６年の予算特別委員会で、子どもたちに対するヘルメットの配付を提案しまして、当時はあまりピンと来なかった部分もありました。今回の３・１１の大震災を受けまして、今年の３月１６日の予算特別委員会で改めてこれを提案しまして、そのときに市川教育次長だったんですが、いろいろな角度から検討しますということで第２回定例会、大変うれしく思っているんです。","respondent":"和氣学務課長","answer":"ですから、実際、訓練でも子どもたちはヘルメットをかぶって、地域に貢献するんだというような意識を持たせながら訓練をしたりもしています。","id":"exchange-143"},{"speaker":"武内委員","kind":"質問","question":"この方が、中にはこういうお話がありました。そうした中で、確かに今、品川区、中学校までお配りになったということは、ほかから見ると非常に先進的にやられて評価はするんですけれども、小学生についても、ぜひ早急にこれは検討してもらいたいと思うんですけれども、いかがでしょうか。","respondent":"和氣学務課長","answer":"先ほど申し上げたような趣旨で配ってありますが、防災用の頭巾については、さっきの火災の問題とか、いろいろ対応もできますということで、総合的に研究させていただきたいと思ってあります。","id":"exchange-144"},{"speaker":"松澤委員","kind":"質問","question":"２点お聞きしたいと思います。１点目は、成果報告書には書いてありません。学級編制について。「お父さん、お父さん、小学校ね、３５人学級になったんだよ」と言われました。ちょっと中学校まではわからなかったので、どうも聞いてみると本当らしいと、学級が増えたところがあるというので、それについて、小学校、中学校、法律的にも含めてどういうことで学級編制が変わったのかについてお教えください。","respondent":"和氣学務課長","answer":"それ以外に、東京都のほうが、中一プロブレムへの対応ということで、中学校１年生に関しては３９人ということで学級編制をする、３９人で１名の教員をということでやってありますので、それが中学校でもクラスが増えたという例になります。","id":"exchange-145"},{"speaker":"松澤委員","kind":"質問・要望","question":"小学校は３５人学級を選択してもいいということで、そうすると、また今、２年生も予算要望している。聞いたところによると、２年生でも予算要望する前からもう２クラスになっているところもあるように聞いているんですけれども、これ、来年度はどうなるのでしょうか。１年生が２クラスに増えたところが、来年また、１年生はなるけれども、２年生になったらまた戻すのでしょうか。","respondent":"和氣学務課長","answer":"失礼いたしました。それから、来年度に関してですが、一応、今の文部科学省の概算要求の一番の要求が、２年生も３５人学級にするための教員の増員ということになってありますので、国としても３５人学級にするということで動いているというふうに認識しています。","id":"exchange-146"},{"speaker":"松澤委員","kind":"質問・要望","question":"ですから、私が言っているように、１年も２年も、そうすると、今、２年もするなら、３年になったらまた単学級に戻すんですかという話になります。これを見ていても、１０５人というと３学級、１０５人を超えると４学級、そんな学級が１年、２年、４年、５年とある学校もあるんですけれども、これをどう対応するのか、しっかりとしたお答えをいただきたいと思います。","respondent":"和氣学務課長","answer":"ということで、私ども学務課、庶務課、指導課、３課で常に数を検討しながら、実際にシミュレーションをして、教室が足りるか足りないか、そのためにどう対応すればいいか、今のあき教室をどのように改造していくかとか、人口推計自体も、実はだんだん増えていって。","id":"exchange-147"},{"speaker":"松澤委員","kind":"質問","question":"そうしたら、その話は教育委員会の中ではもうしっかり事前に打ち合わせができているんだなというふうに感じたんですけれども、やはりそうすると、一般の学校でも、どこでも選択できますよという中で、超えそうなところはそれとなく学区以外のところから来ないでくださいとか、そういうふうな形で指導していくようになるのだろうというふうに思うんですけれども、その辺はしっかりと言えないですか。","respondent":"和氣学務課長","answer":"もう１つは、１つやったのは、昨年の品川学園、城南第二小学校、非常に増えていますので、品川学園の順位に上げたというのが１つ対策は講じてありますが、そういうことも考えながら、基本的に子どもたちに混乱をもたらさないように。","id":"exchange-148"},{"speaker":"松澤委員","kind":"質問・要望","question":"本当に今、学校にばらつきがあって、１学級２０人いない学級も、単学級の学校もありますので、その辺しっかりと教育の中で、学校の特色を出して選択できるような形にしていただきたいと思います。どうして書いていないのか。スチューデント・シティとファイナンス・パークの役割と、そして子どもたちにとってどのような役に立っているのかについて教えていただきたいと思います。","respondent":"冠木指導課長","answer":"平成２２年の決算書に載っていないのは、この年、八潮学園、それから城南中学校から品川学園のほうに引っ越しを、移動の事業をして、この年は子どもたち、ちょっと行けませんでしたので、それはまた今年から再開しましたので、そんな形で対応しています。","id":"exchange-149"},{"speaker":"松澤委員","kind":"質問","question":"大変失礼しました。子どもたちがこれに通う曜日というものは、どういう日を選んでやっているんでしょうか。普通の授業時間内にやっているのか、あるいは土曜日、日曜日も含めてやっているのか、その辺をお聞きしたいと思います。","respondent":"冠木指導課長","answer":"その前に学校で勉強を８時間ほどいたしまして、それで実際に品川学園のスチューデント・シティで６時間かけて授業をしまして、学校に戻ってまた振り返りの学習を１時間するという計画になってあります。","id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"こんなこともやはり学校が地域に開かれた、地域と一体となったきずなを深めるなんていう合い言葉ではないんですけれども、あるんですから、しっかりその辺も見てやってほしいと思うんです。その選び方について、当然、教育委員会ではわからないと思いますけれども、この辺、学校との連携はどのような話し合いをしているのかについて、１点お伺いしたいと思います。","respondent":"冠木指導課長","answer":"スチューデント・シティ、ファイナンス・パークの日程については、私どものほうから学校のほうに予定をお知らせする中で、学校のほうの希望も聞いて調整をしていますけれども、先ほど、引っ越しということがございました関係で。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"私は、教育指導費と教育費全般についてお伺いしたいと思います。品川区、公立中学校の中学３年生の進学実績についてお伺いいたします。教育委員会では、偏差値の高い都立高校や私立高校の進学校への進学実績が上がったという成果を言われているようですが、これは事実でしょうか。","respondent":"冠木指導課長","answer":"そういった子どもたちそれぞれの将来設計であるとか考え方、そういうようなところも含めまして進路指導していますので、そういった意味では、子どもたちの考えがより深まって進学をしている子どもたちは確実に増えております。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"中学３年生になると、その実態は本当に顕著にあらわれて増えております。学校の勉強だけでは不十分であり、到底私立や都立の進学校を受験する力が身につかないというお話を私はよくお聞きします。特に学力レベルが高い進学校へ行くには、高いレベルの教育をしている民間の塾で学ばなければ合格できないのが現状だと思いますが、この辺について何か見解をお聞かせください。","respondent":"冠木指導課長","answer":"しかしながら、品川区が今取り組んでいる教育によって、先ほども経済の学習であるとか、そういったところも出てまいりましたけれども、そういったことで、子どもたちがきちっと将来設計を描けるようになっている。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"中学３年生になると、大半の生徒が私立高校か都立高校を一般入試である受験をします。ですが、高レベルの問題は、品川区の公立中学校では教えていない問題が出題されています。ならば、受験する子どもたち、公立中学校でも公教育を塾が支えるということではなく、民間の塾と同様に、受験対策の勉強を教えるべきではないんですか。その辺についてご見解をお聞かせください。","respondent":"冠木指導課長","answer":"これについては、当然、私どもと同じ仕事をしている指導主事が十分に学習指導要領にのっとった問題であるかというのを確認している問題ですので、今委員のご指摘になったような事実はございません。確実に子どもたちに中学校で教えている中から出題がされているです。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"今、そういうふうにおっしゃいましたが、現実、私もいろいろな受験生にヒアリングさせていただきました。はっきり皆さん、こう言っていました。できませんと。ちょっとその辺。要は、習った問題が出ているということを、そうやって簡単に言うということは、ちっともそれを見ていないということではないですか。もしそれができるなら、もっと多くの子が受験して合格できてしまうんじゃないですか。違いますか。","respondent":"冠木指導課長","answer":"私が責任を持って、当時の各学校の試験問題については確認をしています。ですので、切り口は違います。ですから、ふだんの学習、基礎のトレーニングだけで解けるかといえば、それは選抜試験の一環がありますから、解けないという、難しいと思われるお子さんもいるかもしれません。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと見解が違うので、本来なら、もっと私は、指導課長、もっと子どもたちと向き合ってほしいと思います。でも、現実は、やはり一般入試ではほとんどいません。それが実情だと思います。それについてちょっとご意見を聞かせていただきたいのと、また、民間塾は進学指導をする資料をきちっと持っております。今の教員は、何を根拠に進学指導するんですか。それについてちょっとご見解をお聞かせください。","respondent":"冠木指導課長","answer":"だから、子どもたちは宝なのであります。ですから、そういった意味で、中学校の教員は全力を挙げて進路指導しておりますので、塾について私はコメントする立場にありませんけれども、それはご家庭の判断ですけれども、学校の教育は十分に機能しています。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問・要望","question":"何度も申し上げますけれども、そういうことをいつまで言っていたら、本当の子どもたちの教育の実態を見ていないじゃないですか。見られないですよ。いつまでもそうやってきれいごとを言ってどうするんですか。そういう子どもたちが上げているというのが事実じゃないですか。学力をつけさせることが先じゃないですか。そして、学力がついていなかったら、結局、就職できないじゃないですか。","respondent":"冠木指導課長","answer":"他区に負けない、他区以上の区の非常勤講師であるとか、習熟度別学習コースであるとか、学習支援のボランティアであるとか、そういうようなところを各学校に配置しまして、少人数の指導展開をして、そういった子どもたちについても十分に対応しています。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"みんな子どもたちは、できれば学力をつけて、授業も楽しくやりたいと思っていると思います。見回ってみたら、やっぱり解けない子もいます。今はどうですか、立たすこともできない、座らすこともできない、強く怒ってもいけない、こんな状態で学力が子どもたちがちゃんとつくんですか。そして中３になったら、いや、全然解けません。やっぱりきちんと競争社会と向き合うべきじゃないでしょうか。","respondent":"冠木指導課長","answer":"いろいろとご意見をいただきましたけれども、競争社会と向き合っていくということについては、私もその考えは１つあるかなと思います。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"今、実際、ご夫婦共稼ぎ、皆さん大変なんですよ。地域でもその子たちの悪い行動とかがあったら注意もします。もし何だったら、極秘でも、極秘ではできないのだろうけれども、１回模擬テストをやってみてくださいよ。なんでその本当の力を、皆さんの実力というものを１回把握しようとしないんですか。なぜですか。怖くて出せないのかわからないですけれども、それをしっかり申し上げて終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"南委員","kind":"質問","question":"１７１ページの保幼少連携推進経費に関してお尋ねしたいと思います。保幼少連携事業の目的、どのような内容で実践しているのか、参加状況、事務事業概要には「希望するところ」となっておりますけれども、参加状況がどうなっているのかについても伺います。","respondent":"冠木指導課長、吉岡保育課長","answer":"この事業につきましては、私どもが保育課と共同でつくりましたジョイント期のカリキュラム、これをぜひ品川区内の公立の、幼稚園は教育委員会の部分もありますけれども、あと保育園、それから私立の保育園、幼稚園にもご協力いただいて。保幼少交流事業の実績ですけれども、平成１９年度にモデル実施を始めまして、翌年度からは全区立保育園、幼稚園、それから小学校で実施しているところですので、それぞれの学校、幼稚園、保育園、交流をしていますので。","id":"exchange-160"},{"speaker":"南委員","kind":"確認","question":"そうすると、「希望するところ」というふうにはなっているものの、すべての公私立保育園、すべての公私立幼稚園、そして小学校ということで考えていいということですね。ちょっとそこを確認したいと思います。それから、それぞれの担当者が事前準備をしないとこれはできないというふうに思うんですけれども、その事前準備についてはどういうふうになっているのかについても教えてください。","respondent":"吉岡保育課長","answer":"基本的に今申し上げましたように、公立の幼稚園、保育園については、全園がそれぞれの小学校と交流をしていますので、平成２２年度の実績としては、公立の保育園は４０園、それから公立の幼稚園は９園ということで実施しています。","id":"exchange-161"},{"speaker":"南委員","kind":"質問","question":"地域の取り組みにちょっと話を伺ったので紹介したいと思います。一貫校と４つの公私立の保育園、１つの公立幼稚園、ですから、就学前の施設は５園、あと一貫校、小学校部分だと思います。したがって、こういう実態があるということをどこまで承知をして教育委員会サイドも、それから子育て支援課サイドも、どこまでつかんでこの事業を推進しているのかということについて伺いたいと思います。","respondent":"吉岡保育課長","answer":"今、委員がおっしゃられた事例が、どの学校あるいは保育園、幼稚園で、いつ起きた事例かは承知しませんけれども、一つ一つの事業を実施するに当たっては、小学校側の教員、それから保育園側の保育士、幼稚園の幼稚園教諭、それぞれが事前に十分な打ち合わせをし。","id":"exchange-162"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、連携推進ということで、そういう保育園の中で全面的な発達を求めてきた、そういう営みがこういうことで途切れさせてしまってはならないという心配をするわけで、私はですから、この時間と子どもたちの思いを、やっぱり期待を裏切ってしまうような、そういう場面があちこちあるのであれば、やっぱりやる必要はない、こういうふうに思いますけれども、保育園や幼稚園の中での指導員の。","respondent":"吉岡保育課長","answer":"さまざまなお話ございましたけれども、調査をしろというお話もありましたが、そもそも、そうすると、委員は、これをどういうふうにお知りになって、どういうふうに実態を把握されたのかということが私はよくわかりませんけれども、基本的には、何回も申し上げているように。","id":"exchange-163"},{"speaker":"南委員","kind":"質問・要望","question":"私は、やっぱり６年生のお兄さんやお姉さんが、小さな子どもに対してはきちんとした成功する、そういう場面を提供できることが大事だと思うんです。就学前の子どもにとっても、そういう姿を見て、期待やあこがれが広がっていくと思うんです。もっと一人一人の年齢に合ったやり方、そこをしっかり保育園でやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-164"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど、会派の向委員から、帰国児童生徒等適応指導費で、ＩＷＣの実績を評価して、さらに推進してほしいという要望がありましたけれども、これについて、私もそのことについて適正な運営費をということで、一昨年はアップしていたと思うんですけれども、今回の決算書では、前年度よりも５００万円ほど決算額が減少しているので、その理由をお伺いしたいと思います。","respondent":"和氣学務課長、冠木指導課長","answer":"日光光林荘の放射能ですが、私みずからはかってまいりました。日光と同等の数字が確認できました。ＩＷＣの適応の経費ですけれども、一昨年につきましては、対象のお子さんの数が通常の１.５倍おられまして、急遽その対応をしたということで、その前の年の決算は、少し数字的には高くなってあります。","id":"exchange-165"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。すまいるスクールなんですが、専任指導員は、今、各学校１名正規職員があると思いますが、職員の資格と平均年齢を伺います。生ごみのところでは、学校給食の廃食油リサイクル、現在どのように行っているのかお伺いします。図書館経費では、図書館で図書司書の配置をされているのは、１０館のうち何館あるのか教えてください。","respondent":"齋藤庶務課長、和氣学務課長、中元品川図書館長","answer":"すまいるの正規職員の平均年齢ですが、今年の４月１日現在で５２.６歳になります。全部で４０人いる中、５２.６歳です。廃油についてのお尋ねにお答えいたします。ただし、委託職員の中に何割か司書の者がおりまして、こちらで特に司書資格を求めているわけではございませんが、現在。","id":"exchange-166"},{"speaker":"井上委員","kind":"質問・要望","question":"図書館のところは、３割程度ということで、私が伺ったのは、１０館中何館に図書館司書が配置されているのかということでしたので、明確にお答えをいただきたいと思います。","respondent":"中元品川図書館長、和氣学務課長、齋藤庶務課長","answer":"失礼いたしました。正規職員の２人の司書については、品川図書館に配置があります。せっけんの件は、前にもご質問ありましたので存じ上げてありますが、今のこの廃油については、しっかりとリサイクルされてありますので。これは人事施策の問題ではありますけれども、平成２０年の本会議で、すまいるスクールの正規職員は、事業運営の要であり、学校と地域との調整役だと。","id":"exchange-167"},{"speaker":"井上委員","kind":"質問・要望","question":"図書館なんですけれども、１０館に必ず１人がいるということで安心しましたけれども、ここのところはしっかりと継続していただきたいし、あと、図書館でレファレンス業務や、いろいろな企画で地域の生涯学習の拠点になっていただきたいというふうに思いますので、そういったところでこれから工夫をされていこうと思うことがあったら教えてください。","respondent":"和氣学務課長、中元品川図書館長","answer":"先ほどと繰り返しになってしまいますが、基本的に私どもは今の方式で十分リサイクルはできておりますし、その中で子どもたちにもリサイクルの教育をしていますので、そういうお考えもございましょうが。ただ、その中で品川図書館本館には視聴覚ホールなどありますので、そちらで地域の方向けの講演会を無料で実施したり、映画会を実施したりということで、今後も引き続き努力してまいりたいと思ってあります。","id":"exchange-168"},{"speaker":"井上委員","kind":"質問","question":"図書館なんですけれども、今、子どもたちが遊べるスペース、本が読めるスペースを確保していただいているのはよくわかるんですけれども、そこが場所的な面積の関係で、そこはあっても迷惑がかかるということで、なかなか利用ができないという中で、杉並区では時間を分けて使うというようなこともやっていますが、そういったことの検討はいかがでしょうか。","respondent":"中元品川図書館長","answer":"今委員おっしゃったのは、杉並区で始められたあかちゃんタイムのことかと存じておりますが、こちらも検討してまいりたいと思います。","id":"exchange-169"},{"speaker":"若林委員","kind":"質問・要望","question":"１６９ページの品川区教育会助成金、これは私、あまり存じませんので、この教育会とはどういう団体なのか、あと、助成金の内容なんかもお聞かせいただきたいと思います。それからあわせて、見比べますと、予算に対していわゆる５７％の執行にとどまったということですので、その内容とともに、この原因も教えていただきたいと思います。それから、１７１ページの特別支援教育費です。","respondent":"冠木指導課長","answer":"サポート経費のほうは、巡回相談ということで各学校を回らせていただいて対応させていただいて、気になるお子さんについて確認させていただいているんですが、そこのスタッフの医師が減ったということで、額のほうは下がったです。","id":"exchange-170"},{"speaker":"若林委員","kind":"質問・要望","question":"教育会の詳しい話はちょっと聞けませんけれども、同額を補助するということは、会員の会費が例えば１００万円になったら１００万円を補助する、２００万円になったら２００万円を補助するということでどんどん膨らんでいく、また逆に減っていくという。それを確認します。特にこの教員のスキルアップについて、平成２２年度等どのようなことをされているかお聞きしたいと思います。","respondent":"冠木指導課長","answer":"ＮＰＯと委託の契約を交わす中で、介助員もいるんですけれども、学習支援員の研修、これについても充実をするようにということで、私どもと委託の前に調整して対応しているところでございまして、そういった事例については幾つか私ども知っておりますけれども。","id":"exchange-171"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、先ほど、英語科のＡＬＴのお話でもありましたけれども、雇用形態の問題が１つ横たわっているのかなというふうに、さっきの質疑を聞いていて思ったんですが、ここら辺の改善について、ＡＬＴとともに、もしそういう事実があれば、学習支援員の雇用形態についても、またぜひそこの中で課題に取り上げていただきたいということの要望が１つと、あと。","respondent":"冠木指導課長","answer":"学習支援員の委託契約の問題につきましては、私どもも課題の１つととらえております。引き続き検討している部分です。それからもう１つのほうにつきましても、十分な対応をしてまいりたいというふうに思ってあります。","id":"exchange-172"},{"speaker":"須藤委員","kind":"質問","question":"ページ１６８の教育指導費に関連して質問しますが、その前に、今までの委員の質問の中からちょっと感じたことで再質問させてもらいますが、渡辺委員の質問のときに、品川区の教育は国より進んでいるんだというふうに自負をしていますというようなお話があったので、それは自負をすることはいいこと、自信を持つことはすばらしいと思うんだけれども。","respondent":"冠木指導課長、齋藤庶務課長","answer":"地域の皆様に混乱を与えてしまったという部分があることは事実ですので、ここは私どもも反省点として、それぞれの校長との共通理解というような部分でさらにこういった緊急対応について。先ほど、本多委員のお話は、校庭開放ではなくて、地域開放、一般開放の話だというふうに理解しましたのでご答弁は控えさせていただきましたけれども、先ほどの伊藤学園の例をはじめ、各学校が抱える問題については。","id":"exchange-173"},{"speaker":"須藤委員","kind":"質問","question":"改めて教育指導費のところで聞かせていただきますけれども、児童・生徒が教科に興味を持つということ、あるいは好奇心を持ってということが、その教科を好きになったりしていく、あるいは、その教科の向上をしてくるということにつながってくると思うんだけれども、いかがでしょうか。","respondent":"冠木指導課長","answer":"子どもたちがまずその教科に興味関心を持って、それに意欲を持って取り組んでいくという姿は教育の中で一番望ましい姿であって、さらにその後、子どもたちが伸びていく原動力になるということは間違いないと思います。","id":"exchange-174"},{"speaker":"須藤委員","kind":"質問","question":"最近、金魚とドジョウの詩で有名になった詩人の詩に、「負ける練習」という詩があるんですけれども、ご存じでしょうか。","respondent":"冠木指導課長","answer":"勉強不足で存じ上げておりません。","id":"exchange-175"},{"speaker":"須藤委員","kind":"質問","question":"先ほど来、武道ということで、礼法をという話ですけれども、投げられて受け身をとってぶざまな格好を見せるということが、年間１０時間の間でどの程度続くのかなと。そして、それを拙速的にやると、事故につながったりというようなことが出てきてしまうので、非常にそのあたりが難しいと思うんですけれども、授業でやったことと、今度、部活につなげるという考え方はいかがでしょうか。","respondent":"冠木指導課長","answer":"武道の礼に始まって礼に終わるという考え方を十分に理解していただいた上で、子どもたちが興味関心を持って競技の部活につないでいく、競技活動につながっていくということは、望ましい姿の１つであろうかなというふうには思います。","id":"exchange-176"},{"speaker":"須藤委員","kind":"質問","question":"今の例で出てきたんですけれども、学校の中で、「気をつけ、礼」という、気をつけの姿勢というのは教えているのでしょうか。","respondent":"冠木指導課長","answer":"教えております。４月の初めの体育の時間、あるいは４月の初めの学年集会等々で、「気をつけ、礼」については、「回れ右」も含めまして指導しています。","id":"exchange-177"},{"speaker":"須藤委員","kind":"質問","question":"学校の卒業式なんかに行って、来賓のほうへ向かって礼をするときも、足を開いて礼をしている。やはり礼というのは見ていてきれいでなければいけないので、足を開いて礼をされると、何となく違和感が出てきてしまう。そういったマナーと礼法と一緒になってしまって、礼をするときに足を開いたまま礼をしてしまうのではないかなというような気がするんだけれども、そのあたりはいかがでしょうか。","respondent":"冠木指導課長","answer":"マナーキッズのところでも、きちんとした礼ができるように指導しています。","id":"exchange-178"},{"speaker":"須藤委員","kind":"質問・要望","question":"だから、先ほどの詩人じゃないけれども、間違ってもいいんだよ、「にんげんだもの」という詩が出てきているんですけれども、私は教育委員会では、間違ってはいけないんだよ、教育委員会だものというふうに思っていますので、今の教育改革はすばらしいと思うんだけれども、間違ってはいけない、子どもたちが育っている９年間というのは、その前の未就学児を見ても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/796486?Template=document&Id=1350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":117523,"voices":402}}]);
